async function bizGalleryOp226(run) {
  const err = document.getElementById("biz-gallery-err");
  if (err) err.style.display = "none";
  try {
    const data = await run();
    if (data && data.photos && state.user) {
      state.user.business = state.user.business || {};
      state.user.business.photos = data.photos;
      state.user.business.photoCount = data.photoCount != null ? data.photoCount : data.photos.length;
      state.user.business.hasPhoto = data.photos.length > 0;
    }
    state.bizGalleryV = (state.bizGalleryV || 0) + 1;
    const host = document.getElementById("biz-gallery");
    if (host && state.user) host.innerHTML = bizGallery226Html(state.user, state.bizProfileView && state.bizProfileView.home);
    return true;
  } catch (e) {
    if (err) { err.textContent = (e && e.message) || J226("That photo change did not save.", "Ese cambio de foto no se guardó."); err.style.display = "block"; }
    return false;
  }
}
function bizGalleryAdd226(input) {
  const file = input && input.files && input.files[0];
  if (!file) return false;
  const reader = new FileReader();
  reader.onload = () => {
    const slot = bizPhotosOf226(state.user, state.bizProfileView && state.bizProfileView.home).length;
    bizGalleryOp226(() => api("POST", "/me/photo", { dataUrl: reader.result, slot }));
  };
  reader.onerror = () => {
    const err = document.getElementById("biz-gallery-err");
    if (err) { err.textContent = J226("That photo could not be read.", "Esa foto no se pudo leer."); err.style.display = "block"; }
  };
  reader.readAsDataURL(file);
  return false;
}
function bizGalleryMakeCover226(i) {
  bizGalleryOp226(() => api("POST", "/me/photo/cover", { slot: i }));
  return false;
}
function bizGalleryRemove226(i) {
  bizGalleryOp226(() => api("DELETE", `/me/photo/${i}`));
  return false;
}

/* BUILD226-END */

function go(view, tab) {
  // Any navigation leaves Business Preview: the mode is a single
  // deliberate walk, and the admin lands back on the normal console.
  if (state.preview) { stopPreviewCountdown(); state.preview = null; }
  stopHomeCountdown();
  // Flush the deferred notification read (see loadNotificationsInto):
  // leaving the dashboard marks its Updates read and clears the badges.
  if (state.notesReadPending) {
    state.notesReadPending = false;
    api("POST", "/notifications/read", {}).then(() => refreshBadges()).catch(() => {});
  }
  state.view = view;
  // A direct invite (startOffer) latches the Offers composer for
  // the render that follows it. Deliberate navigation anywhere
  // else releases the latch: without this, one Invite tap in
  // Discover pinned EVERY later tab to My Offers until a refresh
  // reset the in-memory state (Jeff's stuck-nav report,
  // 2026-10-28, reproduced in the seed world). The draft itself
  // is kept (state.offerDraft survives re-renders); only the
  // direct targeting ends when the business walks away from it.
  if (tab && tab !== "My Offers" && tab !== "Campaign Setup") state.offerTarget = null;
  // Build -154: a Lineup book-all in progress ends the same
  // way when the business walks away from the composer.
  if (tab && tab !== "My Offers" && tab !== "Campaign Setup") state.lineupTargets = null;
  // Build -146: the discover brief belongs to the Discover
  // visit that produced it. Walking to any other tab ends it,
  // so a booking started elsewhere never inherits it.
  if (tab && tab !== "Discover") state.discoverBrief = null;
  // Multi-scope exit (Build -106): the Impact Portal's
  // "Partner view" row leaves the pilot scope and lands back
  // on the license partner's Home.
  if (tab === "__partner_scope_exit") {
    state.pilotScopeId = null;
    pilotState.me = null;
    state.tab = "Home";
    render();
    return false;
  }
  if (tab) state.tab = tab;
  render();
  return false;
}

async function render() {
  // The Ready-for-you queue belongs to the home that computed it;
  // every navigation clears it and the new home re-registers.
  state.agentQueue = null;
  renderAgentFab();
  renderNav();
  // Build -68: while a public profile is on screen, the
  // profile-view CSS centers the content column in the page
  // (the admin rail otherwise left-anchors it, stranding the
  // profile against the left with a void on the right).
  document.body.classList.toggle("profile-view", state.view === "public-profile");
  // Build -138 (Jeff, 2026-11-06): the shopping surfaces take
  // over the full screen on desktop — the dashboard rail and
  // top row leave; the surface's own bar carries Back.
  document.body.classList.toggle("shop-takeover",
    !!state.user && ((state.user.role === "business" && state.tab === "Discover")
      || (state.user.role === "creator" && state.tab === "Find Offers")));
  if (state.view === "public-profile") return renderPublicProfile();
  if (state.view === "public-proof") return renderPublicProof();
  // Build -178: the national campaign page + the brand profile a
  // creator opens from a campaign card.
  if (state.view === "national-campaign") return renderNationalCampaignPage();
  if (state.view === "brand-profile") return renderBrandProfilePage();
  clearShareShell();
  if (state.view === "staff") return renderStaff();
  if (state.view && state.view.indexOf("j226-") === 0) return renderJourney226();
  const u = state.user;
  if (!u) {
    if (state.view === "join-creator") return renderJoinCreator();
    if (state.view === "for-businesses" || state.view === "join-business") return renderForBusinesses();
    if (state.view === "signin") return renderSignin();
    if (state.view === "forgot") return renderForgot();
    if (state.view === "reset") return renderReset();
    // Build -219a (F2 entry, locked by Jeff 2026-11-20): the
    // signed-out cold open is the v5 intro film, then the F2
    // sign-in surface. Signed-in sessions never reach this branch:
    // boot() restores state.user before the first render, so they
    // land on their dashboard.
    if (state.introSkipped) return renderHome();
    return renderIntro();
  }
  // Build -85: the claim flow's done state replaces the pending
  // wall for the claim session itself ("You're in").
  // It is one screen, shown once: the exits below clear the step,
  // and a returning pending creator gets the normal pending home.
  if (state.claimStep === 5 && state.claimDone) return renderClaimDone();
  // Build -161 fix: an active biz dev seat is a separate axis
  // from the creator application — a seat holder whose creator
  // profile is still in review lands in the seller shell, not
  // on the pending wall (the server already treats the seat
  // that way; only this wall disagreed). The wall still applies
  // on the creator side itself, where bdShellActive() is false.
  if (u.status === "pending" && !bdShellActive()) return u.role === "business" ? renderBusinessFoundingStatus() : renderPending();
  if (u.status === "rejected") return renderRejected();
  // Build -68: approved founding businesses route into the
  // real dashboard like everyone else; the founding wall that
  // used to sit here is gone. renderBusinessFoundingStatus
  // remains only for the pending-review business above.
  return renderDashboard();
}

// ---------------- logged-out views ----------------

// Build -219a (F2 entry, locked by Jeff 2026-11-20): the signed-out
// entry. The locked v5 film plays full-screen first; on its end (or
// Skip) the surface becomes the F2 sign-in (renderSignin) — the
// film's own final frame is that same design, over the poster with
// a pale wash. The film is a web asset under /assets/intro/ (served
// like any other web file) so the cut can be swapped later with no
// app store resubmission: replace the file, or point INTRO_CUT at a
// different cut. Every sign-in and join flow behind the surface is
// the existing one, unchanged.
const INTRO_CUT = "/assets/intro/intro-film-v5.mp4";
const INTRO_POSTER = "/assets/intro/intro-film-v5-firstframe.jpg";
const INTRO_HARD_MS = 14000; // fallback: never strand a visitor on the film (v5 runs 11.4s)

let introTimers = [];
function introClearTimers() {
  introTimers.forEach((t) => clearTimeout(t));
  introTimers = [];
}
function introMarkSeen() {
  try { sessionStorage.setItem("magpie_intro_seen", "1"); } catch (e) { /* private mode */ }
}
function introToSignin() {
  introClearTimers();
  introMarkSeen();
  return go('signin');
}
function introSkip() {
  return introToSignin();
}
function introSkipToHome() {
  introClearTimers();
  state.introSkipped = true;
  // The sign-in surface is only ever reached with state.view set to
  // "signin", and render() checks that view before introSkipped, so
  // without this the "See how Magpie works" link could never leave
  // the sign-in surface (rendered-walk catch, 2026-11-20).
  state.view = "home";
  render();
  return false;
}

function renderIntro() {
  introClearTimers();
  let seen = false;
  try { seen = sessionStorage.getItem("magpie_intro_seen") === "1"; } catch (e) { /* storage unavailable */ }
  const reduced = typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduced || seen) {
    // Reduced motion (no autoplay) or a repeat open in this tab
    // session: no film wait — the sign-in surface is simply there,
    // over the poster still. Sign-in is never made to wait.
    return renderSignin();
  }
  app.innerHTML = `
  <section class="intro-stage" id="intro-stage" aria-label="Welcome to Magpie">
    <img class="intro-poster" src="${INTRO_POSTER}" alt="" onerror="this.style.display='none'">
    <video class="intro-video" id="intro-video" autoplay muted playsinline preload="auto" poster="${INTRO_POSTER}" src="${INTRO_CUT}"></video>
    <button class="intro-skip" type="button" onclick="return introSkip()">Skip</button>
  </section>`;
  const video = document.getElementById("intro-video");
  if (!video) return renderSignin();
  video.addEventListener("ended", () => { introToSignin(); });
  video.addEventListener("error", () => {
    // Film missing or undecodable: land straight on sign-in.
    introToSignin();
  });
  const p = video.play && video.play();
  if (p && p.catch) p.catch(() => { introToSignin(); });
  introTimers.push(setTimeout(() => { if (document.getElementById("intro-stage")) introToSignin(); }, INTRO_HARD_MS));
}

