function unlistedLabel() {
  return (state.boot && state.boot.unlistedMarket) || "Not listed yet";
}

// Listed label for a market (Jeff, 2026-10-23): the record keeps
// the canonical name ("Virginia Beach"); labels read
// "Virginia Beach (Hampton Roads)" from the bootstrap label. The
// value submitted and stored never changes.
function marketDisplayName(name) {
  const m = state.boot && state.boot.markets ? state.boot.markets.find((x) => x.name === name) : null;
  return (m && m.label) || name;
}

// Market naming rule (Build -47, audit C15): identity and meta
// lines use the display label ("Virginia Beach (Hampton
// Roads)"); prose uses the talk name ("Hampton Roads"). One
// form per context, held everywhere. An identity line never
// repeats the market's own lead city after the label.
function marketPlaceLine(market, city) {
  const label = marketDisplayName(market);
  const leadCity = String(market || "").split(" (")[0];
  if (!city || city === leadCity) return label;
  return `${label} · ${city}`;
}

// Conversational name for the Virginia Beach market in creator
// and business prose (Jeff, 2026-10-23): talk says Hampton Roads.
function marketTalkNameClient(name) {
  return name === "Virginia Beach" ? "Hampton Roads" : name;
}

// "City, Country" for an unlisted creator. Records from before the
// country field fall back to their stored state, so nobody's place
// loses its second half.
function unlistedPlace(rec) {
  const region = rec.country || rec.state || "";
  return `${rec.city || ""}${region ? ", " + region : ""}`;
}

// Typed-city resolution (Jeff, 2026-10-23): when intake resolved
// the typed city into a market, the pending screen says so in one
// line, so a creator who typed Portsmouth learns they are filed
// under the Virginia Beach market instead of parked as
// "not listed". Conversation about that market says Hampton
// Roads (Jeff, 2026-10-23), so its towns read that way here.
function marketResolvedNote(u) {
  if (!u || u.marketResolvedFrom !== "typed_city" || !u.market || u.market === unlistedLabel()) return "";
  const city = u.marketResolvedCity || u.city || "";
  if (!city) return "";
  if (u.market === "Virginia Beach") return `<p><span class="badge info">${esc(city)} is part of Hampton Roads, so you're filed there.</span></p>`;
  return `<p><span class="badge info">${esc(city)} is part of our ${esc(u.market)} market, so you're filed there.</span></p>`;
}

// Display spelling of a typed city for the candidate prompt: the
// record keeps the typed value verbatim ("Portsmouth, United
// States"); the prompt reads better without the country suffix.
function typedCityDisplay(rec) {
  return String((rec && rec.city) || "").replace(/,\s*(united states|usa)$/i, "");
}

// One tap on an ambiguous intake's candidate metro: files the
// record under it through the pending market endpoint, which
// keeps the typed city as the home city.
async function pickCandidateMarket(e, market) {
  if (e) e.preventDefault();
  try {
    const data = await api("POST", "/me/market", { market });
    state.user = data.user;
    render();
  } catch (err) { alert(err.message); }
  return false;
}

// Market options are grouped by country (United States first, then the
// rest alphabetically), cities alphabetical inside each country, so the
// picker stays scannable as Magpie goes universal (38 markets: universal
// 2026-10-18, roster reset 2026-10-23, Miami restored 2026-10-30).
function marketOptions(selected, forJoin) {
  const byCountry = {};
  for (const m of state.boot.markets) {
    const country = m.country || "United States";
    (byCountry[country] = byCountry[country] || []).push(m);
  }
  const countries = Object.keys(byCountry).sort((a, b) => (a === "United States" ? -1 : b === "United States" ? 1 : a.localeCompare(b)));
  const groups = countries.map((country) => {
    const opts = [...byCountry[country]]
      .sort((a, b) => a.name.localeCompare(b.name))
      .map((m) => `<option value="${esc(m.name)}" ${m.name === selected ? "selected" : ""}>${esc(m.label)}</option>`)
      .join("");
    return `<optgroup label="${esc(country)}">${opts}</optgroup>`;
  }).join("");
  // Build -173: the unlisted option takes `selected` when it
  // is the requested value. It never did before — harmless
  // while every form defaulted to a real market, but a claim
  // whose market string resolves to the unlisted path seeds
  // exactly this value, and an unselected select falls back
  // to the first option (Atlanta) — a wrong pre-pick again.
  return forJoin ? groups + `<option value="${esc(unlistedLabel())}" ${selected === unlistedLabel() ? "selected" : ""}>Add your city</option>` : groups;
}

// Options for the per-market audience share rows on the creator
// Profile (multi-market listing, 2026-11-01): every Magpie market
// except the creator's home market (the home share is the local
// % field, never a row here), with a blank "pick a market" head.
// Build -90: grouped by country exactly like the claim form's
// market picker (marketOptions), so the profile rows and the
// claim facts screen offer the same search-then-pick control.
function audienceMarketOptions(selected, homeMarket) {
  const markets = ((state.boot && state.boot.markets) || []).filter((m) => m.name !== homeMarket);
  const byCountry = {};
  for (const m of markets) {
    const country = m.country || "United States";
    (byCountry[country] = byCountry[country] || []).push(m);
  }
  const countries = Object.keys(byCountry).sort((a, b) => (a === "United States" ? -1 : b === "United States" ? 1 : a.localeCompare(b)));
  const groups = countries.map((country) => {
    const opts = [...byCountry[country]]
      .sort((a, b) => a.name.localeCompare(b.name))
      // Short market names, not the "Name, State" label: this
      // select shares its row with the % input, and at phone
      // width the long label truncates into ambiguity.
      .map((m) => `<option value="${esc(m.name)}" ${m.name === selected ? "selected" : ""}>${esc(m.name)}</option>`)
      .join("");
    return `<optgroup label="${esc(country)}">${opts}</optgroup>`;
  }).join("");
  return `<option value="">Pick a market</option>` + groups;
}

// Multi-market audience rows (Build -64, audit F2): the profile
// form used to render five always-open dropdown rows before any
// explanation. Now the help leads, the form starts with the
// rows the creator actually has (one blank row when they have
// none), rows are added and removed one at a time up to five,
// and each row carries the claim form's search-then-pick
// pattern instead of a bare full-list select.
// Build -160 (Jeff, Option B): each row also carries the
// market's own switch. Declaring a % lists nobody by itself —
// the switch is the listing, and the travel copy sits at the
// switch itself, naming the row's market. Stored entries with
// no flag are legacy declarations and render ON (they were
// listed before the switch existed); a brand-new row starts
// OFF.
function amTravelCopy(market) {
  if (market) return T(`Turn this on and businesses in ${market} can find you and send you offers. Offers there mean going there — a comped visit only counts when you show up in person. Only turn this on for places you actually get to.`, `Actívalo y los negocios en ${market} podrán encontrarte y enviarte ofertas. Las ofertas allí significan ir allí: una visita con cortesía solo cuenta cuando te presentas en persona. Actívalo solo para lugares a los que realmente vas.`);
  return T("Turn this on and businesses in the market you pick can find you and send you offers. Offers there mean going there — a comped visit only counts when you show up in person. Only turn this on for places you actually get to.", "Actívalo y los negocios en el mercado que elijas podrán encontrarte y enviarte ofertas. Las ofertas allí significan ir allí: una visita con cortesía solo cuenta cuando te presentas en persona. Actívalo solo para lugares a los que realmente vas.");
}
function amSyncTravel(el) {
  const row = el && el.closest ? el.closest(".p-am-row") : null;
  if (!row) return;
  const sel = row.querySelector(".p-am-market");
  const note = row.querySelector(".p-am-travel");
  if (note) note.textContent = amTravelCopy(sel ? sel.value : "");
}
function amRowHtml(market, pct, on) {
  const u = state.user || {};
  return `<div class="p-am-row"><input class="p-am-search" placeholder="${T("Search markets, for example: Dubai", "Busca mercados, por ejemplo: Dubái")}" oninput="filterAmOptions(this)" style="margin-bottom:6px"><select class="p-am-market" style="width:100%" onchange="amSyncTravel(this)">${audienceMarketOptions(market || "", u.market)}</select><div style="display:flex;align-items:center;gap:8px;margin-top:6px"><input class="p-am-pct" type="number" min="0" max="100" style="width:96px" placeholder="%" value="${esc(pct === undefined || pct === null ? "" : String(pct))}"><span class="small muted">${T("% of my audience", "% de mi audiencia")}</span><button type="button" class="btn small-btn ghost" onclick="return amRemoveRow(this)">${T("Remove", "Quitar")}</button></div><label class="tgl-row" style="margin-top:10px"><input type="checkbox" class="sw p-am-active" ${on ? "checked" : ""}><span><strong>${T("List me in this market", "Aparecer en este mercado")}</strong></span></label><p class="small muted p-am-travel" style="margin:4px 0 2px">${amTravelCopy(market || "")}</p></div>`;
}
function amRowCount() {
  return document.querySelectorAll("#p-am-rows .p-am-row").length;
}
function amSyncAddBtn() {
  const b = document.getElementById("p-am-add");
  if (b) b.style.display = amRowCount() >= 5 ? "none" : "";
}
function amAddRow() {
  const host = document.getElementById("p-am-rows");
  if (!host || amRowCount() >= 5) return false;
  const tmp = document.createElement("div");
  tmp.innerHTML = amRowHtml("", "");
  host.appendChild(tmp.firstElementChild);
  amSyncAddBtn();
  return false;
}
function amRemoveRow(btn) {
  const host = document.getElementById("p-am-rows");
  const row = btn && btn.closest ? btn.closest(".p-am-row") : null;
  if (row) row.remove();
  if (host && !host.querySelector(".p-am-row")) {
    const tmp = document.createElement("div");
    tmp.innerHTML = amRowHtml("", "");
    host.appendChild(tmp.firstElementChild);
  }
  amSyncAddBtn();
  return false;
}
function filterAmOptions(input) {
  const row = input && input.closest ? input.closest(".p-am-row") : null;
  const sel = row ? row.querySelector(".p-am-market") : null;
  if (!sel) return;
  const q = input.value.trim().toLowerCase();
  for (const opt of sel.querySelectorAll("option")) {
    if (!opt.value) continue;
    opt.hidden = !!q && !opt.textContent.toLowerCase().includes(q) && !opt.value.toLowerCase().includes(q);
  }
  // Claim-picker pattern: a country group with no visible match
  // hides too, so search never leaves an empty heading behind.
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
}

// The search box above the market picker filters the grouped options
// live; if the current selection gets filtered out, the first match
// takes over so the city list below never disagrees with the market.
function filterMarketOptions() {
  const input = document.getElementById("jc-market-search");
  const sel = document.getElementById("jc-market");
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    if (opt.value === unlistedLabel()) continue;
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) {
    sel.value = firstMatch.value;
    syncMarketChoice();
  }
}

// When a joiner picks "My city is not listed yet", the market city
// dropdown swaps for their own typed city + country: nobody is turned
// away, and their sign-up counts toward opening their city.
function syncMarketChoice() {
  const m = document.getElementById("jc-market");
  if (!m) return;
  const unlisted = m.value === unlistedLabel();
  const cityWrap = document.getElementById("jc-city-wrap");
  const customWrap = document.getElementById("jc-custom-wrap");
  // Build -173: no market picked yet hides the city picker
  // (nothing defaults; see renderJoinCreator).
  if (cityWrap) cityWrap.style.display = unlisted || !m.value ? "none" : "";
  if (customWrap) { customWrap.style.display = unlisted ? "" : "none"; customWrap.style.gridColumn = unlisted ? "1 / -1" : ""; }
  if (!unlisted && m.value) document.getElementById("jc-city").innerHTML = m.value === "London" ? `<option value="London" selected>London</option>` : cityOptions(m.value);
  // Build -88: for London the free-text neighborhood field is
  // replaced by the area picker (home city stays London).
  const jcAreaWrap = document.getElementById("jc-area-wrap");
  if (jcAreaWrap) {
    jcAreaWrap.style.display = m.value === "London" ? "" : "none";
    if (m.value === "London") {
      const areaSel = document.getElementById("jc-area");
      if (areaSel) areaSel.innerHTML = areaOptions("London", areaSel.value || undefined);
    }
  }
  const jcNbWrap = document.getElementById("jc-neighborhood-wrap");
  if (jcNbWrap) jcNbWrap.style.display = m.value === "London" ? "none" : "";
  // Dubai Advertiser Permit note (Build -70): shown only when
  // Dubai is the picked market. It never blocks the signup.
  const dubaiNote = document.getElementById("jc-dubai-note");
  if (dubaiNote) dubaiNote.style.display = m.value === "Dubai" ? "" : "none";
  // London note (Build -86): same shape as the Dubai note
  // above, for UK ad-labelling norms. Never blocks the signup.
  const londonNote = document.getElementById("jc-london-note");
  if (londonNote) londonNote.style.display = m.value === "London" ? "" : "none";
}

function cityOptions(marketName, selected) {
  const m = state.boot.markets.find((x) => x.name === marketName) || state.boot.markets[0];
  return m.cities.map((c) => `<option value="${esc(c)}" ${c === selected ? "selected" : ""}>${esc(c)}</option>`).join("");
}

// Build -88: the area picker options for a market, fed by the
// market's own typed city list (for London, its full
// neighbourhood + surrounding-towns list). The area search box
// filters the options live, mirroring the market picker.
function areaOptions(marketName, selected) {
  const m = (state.boot.markets || []).find((x) => x.name === marketName);
  const list = m ? m.cities : [];
  return list.map((c) => `<option value="${esc(c)}" ${c === selected ? "selected" : ""}>${esc(c)}</option>`).join("");
}
// Build -89: currency by market, client side. The bootstrap
// market entries carry currencySymbol + paidFloor (London: £,
// 40); every other market defaults to $ and 50. Creator money
// surfaces render with the CREATOR's home-market symbol — the
// viewer's own market when the surface is the creator's own.
function currencySymbolForMarket(name) {
  const m = (state.boot.markets || []).find((x) => x.name === name);
  return (m && m.currencySymbol) || "$";
}
function paidFloorForMarketClient(name) {
  const m = (state.boot.markets || []).find((x) => x.name === name);
  return m && typeof m.paidFloor === "number" ? m.paidFloor : 50;
}
function ownCurrencySymbol() {
  return state.user ? currencySymbolForMarket(state.user.market) : "$";
}
function ownPaidFloor() {
  return state.user ? paidFloorForMarketClient(state.user.market) : 50;
}
function filterAreaOptions(searchId, selectId) {
  const input = document.getElementById(searchId);
  const sel = document.getElementById(selectId);
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) sel.value = firstMatch.value;
}

// ---------- Google sign-in + sign-in link (Build -123) ----------
// Continue with Google renders only when the server says the
// Google lane is configured (bootstrap googleSignin): with the
// env unset there is no button and no dead click, exactly the
// honesty rule every other rail follows.
function googleConfigured123() {
  return !!(state.boot && state.boot.googleSignin && state.boot.googleSignin.configured);
}
function googleButtonHtml(mode, label) {
  if (!googleConfigured123()) return "";
  // Build -219a: on the F2 sign-in surface the Google lane sits
  // below the password block in the same quiet borderless style
  // (no boxed ghost button, no "or" rule). Apply surfaces keep
  // the original boxed treatment below.
  if (mode === "signin") {
    return `<a class="entry-google" href="/api/auth/google/start?mode=${mode}"><strong style="margin-right:6px">G</strong> ${esc(label || "Continue with Google")}</a>`;
  }
  return `<a class="btn ghost" style="width:100%;margin-bottom:10px" href="/api/auth/google/start?mode=${mode}"><strong style="margin-right:6px">G</strong> ${esc(label || "Continue with Google")}</a>
    <p class="small muted" style="text-align:center;margin:0 0 10px">or</p>`;
}
function storedGoogleLink() {
  try { return localStorage.getItem("signl_googlelink") || ""; } catch (e) { return ""; }
}
function clearStoredGoogleLink() {
  try { localStorage.removeItem("signl_googlelink"); localStorage.removeItem("signl_google_prefill"); localStorage.removeItem("signl_claim_draft"); } catch (e) { /* storage unavailable */ }
  state.googlePrefill = null;
}

function renderSignin() {
  // Build -219a (F2 entry, locked by Jeff 2026-11-20): the sign-in
  // view IS the F2 surface — the real logo over the settled film
  // frame under a pale wash, footage faintly visible. The frame is
  // intro-signin-bg.jpg (the film at 8.5s), NOT the film's final
  // frame: the final frame carries the film's own mock sign-in UI,
  // which ghosted through the wash behind the real controls
  // (rendered-walk catch, 2026-11-20). Borderless EMAIL / PASSWORD
  // fields, the gradient
  // Sign in pill, Forgot password?, and the join lines at the
  // bottom. No boxes, cards or panels. Every existing auth route
  // stays on this surface: password (doSignin), Google and the
  // emailed sign-in link below the password block in the same
  // quiet style, forgot/reset via the link, and the staff redeem
  // door as a quiet line at the bottom.
  introClearTimers();
  const gNotice = state.googleNotice;
  state.googleNotice = "";
  app.innerHTML = `
  <section class="entry-stage entry-signin" aria-label="Sign in to Magpie">
    <img class="entry-bg" src="/assets/intro/intro-signin-bg.jpg" alt="" onerror="this.style.display='none'">
    <div class="entry-wash"></div>
    <div class="entry-ui">
      <img class="entry-logo" src="/assets/logo.png" alt="Magpie">
      <div id="form-error">${gNotice ? `<div class="error-box">${esc(gNotice)}</div>` : ""}</div>
      <form novalidate onsubmit="return doSignin(event)">
        <div class="entry-field"><label for="si-email">Email</label><input type="email" id="si-email" required autocomplete="email" placeholder="you@example.com"></div>
        <div class="entry-field"><label for="si-password">Password</label><input type="password" id="si-password" required autocomplete="current-password" placeholder="&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;"></div>
        <button class="btn entry-signin-btn" type="submit">Sign in</button>
      </form>
      <p class="entry-forgot"><a href="#" onclick="return go('forgot')">Forgot password?</a></p>
      <p class="entry-stay">You will stay signed in on this device for 30 days.</p>
      <div class="entry-alt">
        ${googleButtonHtml("signin")}
        <p class="entry-alt-note"><strong>No password handy?</strong> We can email you a sign-in link instead. It works once and expires in 30 minutes, and your password stays as it is.</p>
        <form novalidate onsubmit="return doSigninLink(event)">
          <div class="entry-field"><label for="sl-email">Email</label><input type="email" id="sl-email" required autocomplete="email" placeholder="you@example.com"></div>
          <button class="entry-quiet-btn" type="submit">Email me a sign-in link</button>
        </form>
        <p class="entry-note" id="sl-note"></p>
      </div>
      <div class="entry-bottom">
        <p class="entry-new">New to Magpie?</p>
        <p class="entry-join"><a href="#" onclick="return go('join-creator')">Join as a creator</a> <span aria-hidden="true">&middot;</span> <a href="#" onclick="return go('for-businesses')">Join as a business</a></p>
        <p class="entry-more"><a href="#" onclick="return introSkipToHome()">See how Magpie works</a></p>
        <p class="entry-more"><a href="#" onclick="return goStaff()">Redeem a creator visit</a> <span class="entry-more-note">Staff at a Magpie business: PIN in, creator code in, redeemed.</span></p>
      </div>
    </div>
  </section>`;
}

// Build -238: email deep links (/?open=profile, /?open=status,
// /?open=messages) used to lose their destination whenever the
// visitor was logged out. The approval email and the platform
// message notification email link straight at those params,
// but init() only honoured them for an already signed-in
// session, so a newly approved creator tapped the link, sat
// through the intro film (Jeff-locked for plain signed-out
// visits, Build -219a), signed in, and landed on the default
// dashboard tab instead of the surface the email named. The
// fix: init() stashes a valid open target in sessionStorage
// under magpie_pending_open when the visitor is logged out,
// sends them straight to the sign-in surface (no film), and
// this helper applies the stash the moment a session exists.
// It is called from doSignin, from the ?signinlink= consume
// block in init(), and at boot when a live session is already
// present with no open param in the URL (the Google sign-in
// return). The stash is consumed exactly once, and only once
// a session exists, so an abandoned sign-in never loses it.
// The role guards are the SAME ones the signed-in boot code
// has always used: messages is for creators and businesses
// (a creator lands on the Magpie team thread), profile and
// status are creators only. A signed-in role that does not
// fit the target just clears the stash and lands normally.
const PENDING_OPEN_KEY_238 = "magpie_pending_open";
// Build -239: the stash also lives in localStorage as an
// expiring envelope, so a sign-in detour that hops tabs (the
// emailed sign-in link opened in a fresh tab has no
// sessionStorage copy) cannot lose the destination. The
// expiry matches the sign-in link's own 30-minute lifetime.
const PENDING_OPEN_TTL_239 = 30 * 60 * 1000;
function stashPendingOpen238(target) {
  try { sessionStorage.setItem(PENDING_OPEN_KEY_238, target); } catch (e) { /* storage unavailable */ }
  try { localStorage.setItem(PENDING_OPEN_KEY_238, JSON.stringify({ t: target, exp: Date.now() + PENDING_OPEN_TTL_239 })); } catch (e) { /* storage unavailable */ }
}
function applyPendingOpen238() {
  let target = "";
  try { target = sessionStorage.getItem(PENDING_OPEN_KEY_238) || ""; } catch (e) { target = ""; }
  if (!target) {
    // Build -239: the cross-tab fallback described above.
    try {
      const raw = localStorage.getItem(PENDING_OPEN_KEY_238) || "";
      const env = JSON.parse(raw);
      if (env && typeof env.t === "string" && env.exp && Date.now() < env.exp) target = env.t;
    } catch (e) { target = ""; }
  }
  if (!target) return false;
  if (!state.user) return false; // no session yet: keep the stash for the sign-in that is still to come
  try { sessionStorage.removeItem(PENDING_OPEN_KEY_238); } catch (e) { /* the routing below still runs once */ }
  try { localStorage.removeItem(PENDING_OPEN_KEY_238); } catch (e) { /* the routing below still runs once */ }
  if (target === "messages" && (state.user.role === "creator" || state.user.role === "business")) {
    state.tab = "Messages";
    if (state.user.role === "creator") state.activeThread = "signl-team";
    state.view = "dashboard";
    return true;
  }
  if (target === "profile" && state.user.role === "creator") {
    state.tab = "Profile";
    state.view = "dashboard";
    return true;
  }
  if (target === "status" && state.user.role === "creator") {
    state.tab = "Status";
    state.view = "dashboard";
    return true;
  }
  // Build -239: the generalized targets. Every notification
  // email now links at the surface its own words name; the
  // role guards mirror the tabs each role actually has, and a
  // role that does not fit just clears the stash (consumed
  // above) and lands normally, exactly like the -238 targets.
  if (target === "profile" && state.user.role === "business") {
    state.tab = "Profile";
    state.view = "dashboard";
    return true;
  }
  if (target === "visits" && state.user.role === "creator") {
    state.tab = "My Visits";
    state.view = "dashboard";
    return true;
  }
  if (target === "visits" && state.user.role === "business") {
    state.tab = "Visits & Posts";
    state.view = "dashboard";
    return true;
  }
  if (target === "offers" && state.user.role === "creator") {
    state.tab = "Find Offers";
    state.view = "dashboard";
    return true;
  }
  if (target === "offers" && state.user.role === "business") {
    state.tab = "My Offers";
    state.view = "dashboard";
    return true;
  }
  if (target === "deals" && state.user.role === "creator") {
    state.tab = "Offers";
    state.crOffersSeg = "deals";
    state.view = "dashboard";
    return true;
  }
  if (target === "deals" && state.user.role === "business") {
    state.offersSeg = "deals";
    state.tab = "My Offers";
    state.view = "dashboard";
    return true;
  }
  if (target === "applications" && state.user.role === "business") {
    state.offersSeg = "applicants";
    state.tab = "My Offers";
    state.view = "dashboard";
    return true;
  }
  if (target === "licences" && state.user.role === "creator") {
    state.tab = "Earnings";
    state.view = "dashboard";
    return true;
  }
  if (target === "licences" && state.user.role === "business") {
    state.tab = "Visits & Posts";
    state.view = "dashboard";
    return true;
  }
  if (target === "counter" && state.user.role === "business") {
    state.tab = "Counter";
    state.view = "dashboard";
    return true;
  }
  if (target === "discover" && state.user.role === "business") {
    state.tab = "Discover";
    state.view = "dashboard";
    return true;
  }
  return false;
}

async function doSignin(e) {
  e.preventDefault();
  const form = e.target;
  // Empty submit speaks (Build -47, audit L1): the form is
  // novalidate so this check, not a browser bubble, answers.
  const siEmail = (document.getElementById("si-email").value || "").trim();
  const siPw = document.getElementById("si-password").value || "";
  if (!siEmail || !siPw) {
    document.getElementById("form-error").innerHTML = `<div class="error-box">${!siEmail && !siPw ? "Enter your email and password to sign in." : !siEmail ? "Enter your email to sign in." : "Enter your password to sign in."}</div>`;
    return false;
  }
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/login", {
      email: document.getElementById("si-email").value,
      password: document.getElementById("si-password").value,
    });
    state.user = data.user;
    state.view = "dashboard";
    applyPendingOpen238(); // Build -238: an email deep link stashed while logged out lands now
    render();
    refreshBadges();
    magpieNativeInitPush218();
  } catch (err) {
    submitBusy(form, false);
    document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

async function doSigninLink(e) {
  e.preventDefault();
  const form = e.target;
  const note = document.getElementById("sl-note");
  const email = (document.getElementById("sl-email").value || "").trim();
  if (!email) { if (note) note.textContent = "Enter your email and we will send the link there."; return false; }
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/signin-link", { email });
    submitBusy(form, false);
    if (note) note.textContent = data && data.emailDown
      ? "Email is down on our side right now, so no link went out. Try again in a little while, or email hello@magpielocal.com and we will help you in by hand."
      : "If an account exists for that email, a sign-in link is on its way. It works once and expires in 30 minutes.";
  } catch (err) {
    submitBusy(form, false);
    if (note) note.textContent = err.message;
  }
  return false;
}

// Forgot password (UX audit fix, 2026-10-22): the request screen
// always lands on the same neutral confirmation, whether or not
// the email belongs to an account, so the form never confirms
// that an account exists.
function renderForgot() {
  app.innerHTML = `
  <section class="panel form-panel" style="max-width:460px;margin:30px auto">
    <div class="form-head">
    <h2>Forgot password</h2>
    </div>
    <div class="form-body">
    <p class="muted">Enter the email on your Magpie account and we will email you a link to set a new password. The link works once and expires in one hour.</p>
    <div id="form-error"></div>
    <form onsubmit="return doForgot(event)">
      <div class="field"><label>Email</label><input type="email" id="fp-email" required autocomplete="email"></div>
      <button class="btn" type="submit" style="width:100%">Email me a reset link</button>
    </form>
    <p class="small muted mt">Remembered it after all? <a href="#" onclick="return go('signin')">Back to sign in</a>.</p>
    </div>
  </section>`;
}

async function doForgot(e) {
  e.preventDefault();
  const form = e.target;
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/forgot", { email: document.getElementById("fp-email").value });
    // Transport honesty (Build -46): when the server says email
    // itself is down, no link can go out to anyone, so the screen
    // says that instead of promising one — with a human way
    // forward, never a loop of fresh requests that cannot send.
    if (data && data.emailDown) {
      app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Email is down on our side</h2>
      <p>We cannot send a reset link right now, so none went out. This is a problem on our end, not with your account.</p>
      <p class="muted">Try again in a little while, or email hello@magpielocal.com and we will help you set a new password by hand.</p>
      <div class="cta-row" style="justify-content:center">
        <a class="btn ghost" href="#" onclick="return go('signin')">Back to sign in</a>
      </div>
    </section>`;
      return false;
    }
    app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Check your email</h2>
      <p>If an account exists for that email, a reset link is on its way. The link works once and expires in one hour.</p>
      <p class="muted">Nothing arrived after a few minutes? Check spam, then request a fresh link. If it keeps not arriving, email hello@magpielocal.com and we will sort it out with you.</p>
      <div class="cta-row" style="justify-content:center">
        <a class="btn" href="#" onclick="return go('forgot')">Request another link</a>
        <a class="btn ghost" href="#" onclick="return go('signin')">Back to sign in</a>
      </div>
    </section>`;
  } catch (err) {
    submitBusy(form, false);
    document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

// The reset screen the email link lands on (/?reset=<token>).
function renderReset() {
  app.innerHTML = `
  <section class="panel form-panel" style="max-width:460px;margin:30px auto">
    <div class="form-head">
    <h2>Set a new password</h2>
    </div>
    <div class="form-body">
    <p class="muted">Pick a new password for your Magpie account. Setting it signs out every other device on the account.</p>
    <div id="form-error"></div>
    <form onsubmit="return doReset(event)">
      <div class="field"><label>New password (10+ characters)</label><input type="password" id="rs-password" required minlength="10" autocomplete="new-password"></div>
      <div class="field"><label>New password again</label><input type="password" id="rs-password2" required minlength="10" autocomplete="new-password"></div>
      <button class="btn" type="submit" style="width:100%">Set my new password</button>
    </form>
    <p class="small muted mt">Link expired or already used? <a href="#" onclick="return go('forgot')">Request a new one</a>.</p>
    </div>
  </section>`;
}

async function doReset(e) {
  e.preventDefault();
  const form = e.target;
  const errBox = (msg) => { document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(msg)}</div>`; };
  const pw = document.getElementById("rs-password").value;
  if (pw !== document.getElementById("rs-password2").value) { errBox("The two passwords do not match. Type the same new password in both boxes."); return false; }
  if (!submitBusy(form, true)) return false;
  try {
    await api("POST", "/auth/reset", { token: state.resetToken || "", password: pw });
    state.resetToken = "";
    app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Your password is set</h2>
      <p>Sign in with your new password to pick up right where you left off.</p>
      <div class="cta-row" style="justify-content:center"><a class="btn" href="#" onclick="return go('signin')">Sign in</a></div>
    </section>`;
  } catch (err) {
    submitBusy(form, false);
    errBox(err.message);
  }
  return false;
}

async function signOut() {
  // In a view-as session (Build -67), signing out exits the view
  // back to Admin; the admin is never signed out from under the
  // view. The server routes logout the same way, belt and braces.
  if (state.user && state.user.viewAs) { await exitViewAs(); return; }
  try { await api("POST", "/auth/logout", {}); } catch (e) { /* ignore */ }
  state.user = null;
  state.view = "home";
  // V4.1: Sig's queue + conversation belong to the signed-out
  // account; the next person on this device starts clean.
  state.sigQueue = null;
  state.sigQueueLinks = [];
  state.sigQueueCount = 0;
  state.sigThread = [];
  render();
}

// Account basics (UX audit fix, 2026-10-22): every signed-in
// account surface shows who you are signed in as and offers a
// password change (current password required; every other device
// signs out, this one stays). Before this there was no settings
// surface at all: no email display, no password change, and a
// forgotten password was a permanent lockout.
// Google sign-in row (Build -123): the Settings home of the
// link/unlink. Linked shows which Google email signs you in;
// unlinked offers the one-tap link when the lane is configured,
// and says plainly when it is still being switched on.
function googleAccountRowHtml(u) {
  if (u.google && u.google.email) {
    return `<div style="margin:10px 0">
      <p class="small" style="margin:0 0 6px"><strong>Google:</strong> connected as ${esc(u.google.email)}. Continue with Google on the sign-in screen brings you straight in; your password still works too.</p>
      <button type="button" class="btn small-btn ghost" onclick="return googleUnlink()">Unlink Google</button> <span class="saved" id="google-note"></span>
    </div>`;
  }
  if (googleConfigured123()) {
    return `<div style="margin:10px 0">
      <p class="small" style="margin:0 0 6px"><strong>Google:</strong> not connected. Link your Google account and signing in becomes one tap, no password to type.</p>
      <a class="btn small-btn" href="/api/auth/google/start?mode=link">Link Google</a>
    </div>`;
  }
  return `<div style="margin:10px 0">
    <p class="small muted" style="margin:0"><strong>Google:</strong> sign-in with Google is being switched on. Until it opens, your email and password are the way in.</p>
  </div>`;
}

async function googleUnlink() {
  if (!confirm("Unlink Google? You will sign in with your email and password instead. Your account and everything on it stays exactly as it is.")) return false;
  try {
    const data = await api("POST", "/auth/google/unlink", {});
    if (data && data.user) state.user = data.user;
    render();
    setTimeout(() => showToast("Google unlinked"), 300);
  } catch (err) {
    const note = document.getElementById("google-note");
    if (note) note.textContent = err.message;
  }
  return false;
}

function accountHtml(u) {
  return `
  <div class="panel mt">
    <h3>Your account</h3>
    <p class="small muted">Signed in as <strong>${esc(u.email)}</strong>. This is the email Magpie uses for your account and launch messages.</p>
    ${googleAccountRowHtml(u)}
    <div id="acct-error"></div>
    <form onsubmit="return doChangePassword(event)">
      <div class="form-2col">
        <div class="field"><label>Current password</label><input type="password" id="acct-current" required autocomplete="current-password"></div>
        <div class="field"><label>New password (10+ characters)</label><input type="password" id="acct-new" required minlength="10" autocomplete="new-password"></div>
      </div>
      <button class="btn" type="submit">Change password</button> <span id="acct-ok" class="saved"></span>
      <p class="small muted mt">Changing your password signs out every other device on this account. This device stays signed in.</p>
    </form>
    <p class="small muted">Cannot get in at all? Sign out, then use Forgot password on the sign-in screen and we will email you a reset link.</p>
    ${(u.role === "creator" || u.role === "business") ? deleteAccountHtml(u) : ""}
  </div>`;
}

// Delete my account (Build -132; soft delete, Build -219c):
// nested at the bottom of Settings → Account, behind its own
// reveal — never a top-level button. The confirm panel says,
// in plain words, what is deleted and what happens to anything
// in flight BEFORE the type-DELETE confirmation can be sent;
// the server runs the one soft-delete routine
// (softDeleteAccount), emails one confirmation to the address
// on file, and an admin can restore the account afterwards.
function deleteAccountHtml(u) {
  const creator = u.role === "creator";
  return `
  <div style="margin-top:22px;border-top:1px solid var(--hairline,#DFE7DF);padding-top:14px">
    <button class="btn small-btn ghost" type="button" onclick="document.getElementById('delacct-panel').style.display=''; this.style.display='none'">Delete my account</button>
    <div id="delacct-panel" style="display:none">
      <h4 style="margin:4px 0 6px">Delete your Magpie account</h4>
      <p class="small" style="margin:0 0 8px">This takes off Magpie:</p>
      <ul class="small" style="margin:0 0 8px;padding-left:18px">
        <li>Your profile${creator ? " and your public page" : ""}, your name, photos and handle</li>
        <li>Your sign-in: email, password and every signed-in device</li>
        <li>Your referral links and invite codes</li>
        <li>Your audience and share data, and your notification settings</li>
      </ul>
      <p class="small" style="margin:0 0 8px">Anything still in flight settles this way:</p>
      <ul class="small" style="margin:0 0 8px;padding-left:18px">
        ${creator ? "<li>Applications you have not heard back on are withdrawn.</li>" : "<li>Offers you have posted are closed.</li>"}
        <li>Open offers and deals are closed, with nobody the winner.</li>
        <li>A booking that has not happened yet is cancelled, and the other side is told the account was deleted. Money held for a paid booking goes back to the business.</li>
        <li>A visit that already happened stays in the other side's history, because it is their record of a real visit.</li>
      </ul>
      <p class="small" style="margin:0 0 10px"><strong>An admin can restore your account if this was a mistake.</strong> Your record is kept, flagged as deleted, and an admin can bring it back with everything as it was. We email one confirmation to ${esc(u.email)} when it is done.</p>
      <div class="field"><label>Type DELETE to confirm</label><input id="delacct-confirm" autocomplete="off" placeholder="DELETE" oninput="document.getElementById('delacct-go').disabled = this.value.trim() !== 'DELETE'"></div>
      <p style="margin:0"><button class="btn danger" type="button" id="delacct-go" disabled onclick="return doDeleteAccount()">Delete my account</button> <span class="small" id="delacct-note"></span></p>
    </div>
  </div>`;
}

// Admin delete (Build -132; soft delete, Build -219c): the
// same soft deletion from the Admin user card, for a deletion
// request that arrives by email. Its own deliberate confirm —
// type DELETE in the row — then the server runs
// softDeleteAccount and the holder gets the one confirmation
// email. An admin restores the account from Deleted accounts.
// Build -133: the card servicing row
// (deck + Find-a-user) carries the same action; it passes a
// prefixed host key because the same person can be on screen
// in a card and in the list at once, and the prompt's element
// ids must stay unique per surface. No key = the list row's
// original ids, unchanged.
function adminDeleteAccountPrompt(userId, key) {
  const k = key || userId;
  const host = document.getElementById("admin-delacct-" + k);
  if (!host) return;
  host.innerHTML = `<span style="display:block;margin-top:8px;min-width:260px"><span class="small">Deletes the account. An admin can restore it later from Deleted accounts. It is the same deletion as the self-serve screen, with in-flight items settled the same way. Type DELETE:</span><br><input id="admin-delacct-word-${k}" placeholder="DELETE" style="margin-top:4px"> <button class="btn small-btn danger" type="button" onclick="adminDeleteAccountGo('${userId}', '${k}')">Delete account</button> <span class="small" id="admin-delacct-note-${k}"></span></span>`;
}
async function adminDeleteAccountGo(userId, key) {
  const k = key || userId;
  const note = document.getElementById("admin-delacct-note-" + k);
  const word = (document.getElementById("admin-delacct-word-" + k) || {}).value || "";
  try {
    await api("POST", `/admin/users/${userId}/delete-account`, { confirmText: word });
    if (note) note.textContent = "Deleted.";
    if (typeof loadApplications === "function") loadApplications();
    else location.reload();
  } catch (e) { if (note) note.textContent = e.message; }
}

async function doDeleteAccount() {
  const note = document.getElementById("delacct-note");
  const word = (document.getElementById("delacct-confirm") || {}).value || "";
  try {
    await api("DELETE", "/me/account", { confirmText: word });
    state.user = null;
    document.body.innerHTML = `<div style="max-width:520px;margin:12vh auto;padding:24px;text-align:center"><h2>Your account is deleted</h2><p>Your Magpie account is off the platform, and every device is signed out. A confirmation email is on its way to the address that was on file. If this was a mistake, contact Magpie and an admin can restore your account.</p></div>`;
    return false;
  } catch (e) { if (note) note.textContent = e.message; return false; }
}

async function doChangePassword(e) {
  e.preventDefault();
  const form = e.target;
  if (!submitBusy(form, true)) return false;
  const errEl = document.getElementById("acct-error");
  try {
    await api("POST", "/auth/change-password", {
      currentPassword: document.getElementById("acct-current").value,
      newPassword: document.getElementById("acct-new").value,
    });
    submitBusy(form, false);
    form.reset();
    if (errEl) errEl.innerHTML = "";
    const ok = document.getElementById("acct-ok");
    if (ok) ok.textContent = "Password changed.";
  } catch (err) {
    submitBusy(form, false);
    if (errEl) errEl.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

function suggestedTierId(followers) {
  const n = Number(followers) || 0;
  if (n >= 15000) return "Headliners";
  if (n >= 2000) return "Locals";
  return "Neighbors";
}

const JC_STACK_ROWS = [["jc-stack-tiktok", "tiktok"], ["jc-stack-facebook", "facebook"], ["jc-stack-x", "x"], ["jc-stack-linkedin", "linkedin"], ["jc-stack-youtube", "youtube"], ["jc-stack-snapchat", "snapchat"]];
function jcPrimary() {
  const sel = document.getElementById("jc-platform");
  return sel ? sel.value : "instagram";
}
function signupStackTotal() {
  // The main followers field IS the primary platform's count; a
  // stack row for that same platform would double it, so its row
  // is hidden by syncJcPlatform and skipped here.
  let total = parseInt((document.getElementById("jc-followers") || {}).value, 10) || 0;
  const primary = jcPrimary();
  for (const [id, platform] of JC_STACK_ROWS) {
    if (platform === primary) continue;
    const el = document.getElementById(id);
    if (el) total += parseInt(el.value, 10) || 0;
  }
  return total;
}
function syncJcPlatform() {
  syncProofDisclosure("jc-platform", "jc-proof-note");
  const meta = primaryMetaClient(jcPrimary());
  const handleLabel = document.getElementById("jc-handle-label");
  if (handleLabel) handleLabel.textContent = `${meta.label} ${T("handle (required)", "usuario (obligatorio)")}`;
  const followersLabel = document.getElementById("jc-followers-label");
  if (followersLabel) followersLabel.textContent = `${meta.label} ${T("followers (required)", "seguidores (obligatorio)")}`;
  const input = document.getElementById("jc-handle");
  const link = document.getElementById("jc-ig-link");
  if (link) link.textContent = input && input.value ? meta.host + input.value.replace(/^@/, "") : "";
  for (const [, platform] of JC_STACK_ROWS) {
    const row = document.getElementById("jc-stackrow-" + platform);
    if (row) row.style.display = platform === meta.id ? "none" : "";
  }
  syncSuggestedTier();
}

// Tier bands are fully automatic (Jeff, 2026-10-19): the band is
// derived from the total audience across platforms, at sign-up and
// on every profile save. Nobody picks or confirms their own band,
// so the form shows it as a read-only line that follows the counts.
function syncSuggestedTier() {
  const total = signupStackTotal();
  const line = document.getElementById("jc-tier-line");
  if (line) line.textContent = total >= 500
    ? `Your band: ${suggestedTierId(total)}, set automatically from your total audience across platforms (${total.toLocaleString()} total).`
    : total > 0
      ? `Magpie starts at 500 total followers across your platforms. You have ${total.toLocaleString()} counted so far; add every platform you post on and the counts add up.`
      : "Your band is set automatically from your total audience across platforms. Magpie starts at 500 total followers across your platforms.";
  syncPaidOption();
}

// Paid cash campaigns are a Headliners-tier option: the checkbox block
// only appears while the automatic band is Headliners.
function syncPaidOption() {
  const wrap = document.getElementById("jc-paid-wrap");
  if (wrap) wrap.style.display = suggestedTierId(signupStackTotal()) === "Headliners" ? "" : "none";
}

function profileStackTotal() {
  // Build -140: every platform row counts — the Instagram
  // field plus every p-stack-* input the form carries (the six
  // legacy rows and any platform added from the picker).
  let total = parseInt((document.getElementById("p-followers") || {}).value, 10) || 0;
  document.querySelectorAll("input[id^='p-stack-']").forEach((el) => { total += parseInt(el.value, 10) || 0; });
  return total;
}

function syncPaidOptionProfile() {
  const wrap = document.getElementById("p-paid-wrap");
  if (wrap) wrap.style.display = suggestedTierId(profileStackTotal()) === "Headliners" ? "" : "none";
}

// ================= Sig Operator (Jeff, 2026-10-28) =================
// Sig does the doing in this chat: set up campaigns, find
// people, track data, prompt the next move, on both sides.
// The contract, from the actions catalog:
//  - routing: active flow first, then operator intents, then
//    the existing question path (AI, then the canon bank).
//  - confirm-before-commit on every write; reads need none.
//  - commits are the exact api() calls the screens make, so a
//    server refusal surfaces with the server's own reason, and
//    Sig offers the compliant fix in the same turn.
//  - flow state lives in memory only until confirmation;
//    "never mind" exits any flow with nothing written.
//  - English/Spanish end to end via ST(), keyed to the stored
//    language (creator record lang from S1, business
//    preferredLanguage from S3). Server error strings surface
//    as written; that is the named S1 limit.
// Operator text matching folds accents first (sigOpNorm), so
// Spanish phrasing matches with or without them.
function sigOpNorm(text) {
  return sigNorm(String(text || "").normalize("NFD").replace(/[\u0300-\u036f]/g, ""));
}
function sigOpSay(text, actions) {
  state.sigThread = state.sigThread || [];
  state.sigThread.push({ who: "sig", text, actions: actions && actions.length ? actions : undefined });
}
function sigOpUserTurn(text) {
  state.sigThread = state.sigThread || [];
  state.sigThread.push({ who: "user", text });
}
function sigOpPaint() {
  const host = document.getElementById("sig-thread");
  if (host) { host.innerHTML = sigThreadHtml(); wireSigThread(host); host.scrollTop = host.scrollHeight; }
  const inp = document.getElementById("sig-ask-input");
  if (inp) inp.focus();
}
async function sigOpPick(label, fn) {
  sigOpUserTurn(label);
  await fn();
  sigOpPaint();
}
function sigOpCancelAction() {
  const label = ST("Never mind", "Cancelar");
  return { label, run: () => sigOpPick(label, async () => {
    state.sigFlow = null;
    state.sigOpData = null;
    sigOpSay(ST("Stopped. Nothing was saved, sent, or posted.", "Listo. No se guardó, envió ni publicó nada."), sigOpHomeActions());
  }) };
}
function sigOpAsk(text, actions) {
  sigOpSay(text, [...(actions || []), sigOpCancelAction()]);
}
function sigOpIsCancel(norm) {
  return [" never mind ", " cancel ", " cancelar ", " olvida ", " olvidalo ", " forget it ", " stop here ", " detente "].some((p) => norm.includes(p));
}
function sigOpNum(text) {
  const m = String(text || "").replace(/[$,]/g, "").match(/(\d+(?:\.\d+)?)/);
  return m ? Number(m[1]) : null;
}
function sigOpHomeActions() {
  const u = state.user;
  if (!u) return [];
  if (u.role === "business") return [
    { label: ST("Start a campaign", "Iniciar una campaña"), primary: true, run: async () => { sigB1Start(); sigOpPaint(); } },
    { label: ST("Find creators", "Buscar creadores"), run: async () => { sigB2Start(); sigOpPaint(); } },
    { label: ST("My Regulars", "Mis clientes habituales"), run: async () => { await sigB95Regulars(); sigOpPaint(); } },
    { label: ST("Licences ending soon", "Licencias por vencer"), run: async () => { await sigB95Licences(); sigOpPaint(); } },
    { label: ST("Monthly receipt", "Recibo mensual"), run: async () => { await sigB96Receipt(); sigOpPaint(); } },
    { label: ST("Standing hours", "Horario habitual"), run: async () => { await sigB96AvailabilityStart(); sigOpPaint(); } },
    { label: ST("How am I doing?", "¿Cómo voy?"), run: async () => { await sigB3Run(); sigOpPaint(); } },
    { label: ST("Build my asset packet", "Crear mi paquete"), run: async () => { sigPacketStart(); sigOpPaint(); } },
    { label: ST("Setup from Instagram", "Configúrame desde Instagram"), run: async () => { sigSetupStart("business"); sigOpPaint(); } },
  ];
  return [
    { label: ST("Find offers for me", "Buscar ofertas para mí"), primary: true, run: async () => { await sigC1Start(); sigOpPaint(); } },
    { label: ST("Licence requests", "Solicitudes de licencia"), run: async () => { await sigC95Licences(); sigOpPaint(); } },
    { label: ST("Payout setup", "Configurar pagos"), run: async () => { sigC98Payout(); sigOpPaint(); } },
    { label: ST("Rate starting points", "Tarifas iniciales"), run: async () => { sigC98Rates(); sigOpPaint(); } },
    { label: ST("Finish my profile", "Terminar mi perfil"), run: async () => { await sigC2Start(); sigOpPaint(); } },
    { label: ST("Setup from Instagram", "Configúrame desde Instagram"), run: async () => { sigSetupStart("creator"); sigOpPaint(); } },
    { label: ST("How am I doing?", "¿Cómo voy?"), run: async () => { await sigC3Run(); sigOpPaint(); } },
    { label: ST("How do I earn more?", "¿Cómo gano más?"), run: async () => { await sigC5Run(); sigOpPaint(); } },
    { label: ST("Invite a creator", "Invitar a un creador"), run: async () => { sigC4Run(); sigOpPaint(); } },
  ];
}
