function laneControlsHtml(c) {
  const compOn = !c || c.compOpen !== false;
  const rate = laneRateOf(c || {});
  const fee = laneFeeOf(c || {});
  // Build -98 (11g): blank fields pre-fill with the tier's
  // starting defaults. A set rate or fee always wins: the
  // defaults only ever fill a box that is empty, and nothing
  // is saved until the creator saves or turns the lane on.
  const defaults = rateStartingDefaults(c || {});
  const rateShown = rate || defaults.paidRate;
  const feeShown = fee || defaults.licensingFee;
  return `<div class="lane-ctl" id="lane-controls">
    ${!rate || !fee ? `<p class="small" id="lane-starting-line" style="margin:0 0 10px">${esc(rateStartingLine(c || {}))}</p>` : ""}
    ${compOn && rate ? "" : `<div class="lane-bothrow"><button type="button" class="btn small-btn" onclick="return laneBothOn()">Turn both on</button></div>`}
    <div class="lrow lane-row"><input type="checkbox" class="sw lane-sw" id="lane-comp" ${compOn ? "checked" : ""} onchange="laneToggleComp(this)"><div><label class="lname" for="lane-comp">I accept comped visits</label> <span class="lline" id="lane-comp-line">— ${esc(laneCompLine(c || {}))}</span></div></div>
    <div class="lrow lane-row"><input type="checkbox" class="sw lane-sw" id="lane-coupon" ${!c || c.couponOpen !== false ? "checked" : ""} onchange="laneToggleCoupon(this)"><div><label class="lname" for="lane-coupon">I accept coupons / store credit</label> <span class="lline" id="lane-coupon-line">— ${esc(laneCouponLine(c || {}))}</span></div></div>
    <div class="lrow lane-row"><input type="checkbox" class="sw lane-sw" id="lane-paid" ${rate ? "checked" : ""} onchange="laneTogglePaid(this)"><div><label class="lname" for="lane-paid">Paid bookings</label> <span class="lline" id="lane-paid-line">— ${esc(lanePaidLine(c || {}))}</span></div></div>
    <div class="lane-rate" id="lane-rate-row" style="display:${rate ? "block" : "none"}">
      <label for="lane-rate">Your paid rate (min ${ownCurrencySymbol()}${ownPaidFloor()})</label>
      <div class="lane-rate-flex"><input type="number" id="lane-rate" min="${ownPaidFloor()}" step="1" inputmode="numeric" placeholder="150" value="${rateShown}" onchange="laneRateAuto()"><button type="button" class="btn small-btn" onclick="return laneRateSave()">Save rate</button></div>
      <p class="small muted" id="lane-rate-note">${rate ? `Businesses pay your listed rate of ${ownCurrencySymbol()}${fmtMoney(rate)}. You keep ${ownCurrencySymbol()}${fmtMoney(Math.round(rate * 0.97 * 100) / 100)} (97%). A paid booking includes the standard license: 90 days of repost and ad use.` : "A starting point, filled in because your rate was blank. You keep 97%. A paid booking includes the standard license: 90 days of repost and ad use."}</p>
      <details class="deal-details"><summary class="small muted">How the rate and license work</summary><p class="small muted" style="margin:6px 0 0">${rate ? `Magpie holds the payment until your post is live. The standard license lets the business repost your post and run it as an ad for 90 days from the post date, never longer, and never edited.` : "Change the rate to whatever you charge, then save. You keep 97%, and Magpie holds the payment until your post is live. Paid bookings turn on when a rate is saved. The standard license lets the business repost your post and run it as an ad for 90 days from the post date, never longer, and never edited."}</p></details>
      <p class="small" id="lane-range-line"></p>
    </div>
    <div class="lrow lane-row"><div><span class="lname">Run my post as an ad</span> <span class="lline" id="lane-fee-line">— ${esc(laneFeeLine(c || {}))}</span></div></div>
    <div class="lane-rate">
      <div class="lane-rate-flex"><input type="number" id="lane-fee" min="1" step="1" inputmode="numeric" placeholder="75" value="${feeShown}"><button type="button" class="btn small-btn" onclick="return laneFeeSave()">Save fee</button></div>
      <p class="small muted">One price for 90 days of repost and ad use. You approve every request; nothing runs without your yes.</p>
      <details class="deal-details"><summary class="small muted">How this fee works</summary><p class="small muted" style="margin:6px 0 0">One price, in plain words: what a business pays to repost your post and run it as an ad for 90 days. The 90 days start the day you approve a request, and the license ends when the 90 days end, never longer. You approve or decline every request; nothing runs without your yes. ${fee ? "" : "The amount in the box is a starting point because your fee was blank. Change it to whatever you charge, then save. Clear the box and save to keep comped posts native-share only."}</p></details>
    </div>
    <p class="small lane-err" id="lane-err" style="display:none"></p>
    ${payoutsStepHtml(c)}
  </div>`;
}
// ---------- Connect Accounts: YouTube actions (2026-10-28) ----------
// Connect is a full-page trip to Google and back (the server
// answers /?yt=<status>); Sync now and Disconnect are in-place
// calls that swap in the fresh user payload and re-render the
// profile so the row states (locked input, Synced mark, buttons)
// always match the server.
function ytConnect() {
  window.location.href = "/api/me/platforms/youtube/start";
  return false;
}

function rerenderProfileTab() {
  const u = state.user;
  if (!u) return;
  if (u.founding && u.founding.marketLive) renderCreatorDash();
  else if (u.role === "creator") renderFoundingHome();
}

async function ytSyncNow() {
  const note = document.getElementById("yt-note");
  if (note) note.textContent = "Syncing...";
  try {
    const data = await api("POST", "/me/platforms/youtube/sync");
    state.user = data.user;
    if (data.ok === false && note) {
      // The re-render below replaces the note element; carry the
      // outcome in the notice slot instead so it survives.
      state.ytNotice = data.status === "hidden" ? "hidden" : "syncerror";
    }
    rerenderProfileTab();
  } catch (err) {
    if (note) note.textContent = err.message;
  }
  return false;
}

async function ytDisconnect() {
  if (!confirm("Disconnect YouTube? Your last synced subscriber count stays on your profile as a number you type and can edit, and it stops updating on its own.")) return false;
  try {
    const data = await api("POST", "/me/platforms/youtube/disconnect");
    state.user = data.user;
    rerenderProfileTab();
  } catch (err) {
    const note = document.getElementById("yt-note");
    if (note) note.textContent = err.message;
  }
  return false;
}

// Instagram connect (Build -108): the YouTube lane's shape,
// word for word where the shape is the same.
function igConnect() {
  window.location.href = "/api/me/platforms/instagram/start";
  return false;
}

async function igSyncNow() {
  const note = document.getElementById("ig-note");
  if (note) note.textContent = "Syncing...";
  try {
    const data = await api("POST", "/me/platforms/instagram/sync");
    state.user = data.user;
    if (data.ok === false) state.igNotice = "syncerror";
    else if (data.status === "below_minimum") state.igNotice = "below";
    else if (data.status === "no_data") state.igNotice = "nodata";
    else if (data.status === "verified") state.igNotice = "verified";
    rerenderProfileTab();
  } catch (err) {
    if (note) note.textContent = err.message;
  }
  return false;
}

async function igDisconnect() {
  if (!confirm("Disconnect Instagram? Your last synced follower count stays on your profile as a number you type and can edit, and your local shares go back to self-reported: the Verified mark comes off, because it is backed by this connection.")) return false;
  try {
    const data = await api("POST", "/me/platforms/instagram/disconnect");
    state.user = data.user;
    rerenderProfileTab();
  } catch (err) {
    const note = document.getElementById("ig-note");
    if (note) note.textContent = err.message;
  }
  return false;
}

// The verification state line under a connected Instagram row:
// per-market truth from the creator's own record.
function igVerificationLine(c) {
  const av = (c && c.audienceVerification) || null;
  if (!av) return "Your local shares have not been checked yet. Sync now runs the first check against Instagram's city data.";
  const per = av.perMarket || {};
  const verified = Object.keys(per).filter((m) => per[m] && per[m].withinTolerance);
  const below = Object.keys(per).filter((m) => per[m] && !per[m].withinTolerance && per[m].igPct < per[m].selfPct).map((m) => `${m}: Instagram ${per[m].igPct}% vs your ${per[m].selfPct}%`);
  if (av.note === "below_100") return "Instagram does not share city data for accounts under 100 followers, so your local shares stay self-reported for now.";
  if (av.note === "no_city_data") return "Instagram has not shared city data yet; it can lag about 48 hours. Your local shares stay self-reported until it lands.";
  if (verified.length) return `Verified from Instagram in ${verified.join(", ")}: the city data matches your stated share within 10 points.${below.length ? ` Not matching yet: ${below.join("; ")}.` : ""}`;
  return `Checked against Instagram's city data; no market matched within 10 points yet, so your shares stay labeled self-reported.${below.length ? ` ${below.join("; ")}.` : ""} Your stated numbers never change on their own.`;
}

// ---------- Connected accounts hub (Build -123) ----------
// One panel on the creator Profile that lists the audience
// platforms together — Instagram, TikTok, YouTube, Facebook —
// each with its honest state in plain words: connected as
// @handle with the last check date, a live Connect button, or
// the real reason it is not open yet (Meta review, TikTok in
// preparation). No dead clicks and no pretend connections: the
// rows render from GET /me/platforms, the same publicStates the
// server computes, and the audience rows above keep their own
// per-count controls.
function connectedAccountsHtml(u) {
  return `<div class="panel mt" id="connected-accounts">
    <h3>Connected accounts</h3>
    <p class="small muted">Connect a platform and Magpie reads your real numbers from it: the count verifies itself, stays up to date on its own, and businesses see a Synced mark next to it. Anything not connected stays typed by you and labeled Self-reported.</p>
    <div id="ca-rows"><p class="small muted">Loading your accounts...</p></div>
  </div>`;
}

async function loadConnectedAccounts() {
  const host = document.getElementById("ca-rows");
  if (!host || !state.user || state.user.role !== "creator") return;
  try {
    const data = await api("GET", "/me/platforms");
    const rows = (data.platforms || []).filter((p) => ["instagram", "tiktok", "youtube", "facebook"].includes(p.platform));
    host.innerHTML = rows.map(caRowHtml).join("");
  } catch (e) {
    host.innerHTML = `<p class="small">We could not load your accounts just now. Refresh the page to try again.</p>`;
  }
}

function caRowHtml(p) {
  const c = (state.user && state.user.creator) || {};
  const day = (iso) => (iso ? fmtDate(iso) : "");
  let body = "";
  if (p.state === "connected") {
    const checked = p.lastSyncAt ? ` · followers last checked ${esc(day(p.lastSyncAt))}` : "";
    const actions = p.platform === "youtube"
      ? `<p class="small" style="margin-top:4px"><button type="button" class="btn small-btn ghost" onclick="return ytSyncNow()">Sync now</button> <button type="button" class="btn small-btn ghost" onclick="return ytDisconnect()">Disconnect</button></p>`
      : p.platform === "instagram"
        ? `<p class="small" style="margin-top:4px"><button type="button" class="btn small-btn ghost" onclick="return igSyncNow()">Sync now</button> <button type="button" class="btn small-btn ghost" onclick="return igDisconnect()">Disconnect</button></p><p class="small muted" style="margin-top:4px">${igVerificationLine(c)}</p>`
        : "";
    body = `<p class="small" style="margin:0"><span class="badge">Connected</span> <span class="muted">as ${esc(p.accountLabel || p.label)}${checked}. This count updates on its own.</span></p>${actions}`;
  } else if (p.state === "available") {
    const go = p.platform === "youtube"
      ? `<button type="button" class="btn small-btn" onclick="return ytConnect()">Connect YouTube</button>`
      : `<button type="button" class="btn small-btn" onclick="return igConnect()">Connect Instagram</button>`;
    const does = p.platform === "youtube"
      ? "Connect it and your subscriber count verifies itself and stays up to date on its own."
      : "Connect it and your follower count syncs itself, and your local audience shares get checked against Instagram's own city data: markets that match earn the Verified mark.";
    body = `<p class="small muted" style="margin:0 0 6px">Not connected. ${does}</p>${go}`;
  } else if (p.platform === "youtube") {
    body = `<p class="small muted" style="margin:0">Coming soon: YouTube connect is being switched on. Until it opens, your subscriber count stays typed by you.</p>`;
  } else if (p.platform === "instagram") {
    body = `<p class="small muted" style="margin:0">Coming soon: Instagram connect is in review with Meta. Until it clears, your follower count and local shares stay typed by you.</p>`;
  } else if (p.platform === "tiktok") {
    body = `<p class="small muted" style="margin:0">Coming soon: TikTok connect is being prepared. For now your TikTok count stays typed by you.${c.tiktokHandle ? ` Your TikTok handle on file: @${esc(String(c.tiktokHandle).replace(/^@/, ""))}.` : ""}</p>`;
  } else if (p.platform === "facebook") {
    body = `<p class="small muted" style="margin:0">Facebook connect is covered by the same Meta review as Instagram, so it is not open yet. ${c.facebookUrl ? `Your Facebook link on your profile: ${esc(c.facebookUrl)}.` : "Add your Facebook profile or Page link under Your links on this page."} Your Facebook count stays typed by you until the review clears.</p>`;
  } else {
    body = `<p class="small muted" style="margin:0">Not connected.</p>`;
  }
  return `<div style="padding:10px 0;border-top:1px solid var(--line)"><p style="margin:0 0 4px"><strong>${esc(p.label)}</strong></p>${body}</div>`;
}

function igNoticeHtml() {
  const v = state.igNotice;
  if (!v) return "";
  state.igNotice = null;
  if (v === "connected") return `<div class="notice"><strong>Instagram is connected.</strong> Your follower count now updates on its own, and your local shares are checked against Instagram's city data. See the audience section below.</div>`;
  if (v === "verified") return `<div class="notice"><strong>Checked, and verified.</strong> Instagram's city data matches your stated local share in at least one market, so the Verified mark is on. Details in your audience section below.</div>`;
  if (v === "below") return `<div class="notice blue"><strong>Instagram is connected.</strong> Accounts under 100 followers do not get city data from Meta, so your local shares stay self-reported for now; your follower count is synced.</div>`;
  if (v === "nodata") return `<div class="notice blue"><strong>Instagram is connected.</strong> It has not shared city data yet (that can lag about 48 hours), so your local shares stay self-reported until it lands.</div>`;
  if (v === "error") return `<div class="notice"><strong>Instagram connect did not finish.</strong> Nothing changed. You can try again from your audience section below.</div>`;
  if (v === "unavailable") return `<div class="notice blue"><strong>Instagram connect is in review with Meta.</strong> Until it clears, your local shares stay typed by you and labeled Self-reported.</div>`;
  if (v === "syncerror") return `<div class="notice"><strong>That sync did not come through.</strong> Your last checked state stands. Try Sync now again in a bit.</div>`;
  return "";
}

// The one-shot notice the OAuth return (?yt=) leaves behind.
// Rendered once by the profile form, then cleared.
function ytNoticeHtml() {
  const v = state.ytNotice;
  if (!v) return "";
  state.ytNotice = null;
  if (v === "connected") return `<div class="notice"><strong>YouTube is connected.</strong> Your subscriber count now updates on its own and shows to businesses as Synced. Find it in your audience section below.</div>`;
  if (v === "error") return `<div class="notice"><strong>YouTube connect did not finish.</strong> Nothing changed. You can try again from your audience section below.</div>`;
  if (v === "unavailable") return `<div class="notice blue"><strong>YouTube connect is being switched on.</strong> Until it opens, your subscriber count stays typed by you and labeled Self-reported.</div>`;
  if (v === "hidden") return `<div class="notice blue"><strong>Your YouTube channel hides its subscriber count,</strong> so there is nothing for the sync to read. Your typed count stays, labeled Self-reported.</div>`;
  if (v === "syncerror") return `<div class="notice"><strong>That sync did not come through.</strong> Your last synced count stands. Try Sync now again in a bit.</div>`;
  return "";
}

function laneErr(msg) {
  const e = document.getElementById("lane-err");
  if (e) { e.textContent = msg || ""; e.style.display = msg ? "block" : "none"; }
}
// Payout setup step (Stripe Connect, 2026-10-26): part of the
// paid lane only, and only once a rate is listed. Joining,
// claiming and comp visits never need it. The states are the
// server's plain words (never raw Stripe requirement codes), and
// the step is resumable: the button always reopens Stripe's
// hosted pages where the creator left off.
function payoutExplainerAckKey() {
  return "signl_payout_explainer_seen:" + (state.user && state.user.id ? state.user.id : "");
}
function payoutExplainerAcked() {
  try { return typeof localStorage !== "undefined" && !!localStorage.getItem(payoutExplainerAckKey()); } catch (e) { return false; }
}
function ackPayoutExplainer() {
  try { localStorage.setItem(payoutExplainerAckKey(), "1"); } catch (e) { /* private mode: hiding for this screen is enough */ }
  const el = document.getElementById("payout-explainer");
  if (el) el.style.display = "none";
  return false;
}
// UK payouts (Build -109, item 20): the market's country picks
// the explainer variant, here and in the payout step below: a
// London creator gets the UK words (sort code, Faster
// Payments, sole trader vs limited company, the generic UK tax
// line) and never hears about Form 1099-K. Wording is flagged
// for Jeff/legal review in the Tier 3 report.
function userMarketCountry() {
  const u = state.user || {};
  const markets = (state.boot && state.boot.markets) || [];
  const hit = markets.find((m) => m && (m.name === u.market || m.id === u.market));
  return (hit && hit.country) || null;
}
function isUkUser() {
  return userMarketCountry() === "United Kingdom";
}
function payoutExplainerUkHtml(lastMargin) {
  return `<p style="margin:0 0 6px"><strong>What payout setup will ask for, and why</strong></p>
    <p class="small" style="margin:0 0 6px">Stripe runs payout setup on its own secure pages. Stripe will ask for identity details, like your name and date of birth, because payment companies have to check who money is going to. It will ask for your address, as part of that same identity check. It will ask for a UK bank account, your sort code and account number, so money can go to your bank; payouts arrive by Faster Payments. Your bank details go to Stripe, never to Magpie.</p>
    <p class="small" style="margin:0 0 6px">Whether you sign up as a sole trader or through a limited company changes what Stripe asks for: a sole trader uses their own identity details; a limited company also gives the company's details and a director's.</p>
    <p class="small" style="margin:0 0 6px">Taxes, in plain words: you are responsible for your own UK tax position, and Magpie does not withhold tax from your earnings.</p>
    <p class="small" style="margin:0 0 6px">Your first payout can be held briefly while identity checks clear. That is a check finishing, not money lost.</p>
    <p class="small" style="margin:0${lastMargin ? " 0 8px" : ""}">Paid bookings are recorded in the app. You are paid after your post is live and verified, within 48 hours, once your payout details are set up.</p>`;
}

// Build -98 (11h): the payout-paperwork explainer copy, shared
// by Help. The payout step below carries the same words inline
// (its renderer is exercised on its own by the Connect suite).
function payoutExplainerHtml() {
  if (isUkUser()) return `<div id="help-payout-explainer" style="text-align:left">${payoutExplainerUkHtml()}</div>`;
  return `<div id="help-payout-explainer" style="text-align:left">
    <p style="margin:0 0 6px"><strong>What payout setup will ask for, and why</strong></p>
    <p class="small" style="margin:0 0 6px">Stripe runs payout setup on its own secure pages. Stripe will ask for identity details, like your name and date of birth, because payment companies have to check who money is going to. It will ask for your address, as part of that same identity check. It will ask for your bank account, so money can go to your bank; your bank details go to Stripe, never to Magpie. And it will ask for tax information, so paid earnings can be reported the right way.</p>
    <p class="small" style="margin:0 0 6px">Taxes, in plain words: if your paid earnings pass the reporting threshold for a tax year, you may get a Form 1099-K for that year. It is a tax record of money paid to you, not a bill. Keep it for your taxes.</p>
    <p class="small" style="margin:0 0 6px">Your first payout can be held briefly while identity checks clear. That is a check finishing, not money lost.</p>
    <p class="small" style="margin:0">Paid bookings are recorded in the app. You are paid after your post is live and verified, within 48 hours, once your payout details are set up.</p>
  </div>`;
}
function payoutsStepHtml(c) {
  // The paid lane is "on" exactly when a rate is listed, the
  // same derivation the lane control itself uses.
  if (!laneRateOf(c || {})) return "";
  const p = c.payouts || { status: "not_started", ready: false, missing: [] };
  // Build -98 (11h): before a creator's FIRST payout setup, and
  // only until they tap Got it, the step carries the explainer:
  // what Stripe asks for and why, 1099-K in plain words, and why
  // a first payout can be held. It is inline here so this
  // renderer stays self-contained. Once setup has started
  // (pending, restricted, or ready) it never shows again, and
  // Help carries the same words any time.
  let explainer98 = "";
  if (p.status === "not_started" && !p.ready) {
    let acked98 = false;
    try { acked98 = typeof localStorage !== "undefined" && !!localStorage.getItem("signl_payout_explainer_seen:" + (state.user && state.user.id ? state.user.id : "")); } catch (e) { acked98 = false; }
    if (!acked98) explainer98 = isUkUser()
      ? `<div id="payout-explainer" style="margin:10px 0;text-align:left">${payoutExplainerUkHtml(true)}
      <button type="button" class="btn small-btn ghost" onclick="return ackPayoutExplainer()">Got it</button>
    </div>`
      : `<div id="payout-explainer" style="margin:10px 0;text-align:left">
      <p style="margin:0 0 6px"><strong>What payout setup will ask for, and why</strong></p>
      <p class="small" style="margin:0 0 6px">Stripe runs payout setup on its own secure pages. Stripe will ask for identity details, like your name and date of birth, because payment companies have to check who money is going to. It will ask for your address, as part of that same identity check. It will ask for your bank account, so money can go to your bank; your bank details go to Stripe, never to Magpie. And it will ask for tax information, so paid earnings can be reported the right way.</p>
      <p class="small" style="margin:0 0 6px">Taxes, in plain words: if your paid earnings pass the reporting threshold for a tax year, you may get a Form 1099-K for that year. It is a tax record of money paid to you, not a bill. Keep it for your taxes.</p>
      <p class="small" style="margin:0 0 6px">Your first payout can be held briefly while identity checks clear. That is a check finishing, not money lost.</p>
      <p class="small" style="margin:0 0 8px">Paid bookings are recorded in the app. You are paid after your post is live and verified, within 48 hours, once your payout details are set up.</p>
      <button type="button" class="btn small-btn ghost" onclick="return ackPayoutExplainer()">Got it</button>
    </div>`;
  }
  if (!paymentsLive()) {
    return `<div class="lane-payouts"><div class="lrow lane-row"><div><span class="lname">Payouts</span><span class="lline"> — setup opens when the paid lane goes live. Comp visits never need it.</span></div></div>${explainer98}</div>`;
  }
  if (p.ready) {
    return `<div class="lane-payouts"><div class="lrow lane-row"><div><span class="lname">Payouts</span><span class="lline"> — <span class="badge ok">Payouts ready</span></span></div></div><p class="small muted">Paid bookings pay out to your bank after your post is live.</p></div>`;
  }
  if (p.status === "pending" || p.status === "restricted") {
    const missing = (p.missing || []).length ? ` Stripe still needs: ${esc(p.missing.join(", "))}.` : "";
    return `<div class="lane-payouts"><div class="lrow lane-row"><div><span class="lname">Payouts</span><span class="lline"> — almost there.${missing}</span></div></div><button type="button" class="btn small-btn" onclick="return startPayoutSetup()">Finish payout setup</button><p class="small muted">Your first payout can take longer while Stripe verifies you.</p></div>`;
  }
  return `<div class="lane-payouts"><div class="lrow lane-row"><div><span class="lname">Payouts</span><span class="lline"> — not set up. You can be booked at your rate, but the money cannot reach your bank until this is done.</span></div></div>${explainer98}<button type="button" class="btn small-btn" onclick="return startPayoutSetup()">Set up payouts</button><p class="small muted">Two minutes on Stripe's secure pages: your bank details go to Stripe, never to Magpie. Your first payout can take longer while Stripe verifies you.</p></div>`;
}
async function startPayoutSetup() {
  try {
    const data = await api("POST", "/me/payouts/start", {});
    if (data && data.url) { window.location.href = data.url; return false; }
    // Build -189 (PL-62): a concierge market answers with the
    // path itself, shown as information, not as an error.
    if (data && data.message) { laneErr(data.message); return false; }
    laneErr("Payout setup could not open. Try again.");
  } catch (err) { laneErr((err && err.message) || "Payout setup could not open. Try again."); }
  return false;
}
// Business card on file (Stripe Connect, 2026-10-26): opens
// Stripe Checkout in setup mode; the saved card lands on the
// record through the webhook and shows under Plan.
async function addBusinessCard() {
  try {
    const data = await api("POST", "/billing/card", {});
    if (data && data.url) { window.location.href = data.url; return false; }
    alert("Card setup could not open. Try again.");
  } catch (err) { alert((err && err.message) || "Card setup could not open. Try again."); }
  return false;
}
function cardOnFileSectionHtml() {
  const card = cardOnFileView();
  if (card) {
    return `<div class="mt"><p><span class="badge ok">Card on file</span> <strong>${esc(brandName(card.brand))} &middot;&middot;&middot;&middot;${esc(card.last4)}</strong></p><p class="small muted">Paid bookings charge this card when you book. Magpie holds the money until the creator's post is live.</p><button class="btn ghost small-btn" onclick="return addBusinessCard()">Update card</button></div>`;
  }
  return `<div class="mt"><p><strong>No card on file.</strong></p><p class="small muted">Paid bookings need a card: it is charged when you book, Magpie holds the money until the creator's post is live, and the creator is paid from it.</p><button class="btn small-btn" onclick="return addBusinessCard()">Add a card</button></div>`;
}
// Held / released money status on a booking card (Stripe
// Connect, 2026-10-26). Renders nothing unless real funds ride
// on the booking; the ledger states above it are unchanged.
function fundsStatusHtml(lane, role) {
  const f = lane && lane.funds;
  if (!f) return "";
  if (role === "creator") {
    if (f.state === "released") return `<br><span class="muted">Released · on its way to your bank.</span>`;
    if (f.state === "refunded") return `<br><span class="muted">Refunded to the business in full.</span>`;
    if (f.state === "needs_card" || f.state === "charge_failed") return `<br><span class="muted">Magpie is sorting out the business's card with the business.</span>`;
    if (f.blockedReason === "payouts_not_ready") return `<br><span class="muted">Held · finish payout setup under Profile to release it.</span>`;
    return `<br><span class="muted">Held · releases when your post is live.</span>`;
  }
  if (f.state === "released") return `<br><span class="muted">Paid · released to the creator.</span>`;
  if (f.state === "refunded") return `<br><span class="muted">Paid · refunded in full.</span>`;
  if (f.state === "needs_card" || f.state === "charge_failed") return `<br><span class="muted">Add a card under Plan to complete this booking's payment.</span>`;
  return `<br><span class="muted">Paid · held until the post is live.</span>`;
}
function rerenderLaneControls() {
  const host = document.getElementById("lane-controls");
  if (!host || !state.user || !state.user.creator) return;
  const rateInput = document.getElementById("lane-rate");
  const typed = rateInput ? rateInput.value : "";
  const row = document.getElementById("lane-rate-row");
  const rowOpen = !!row && row.style.display !== "none";
  host.outerHTML = laneControlsHtml(state.user.creator);
  const sp = document.getElementById("spanish-panel");
  if (sp) sp.outerHTML = spanishPanelHtml(state.user.creator);
  const mp = document.getElementById("music-panel");
  if (mp) mp.outerHTML = musicPanelHtml(state.user.creator);
  const pp = document.getElementById("proximity-panel");
  if (pp) pp.outerHTML = proximityPanelHtml(state.user.creator);
  const bp = document.getElementById("bookme-panel");
  if (bp) bp.outerHTML = bookMePanelHtml(state.user.creator);
  if (rowOpen) {
    const r2 = document.getElementById("lane-rate-row");
    if (r2) r2.style.display = "block";
    if (typed && !laneRateOf(state.user.creator)) {
      const ni = document.getElementById("lane-rate");
      if (ni) ni.value = typed;
    }
  }
}
async function laneSave(patch) {
  laneErr("");
  try {
    const data = await api("PATCH", "/me/profile", patch);
    if (data && data.user) state.user = data.user;
    rerenderLaneControls();
    // Build -115 (no-dead-ends rule): every lane save confirms
    // visibly. The toast is body-level, so it survives the
    // in-place re-render of the lane controls.
    showToast("Saved.");
    return true;
  } catch (err) {
    rerenderLaneControls();
    laneErr((err && err.message) || "That didn't save. Try again.");
    return false;
  }
}
function laneToggleSpanish(input) {
  laneSave({ spanishContent: !!input.checked });
  return true;
}
function laneToggleMusician(input) {
  laneSave({ musician: !!input.checked });
  return true;
}
function laneToggleMusicPerform(input) {
  laneSave({ musicPerform: !!input.checked });
  return true;
}
function laneToggleMusicCreate(input) {
  laneSave({ musicCreate: !!input.checked });
  return true;
}
function laneToggleComp(input) {
  laneSave({ compOpen: !!input.checked });
  return true;
}
function laneToggleCoupon(input) {
  laneSave({ couponOpen: !!input.checked });
  return true;
}
function laneTypedRate() {
  const inp = document.getElementById("lane-rate");
  const v = inp ? Number(inp.value) : NaN;
  return Number.isFinite(v) && v > 0 ? v : null;
}
function laneOpenRateEntry(msg) {
  const row = document.getElementById("lane-rate-row");
  if (row) row.style.display = "block";
  const inp = document.getElementById("lane-rate");
  if (inp) inp.focus();
  const note = document.getElementById("lane-rate-note");
  if (note && msg) note.textContent = msg;
}
function laneTogglePaid(input) {
  if (!input.checked) { laneSave({ paidRate: null }); return true; }
  const rate = laneRateOf(state.user.creator || {}) || laneTypedRate();
  if (rate && rate >= ownPaidFloor()) { laneSave({ paidRate: rate }); return true; }
  laneOpenRateEntry(`Set a rate (min ${ownCurrencySymbol()}${ownPaidFloor()}), then tap Save rate — paid bookings turn on.`);
  return true;
}
function laneRateSave() {
  const v = laneTypedRate();
  if (!v || v < ownPaidFloor()) {
    laneErr(`Paid bookings need a rate of at least ${ownCurrencySymbol()}${ownPaidFloor()}.`);
    const inp = document.getElementById("lane-rate");
    if (inp) inp.focus();
    return false;
  }
  laneSave({ paidRate: Math.round(v * 100) / 100 });
  return false;
}
function laneRateAuto() {
  // Typing a valid rate while the paid switch is on saves it, so
  // the rate and the toggle land together.
  const sw = document.getElementById("lane-paid");
  const v = laneTypedRate();
  if (sw && sw.checked && v && v >= ownPaidFloor() && v !== laneRateOf(state.user.creator || {})) laneSave({ paidRate: Math.round(v * 100) / 100 });
  return true;
}
function laneBothOn() {
  const rate = laneRateOf(state.user.creator || {}) || laneTypedRate();
  if (rate && rate >= ownPaidFloor()) { laneSave({ compOpen: true, paidRate: rate }); return false; }
  laneSave({ compOpen: true });
  laneOpenRateEntry(`Comp is on. Set a rate (min ${ownCurrencySymbol()}${ownPaidFloor()}), then tap Save rate — paid bookings turn on too.`);
  return false;
}

