function samplePreviewHtml(s) {
  const t = s.totals || {};
  return `<section class="wcard sample-story">
    <div class="flex-between" style="flex-wrap:wrap;gap:8px">
      <h3 style="margin:0">See what your results will look like</h3>${sampleBadgeHtml()}
    </div>
    <p style="margin:8px 0 0">A sample campaign on sample profiles: <strong>${fmtNum(t.visitsDone || 0)} creators visited, ${fmtNum(t.postsLive || 0)} posts went live, and ${fmtNum(t.customersCounted || 0)} customers were counted at the counter.</strong> None of it is yours yet. It is here so you know what this page becomes.</p>
    <div class="mt"><button class="btn ghost" type="button" onclick="return toggleSampleStory(this)">See the sample</button></div>
    <div class="sample-full" style="display:none;margin-top:14px">${sampleStoryHtml(s)}</div>
  </section>`;
}
function toggleSampleStory(btn) {
  const wrap = btn.closest(".sample-story");
  const full = wrap ? wrap.querySelector(".sample-full") : null;
  if (full) {
    const open = full.style.display !== "none";
    full.style.display = open ? "none" : "";
    btn.textContent = open ? "See the sample" : "Hide the sample";
  }
  return false;
}
// Mounts the sample story (or its preview block) into
// #biz-sample on Results. fullIfViewAs: the Admin view-as demo
// context gets the whole story; a business in its own account
// gets the labeled preview block over its real (empty) results.
async function loadSampleResultsInto(fullIfViewAs) {
  const host = document.getElementById("biz-sample");
  if (!host) return;
  try {
    const d = await api("GET", "/me/sample-results");
    if (!d || !d.sample) return;
    if (!document.getElementById("biz-sample")) return;
    host.innerHTML = fullIfViewAs && d.context === "view-as" ? sampleStoryHtml(d.sample) : samplePreviewHtml(d.sample);
  } catch (e) { /* the sample is a demo extra, never a blocker */ }
}

// Build -99: the Build -74 start-here cards are retired. Their
// moves (save creators, open a campaign) are items in the ONE
// setup checklist on Home (setupChecklistHtml, fed by
// GET /me/setup-checklist), alongside the proof-kit steps and
// the Square connect. One setup surface, not three.

async function loadFoundingBusinessHome() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  const u = state.user;
  // Build -137 home: Sig hero, Quick highlights, Next steps,
  // stop. The founding facts (spot held, plan, credit) ride
  // the hero brief and the Wallet row; the setup checklist
  // stays while unfinished, its editors live nowhere else.
  const bz137 = u.business || {};
  const plan137f = foundingPlan();
  const credit137f = plan137f && typeof plan137f.foundingCredit === "number" ? plan137f.foundingCredit : 100;
  el.innerHTML = `
  ${wsHead("Home", { sub: "Start here.", subKey: "biz-home" })}
  <div class="home-greet"><div class="hg-hi">Hi, ${esc(bz137.businessName || u.name || "")}</div><div class="hg-line serif-line">Your founding spot is held. ${esc(foundingBizPlace(u))} opens soon, and we email you the day it does.</div></div>
  ${sigHero137Html(`You are on the founding roster for ${foundingBizPlace(u)}. Nothing is due and nothing is charged. Get your page ready and draft your first campaign now; it goes out the day your market opens.`)}
  ${bizGuideStartersHtml()}
  ${sqNoticeHtml()}
  <div id="fbz-highlights"></div>
  <div id="biz-setup-checklist"></div>
  <div id="fbz-sig-queue" style="margin-top:14px"></div>`;
  loadSigTopNudges();
  // Sig's queue for a founding business: the two things worth
  // doing before opening day. The same items feed the Sig tab
  // and the rail badge, like every other queue.
  const items = [];
  try {
    const staff = await api("GET", "/me/staff");
    if (staff && !staff.staffPinSet) items.push({ text: "Set your staff PIN before your first visit, so your team can mark visits at the counter.", btn: "Set PIN", act: () => go("dashboard", "Visits & Posts") });
  } catch (e) { /* the queue is a nudge, never a blocker */ }
  // Build -91: wishlist and roster-digest alerts join the
  // founding queue too — they are the pre-open moves this home
  // exists for.
  try {
    const nd = await api("GET", "/notifications");
    for (const n of sigAlertNotes(nd && nd.notifications)) {
      const a = sigAlertAction(n);
      items.push({ text: n.text, btn: a.btn, act: a.act });
    }
  } catch (e) { /* the queue is a nudge, never a blocker */ }
  // Build -97 proactive prompt, real records only: a founding
  // business with no campaign drafts at all gets pointed at
  // the guided setup. A business that already saved a draft
  // hears nothing here.
  try {
    const od = await api("GET", "/offers");
    const myOffers = (od && od.offers) || [];
    state._fbzOfferCount = myOffers.length;
    if (!myOffers.length) items.push({ text: "No campaign drafts yet. Set one up now, with Maggie or step by step, and it is ready for opening day.", btn: "Start a campaign", act: () => go("dashboard", "Campaign Setup") });
  } catch (e) { /* the queue is a nudge, never a blocker */ }
  // Build -99: the ONE setup checklist renders on this Home
  // too, and its register item joins the queue when Square is
  // switched on and not yet connected (real state only).
  try {
    const cd = await api("GET", "/me/setup-checklist");
    const cl = cd && cd.setupChecklist;
    state._setupChecklist = cl || null;
    const host2 = document.getElementById("biz-setup-checklist");
    if (host2 && cl) host2.innerHTML = setupChecklistHtml(cl);
    if (cl && cl.register && cl.register.configured && cl.register.state === "not_connected") items.push({ text: "Your register isn't connected yet. Connect it and code visits count themselves.", btn: "Connect Square", act: () => { const c = document.getElementById("setup-checklist"); if (c) c.scrollIntoView({ behavior: "smooth", block: "start" }); } });
  } catch (e) { /* the checklist is a guide, never a blocker */ }
  const bz = u.business || {};
  if (!bz.about) items.push({ text: "Your business page has no story yet. A few lines about your store is what creators read before they apply.", btn: "Write it", act: () => go("dashboard", "Profile") });
  state.sigQueue = items;
  state.sigQueueLinks = [];
  state.sigQueueCount = items.length;
  // Build -137: fill the Quick highlights from real records
  // (drafts saved, visits counted at the counter, the plan).
  let fbzBk = [];
  try { const bd137 = await api("GET", "/bookings"); fbzBk = bd137.bookings || []; } catch (e) { /* no bookings yet */ }
  const hlHost = document.getElementById("fbz-highlights");
  if (hlHost) hlHost.innerHTML = highlights137Html([
    { label: "Campaign drafts", sub: "Saved for opening day", value: String(state._fbzOfferCount || 0) },
    { label: "Visits counted", sub: "Counted at your counter", value: String(fbzBk.filter((b) => b.redeemedAt).length) },
    { label: "Wallet", sub: `$${fmtPrice(credit137f)} founding credit banked`, value: (plan137f ? plan137f.name : null) || bz137.planName || "Founding", tab: "Plan" },
  ]);
  const host = document.getElementById("fbz-sig-queue");
  if (host && document.getElementById("tab-body")) {
    const clF = state._setupChecklist;
    const nxItems = items.filter((it) => !(clF && !clF.allDone && ((it.text || "").indexOf("Your register isn't connected yet") === 0 || (it.text || "").indexOf("Your business page has no story yet") === 0)));
    if (nxItems.length) {
      host.innerHTML = nextSteps137Html(nxItems.slice(0, 3), []);
      wireSigQueue(host, nxItems.slice(0, 3), []);
    }
    renderNav();
  }
}

// Sig's drafted first campaign, as a card on Campaigns
// (Build -68): the same play machinery Sig's B1 flow and the
// old founding preview used (SIG_PLAYS + briefFromParts).
// "Open draft" loads the play into the real composer as a
// draft the business edits and saves; "Start fresh" clears
// the composer draft back to blank.
function sigDraftCardHtml(u) {
  const bz = u.business || {};
  const bizName = bz.businessName || "your business";
  const recId = SIG_PLAY_BY_CATEGORY[bz.category || ""] || "weekend_fill";
  const play = sigPlay(recId) || sigPlay("weekend_fill");
  if (!play) return "";
  return `<section class="wcard" style="margin-top:14px">
    <div style="display:flex;gap:12px;align-items:center">
      ${sigAvatarHtml("greet")}
      <div>
        <p class="ui-kicker" style="margin:0">Drafted by Maggie</p>
        <h3 style="margin:2px 0 0">Your first campaign is already drafted</h3>
      </div>
    </div>
    <p class="wc-sub" style="margin-top:10px">Maggie picked the <strong>${esc(play.name)}</strong> play for ${esc(bizName)}: ${esc(play.spots)} creators, a ${esc(play.windowDays)} day visit window, brief and timing preset. Open it, change anything, and save it for opening day.</p>
    <div class="cta-row" style="justify-content:flex-start;margin-top:12px">
      <button class="btn" type="button" onclick="return foundingOpenSigDraft()">Open draft</button>
      <button class="btn ghost" type="button" onclick="return foundingStartFresh()">Start fresh</button>
    </div>
  </section>`;
}
function foundingOpenSigDraft() {
  const u = state.user;
  const bz = u.business || {};
  const recId = SIG_PLAY_BY_CATEGORY[bz.category || ""] || "weekend_fill";
  const play = sigPlay(recId) || sigPlay("weekend_fill");
  if (!play) return false;
  const d = state.offerDraft || (state.offerDraft = {});
  const bizName = bz.businessName || "";
  d.play = play.id;
  d.briefGoal = play.goal;
  d.briefHook = playFill(play.hook, bizName, d.comped || "a visit on us");
  d.briefMust = [bizName, ...play.mustExtra].filter(Boolean).join("\n");
  d.briefDont = "";
  d.briefTiming = play.timing;
  d.briefCta = play.cta;
  d.spots = String(play.spots);
  d.windowdays = String(play.windowDays);
  d.applydays = String(play.applyDays);
  if (bz.moment) d.moment = bz.moment;
  state.composerLane = "open";
  state.offerTarget = null;
  state.offersSeg = "live";
  loadCampaignSetup();
  setTimeout(() => { const c = document.getElementById("offer-composer"); if (c) c.scrollIntoView({ behavior: "smooth" }); }, 60);
  return false;
}
function foundingStartFresh() {
  state.offerDraft = {};
  state.offerTarget = null;
  state.composerLane = "open";
  loadCampaignSetup();
  setTimeout(() => { const c = document.getElementById("offer-composer"); if (c) c.scrollIntoView({ behavior: "smooth" }); }, 60);
  return false;
}

