const BUSINESS_TABS = ["Home", "Requests", "Discover", "Block", "Favorites", "Campaign Setup", "My Offers", "Counter", "Visits & Posts", "Regulars", "Content", "Analytics", "Plan", "Messages", "Profile", "Settings", "Help", "Sig"];

function renderBusinessDash() {
  const u = state.user;
  let tab = state.tab || "Home";
  if (!BUSINESS_TABS.includes(tab)) tab = "Home";
  // A "Send offer" from Discover lands on the composer, which
  // lives in Start a campaign since Build -97.
  if (state.offerTarget) tab = "Campaign Setup";
  // V3: Requests is the Applicants segment of Offers (§5.2).
  if (tab === "Requests") { state.offersSeg = "applicants"; tab = "My Offers"; }
  state.tab = tab;
  app.innerHTML = `<div class="wrap"><div id="tab-body"></div></div>`;
  // Build -68: founding intercepts. Home, Visits, Results,
  // Posts & licenses and Messages carry founding states; every
  // other tab runs its real renderer (Discover, Campaigns,
  // Plan & billing, Your business page, Settings, Help, Sig).
  const founding = isFoundingBusiness(u);
  if (tab === "Home") { founding ? loadFoundingBusinessHome() : loadBusinessHome(); loadBlockHome213("business"); }
  if (tab === "Discover") loadDiscover();
  if (tab === "Block") renderBlockTab213();
  if (tab === "Favorites") loadFavorites();
  if (tab === "Campaign Setup") loadCampaignSetup();
  if (tab === "My Offers") loadMyOffers();
  if (tab === "Counter") founding ? renderFoundingVisitsTab() : renderCounter();
  if (tab === "Visits & Posts") founding ? renderFoundingVisitsTab() : loadMyVisits("business");
  if (tab === "Regulars") renderRegularsTab();
  if (tab === "Content") founding ? renderFoundingContentTab() : renderContentTab();
  if (tab === "Analytics") founding ? renderFoundingResultsTab() : renderAnalyticsTab();
  if (tab === "Plan") renderPlanTab();
  if (tab === "Messages") founding ? renderFoundingMessagesTab() : loadThreads();
  if (tab === "Profile") renderBizProfileTab();
  if (tab === "Settings") renderSettingsTab();
  if (tab === "Help") renderHelpTab();
  if (tab === "Sig") renderSigTab();
}

// ---------- partner dashboard (Jeff, 2026-10-28) ----------
// A distribution partner's home: the same shell, cards, and
// tokens as the business dashboard, fed by one payload
// (GET /partner/summary) computed from the records stamped with
// the partner's own signup source. A partner with no activity
// yet gets the fills-in voice, never a grid of zeros.
const PARTNER_TABS = ["Home", "Markets", "Creators", "Businesses", "Messages", "Performance", "Earnings", "Links", "Account", "Help", "Sig", "Team"];

// Co-brand (Build -105): when Admin has set a partner brand,
// the partner's name and logo lead their shell and "Powered by
// Magpie" sits underneath. Magpie's own chrome never disappears,
// and with no brand set this returns "" so the shell renders
// exactly as before. The accent restyles only this shell's
// primary buttons and links (the .pt-shell rules in theme-v2.css).
function coBrandHeadHtml(brand) {
  if (!brand || (!brand.displayName && !brand.logoUrl)) return "";
  return `<div class="pt-brand-head">
    ${brand.logoUrl ? `<img class="pt-brand-logo" src="${esc(brand.logoUrl)}" alt="" onerror="this.remove()">` : ""}
    <div>
      ${brand.displayName ? `<div class="pt-brand-name">${esc(brand.displayName)}</div>` : ""}
      <div class="pt-brand-powered">Powered by Magpie</div>
    </div>
  </div>`;
}

function coBrandShellOn(el, brand) {
  if (!el) return;
  if (brand) {
    el.classList.add("pt-shell");
    el.style.setProperty("--pt-accent", brand.accentColor || "#006AFC");
  } else {
    el.classList.remove("pt-shell");
    el.style.removeProperty("--pt-accent");
  }
}

function renderPartnerDash() {
  const u = state.user;
  let tab = state.tab || "Home";
  if (!PARTNER_TABS.includes(tab)) tab = "Home";
  state.tab = tab;
  app.innerHTML = `<div class="wrap"><div id="tab-body"><div class="sig-load-row">${sigAvatarHtml("think")}</div>${skelHtml("Loading your dashboard...", 2)}</div></div>`;
  loadPartnerSummary().then(() => renderPartnerTab(tab)).catch((e) => {
    const el = document.getElementById("tab-body");
    if (el) el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`;
  });
}

async function loadPartnerSummary(force) {
  if (state.partnerData && !force) return state.partnerData;
  state.partnerData = await api("GET", "/partner/summary");
  return state.partnerData;
}

// Partner area strip (Build -119, design): Overview /
// Businesses / Money / Reports is one area system across the
// partner console; the strip rides under each screen's head.
// Build -125: the strip's third stop reads Wallet, like
// everywhere else.
function partnerStrip119(tab) {
  // Build -189 (PL-34): retired, renders nothing. The partner
  // shell's rail, bar and menu are the one nav system now.
  return "";
}
function ptEarnSetSeg(v) { state.partnerEarnSeg = v; renderPartnerTab("Earnings"); return false; }
function renderPartnerTab(tab) {
  const el = document.getElementById("tab-body");
  if (!el || !state.partnerData) return;
  const d = state.partnerData;
  if (tab === "Home") { el.innerHTML = partnerHomeHtml(d); wireSigQueue(el, [], state.sigQueueLinks || []); loadSigTopNudges(); }
  if (tab === "Markets") el.innerHTML = partnerMarketsHtml(d);
  if (tab === "Creators") el.innerHTML = partnerCreatorsHtml(d);
  if (tab === "Businesses") el.innerHTML = partnerBusinessesHtml(d);
  if (tab === "Messages") loadThreads();
  if (tab === "Performance") { el.innerHTML = `<div id="pt-stats"></div>` + partnerPerformanceHtml(d); loadPartnerStats(); }
  if (tab === "Earnings") el.innerHTML = partnerEarningsHtml(d);
  if (tab === "Links") el.innerHTML = partnerLinksHtml(d);
  if (tab === "Account") el.innerHTML = partnerAccountHtml(d);
  if (tab === "Help") el.innerHTML = partnerHelpHtml(d);
  if (tab === "Team") el.innerHTML = teamTabHtml();
  if (tab === "Sig") el.innerHTML = partnerSigHtml(d);
  // Co-brand (Build -105): the partner's brand leads every tab
  // of their shell; no brand set, nothing changes.
  const pBrand = d.partner && d.partner.brand;
  coBrandShellOn(el, pBrand);
  const pBrandHead = coBrandHeadHtml(pBrand);
  if (pBrandHead) el.insertAdjacentHTML("afterbegin", pBrandHead);
  // Build -189 (PL-34): the in-page partner strip is deleted.
  // One nav system per role: rail on desktop, bar + menu on
  // phones. partnerStrip119 stays defined for older callers but
  // renders nothing.
  if (tab === "Sig") wireScopedSig(el);
  if (tab === "Home") loadPartnerScopeHeads(d);
  if (tab === "Earnings") loadPartnerPacks();
  if (tab === "Markets") loadPartnerRace();
  if (tab === "Team") loadTeamTab();
  // Sig's living face rides the same hero stack as the Sig tab
  // (sigHeroSet): idle on the Overview presence card; a greet
  // one-shot the first time the partner opens their Sig, idle
  // after. Reduced motion and failed clips leave the poster.
  if (el.querySelector("[data-sig-hero-media]")) {
    if (tab === "Sig" && !state._ptSigGreeted) { state._ptSigGreeted = 1; sigHeroSet("greet"); }
    else sigHeroSet("idle");
  }
}

function partnerSampleChip(d) {
  return d.partner.demo ? ` <span class="badge warn">Sample data</span>` : "";
}

// Team seats (Build -107): the org lead's seat manager. One
// view: who holds seats, what each seat can reach, and the
// invite form. Revoking ends access on the seat's next
// request; the work they did stays credited.
function teamTabHtml() {
  return `
  <h2 style="margin-bottom:2px">Your team</h2>
  <p class="muted" style="margin-top:0">People you seat get their own login for your scopes only. They set their own password from the invite email; nobody ever sees it but them. Revoking a seat ends access on their next request, and everything they brought in stays credited.</p>
  <div id="pt-team"><p class="muted">Loading your team…</p></div>`;
}
function teamSeatsHtml(d) {
  const seats = d.seats || [];
  const live = seats.filter((s) => s.status !== "revoked");
  const kindLabel = (s) => (s.kind === "team" ? "Partner team seat" : s.kind === "pilot" ? "Pilot seat" : "Recruiter");
  const row = (s) => `
  <div class="card mb" style="padding:12px 14px">
    <div class="flex-between"><strong>${esc(s.name || s.email)}</strong><span class="badge ${s.status === "active" ? "ok" : s.status === "invited" ? "warn" : ""}">${s.status === "active" ? "Active" : s.status === "invited" ? "Invited" : "Revoked"}</span></div>
    <p class="small muted" style="margin:4px 0">${esc(s.email)} · ${esc(kindLabel(s))} · ${esc(s.scope || "")}${s.invitedAt ? ` · invited ${esc(fmtDay(s.invitedAt))}` : ""}</p>
    ${s.status !== "revoked" ? `<div style="display:flex;gap:8px;flex-wrap:wrap">${s.status === "invited" ? `<button class="btn ghost small-btn" onclick="teamSeatAction('${s.seatId}','resend')">Resend the invite</button>` : ""}<button class="btn ghost small-btn" onclick="teamSeatAction('${s.seatId}','revoke')">Revoke this seat</button></div>` : ""}
  </div>`;
  const kindOptions = [];
  if (!d.isFunder) kindOptions.push(`<option value="team">Partner team seat (sees the org's numbers, never the deal terms)</option>`);
  for (const p of d.pilots || []) kindOptions.push(`<option value="pilot:${esc(p.id)}">Pilot seat: ${esc(p.name)}</option>`);
  if (!d.isFunder) for (const m of d.markets || []) kindOptions.push(`<option value="recruiter:${esc(m)}">Recruiter in ${esc(m)}</option>`);
  return `
  ${live.length ? uxCap203(live.map(row), 8) : `<div class="panel"><p style="margin:0">No seats yet. Invite your first person below; they get their own login for your scopes only.</p></div>`}
  ${seats.some((s) => s.status === "revoked") ? `<h3 style="margin:16px 0 6px">Revoked</h3>${uxCap203(seats.filter((s) => s.status === "revoked").map(row), 8)}` : ""}
  <div class="panel mt">
    <h3 style="margin-top:0">Invite someone</h3>
    <div class="form-2col">
      <div class="field"><label>Their name</label><input type="text" id="tm-name" placeholder="Full name"></div>
      <div class="field"><label>Their email</label><input type="email" id="tm-email" placeholder="name@company.com"></div>
    </div>
    <div class="field"><label>Seat</label><select id="tm-kind">${kindOptions.join("")}</select></div>
    <button class="btn" onclick="teamInviteSubmit()">Send the invite</button> <span id="tm-ok" class="saved"></span>
    <p class="small muted" style="margin:8px 0 0">You can only seat people inside your own markets and pilots, and a seat never carries your deal terms or team controls.</p>
  </div>`;
}
async function loadTeamTab() {
  const host = document.getElementById("pt-team");
  if (!host) return;
  try {
    const d = await api("GET", "/partner/team");
    host.innerHTML = teamSeatsHtml(d);
  } catch (e) {
    host.innerHTML = `<div class="panel"><p style="margin:0">${esc(e.message)}</p></div>`;
  }
}
async function teamInviteSubmit() {
  const ok = document.getElementById("tm-ok");
  const kindRaw = (document.getElementById("tm-kind") || {}).value || "team";
  const [kind, scope] = kindRaw.split(/:(.+)/).filter((x) => x !== "");
  const body = { kind, name: (document.getElementById("tm-name") || {}).value || "", email: (document.getElementById("tm-email") || {}).value || "" };
  if (kind === "pilot") body.pilotId = scope;
  if (kind === "recruiter") body.market = scope;
  try {
    const r = await api("POST", "/partner/team/invite", body);
    if (ok) ok.textContent = r.emailSent === false ? "Seat created, but the invite email did not go out. Resend it from the list above." : "Invite sent. They set their own password from the email.";
    loadTeamTab();
  } catch (e) {
    if (ok) ok.textContent = e.message;
  }
}
async function teamSeatAction(seatId, action) {
  if (action === "revoke" && !window.confirm("Revoke this seat? Their access ends on their next request. Everything they brought in stays credited.")) return;
  try {
    await api("POST", `/partner/team/${action}`, { seatId });
    loadTeamTab();
  } catch (e) {
    window.alert(e.message);
  }
}

function partnerFillsIn(what) {
  return `<div class="panel"><h3 style="margin-top:0">Your funnel fills in</h3><p class="muted">Nothing here yet. ${esc(what)} When the first one lands, it shows up on this page the same day.</p></div>`;
}

// Sig's one line on the partner Overview: real counts from the
// summary payload, or the fills-in voice when nothing has come
// through the partner's links yet. Never an invented number.
function partnerSigLine(d) {
  const t = d.totals;
  const cs = d.creators.stages;
  const bs = d.businesses.stages;
  if (t.creatorsAttributed === 0 && t.businessesAttributed === 0) return "Your funnel fills in here. Share your creator link and I will keep count from the first claim.";
  return `${cs.claimed} creator${cs.claimed === 1 ? "" : "s"} claimed, ${cs.complete} complete, ${bs.applied} business${bs.applied === 1 ? "" : "es"} in through your links. Ask me what to do next.`;
}

// Sig's presence on the partner Overview (Jeff, 2026-10-28): the
// same hero media stack as the Sig tab (poster + idle loop,
// stills under reduced motion), his line, and the door into the
// partner Sig surface.
function partnerSigCardHtml(d) {
  return `
  <div class="card mb pt-sig-card">
    <div class="pt-sig-media">${sigHeroMediaHtml()}</div>
    <div class="pt-sig-copy">
      <div class="flex-between"><strong>Maggie</strong><span class="badge info">Your guide</span></div>
      <p class="small" style="margin:6px 0 10px">${esc(partnerSigLine(d))}</p>
      <button class="btn small-btn" onclick="return go('dashboard','Sig')">Ask Maggie</button>
    </div>
  </div>`;
}

// Multi-scope home (Build -106): when one login carries more
// than the license scope, Home opens with the rollup: one
// headline line per scope, never a summed total, and the door
// into each scope. Pilot headlines fill in from each pilot's
// own overview (loadPartnerScopeHeads).
function partnerScopesCardHtml(d) {
  const scopes = d.scopes || [];
  if (scopes.length <= 1) return "";
  const e = d.earnings;
  const sym = e.currency === "GBP" ? "£" : "$";
  return `
  <div class="card mb">
    <div class="flex-between"><strong>Your scopes</strong><span class="badge info">${scopes.length} views, one login</span></div>
    <p class="small" style="margin:8px 0 4px"><strong>License view (this one):</strong> ${esc((d.partner.markets || []).join(", ") || "your markets")} · accrued ${sym}${fmtPrice(e.accruedTotal)} · ${d.totals.creatorsAttributed} creators and ${d.totals.businessesAttributed} businesses through your links.</p>
    ${scopes.filter((s) => s.kind === "pilot").map((s) => `
    <p class="small" style="margin:4px 0"><strong>${esc(s.partnerName || s.name)} (Impact Portal):</strong> <span data-pt-scope-head="${esc(s.pilotId)}">loading its headline…</span></p>
    <button class="btn small-btn ghost" onclick="return enterPilotScope('${esc(s.pilotId)}')">Open ${esc(s.name || "the pilot")}</button>`).join("")}
    <p class="small muted" style="margin:8px 0 0">Each scope keeps its own numbers. Nothing is ever added across scopes.</p>
  </div>`;
}

function enterPilotScope(pilotId) {
  state.pilotScopeId = pilotId;
  pilotState.me = null;
  state.sigThread = [];
  return go("dashboard", "Overview");
}

async function loadPartnerScopeHeads(d) {
  const pilots = (d.scopes || []).filter((s) => s.kind === "pilot");
  for (const s of pilots) {
    const host = document.querySelector(`[data-pt-scope-head="${s.pilotId}"]`);
    if (!host) continue;
    try {
      const data = await api("GET", "/pilot/overview?pilot=" + encodeURIComponent(s.pilotId));
      const f = data.fund || {};
      const c = data.counts || {};
      host.textContent = `$${fmtPrice((f.committedCents || 0) / 100)} fund · $${fmtPrice((f.spentCents || 0) / 100)} spent · ${c.businesses || 0} businesses chosen · ${c.visitsDone || 0} visits done · ${c.postsLive || 0} posts live`;
    } catch (err) {
      host.textContent = "its headline could not load; open the portal to see it";
    }
  }
}

function partnerHomeHtml(d) {
  const p = d.partner;
  const t = d.totals;
  const cs = d.creators.stages;
  const bs = d.businesses.stages;
  const e = d.earnings;
  const sym = e.currency === "GBP" ? "\u00a3" : "$";
  // Build -137 home: Sig hero, Quick highlights, Next steps,
  // stop. The multi-scope card stays under Next steps: it is
  // the only door into a pilot scope from this Home.
  const links = [
    { label: "Share your creator link", act: () => go("dashboard", "Links") },
    { label: "Invite a business", act: () => go("dashboard", "Links") },
    { label: "See your reports", act: () => go("dashboard", "Performance") },
  ];
  state.sigQueue = [];
  state.sigQueueLinks = links;
  state.sigQueueCount = 0;
  return `
  ${wsHead("Home", { chip: partnerSampleChip(d), sub: "Start here.", subKey: "pt-home" })}
  <div class="home-greet"><div class="hg-hi">Hi, ${esc(p.name || "")}</div><div class="hg-line serif-line">Your markets, your bench, your share: the creators and businesses who came in through your links, and the share they earn you.</div></div>
  ${sigHero137Html(partnerSigLine(d))}
  ${highlights137Html([
    { label: "Creators claimed", sub: "Through your links", value: String(cs.claimed) },
    { label: "Creators complete", sub: "Ready to book", value: String(cs.complete) },
    { label: "Businesses joined", sub: "Through your links", value: String(bs.applied) },
    { label: "Wallet", sub: `${sym}${fmtPrice(e.accruedMonthly)} accruing this month`, value: `${sym}${fmtPrice(e.accruedTotal)}`, tab: "Earnings" },
  ])}
  ${nextSteps137Html([], links)}
  ${partnerScopesCardHtml(d)}`;
}

function partnerMarketsHtml(d) {
  // Each tile carries its own next step (Build -47, audit P3),
  // computed from that market's funnel the same way Home's
  // next-step cards are: the emptiest stage is the step.
  const nextFor = (m) => {
    if ((m.creators.claimed || 0) === 0) return { text: `No creators have claimed in ${m.market} yet. Your claim link is the front door.`, btn: "Get links", tab: "Links" };
    if ((m.creators.complete || 0) < (m.creators.claimed || 0)) return { text: `${m.creators.claimed} claimed in ${m.market}, ${m.creators.complete} complete. Complete creators are the bench businesses book, so the link is worth another share here.`, btn: "Get links", tab: "Links" };
    if ((m.businesses.applied || 0) === 0) return { text: `The bench is forming in ${m.market} and no business has joined through you there yet. One business on a paid plan starts your share accruing.`, btn: "Get links", tab: "Links" };
    if ((m.offersLive || 0) === 0) return { text: `Creators and businesses are in for ${m.market}. The first live offer shows up under Performance.`, btn: "See performance", tab: "Performance" };
    return { text: `${m.market} is moving. Performance has the latest numbers.`, btn: "See performance", tab: "Performance" };
  };
  return `
  ${wsHead("Your markets", { sub: "Each market's funnel, end to end, and the next step in each.", subKey: "pt-markets" })}
  ${d.markets.map((m) => { const n = nextFor(m); return `
  <div class="card mb">
    <div class="flex-between"><strong>${esc(m.market)}</strong>${d.partner.demo ? `<span class="badge warn">Sample</span>` : ""}</div>
    <div class="stat-row" style="margin-top:10px">
      <div class="stat"><div class="num">${m.creators.claimed}</div><div class="lbl">Creators claimed</div></div>
      <div class="stat"><div class="num">${m.creators.complete}</div><div class="lbl">Complete</div></div>
      <div class="stat"><div class="num">${m.businesses.applied}</div><div class="lbl">Businesses</div></div>
      <div class="stat"><div class="num">${m.offersLive}</div><div class="lbl">Offers live</div></div>
      <div class="stat"><div class="num">${m.postsLive}</div><div class="lbl">Posts live</div></div>
    </div>
    <p class="small muted" style="margin:12px 0 8px"><strong>Next step:</strong> ${esc(n.text)}</p>
    <button class="btn small-btn" onclick="return go('dashboard','${n.tab}')">${n.btn}</button>
  </div>`; }).join("")}
  <div id="pt-race"></div>`;
}

// London district race (Build -106): renders only when the
// server says London is this partner's market (the endpoint
// 403s otherwise and the section simply never appears).
async function loadPartnerRace() {
  const host = document.getElementById("pt-race");
  if (!host) return;
  let r = null;
  try { r = await api("GET", "/partner/london-race"); } catch (e) { return; }
  if (!r || !r.districts) return;
  const stateLine = r.state === "not_started"
    ? "The race has not started yet: no clock is running and there is no winner. These are today's raw counts."
    : r.state === "running"
      ? `The race is running (backstop ${String(r.endsAt || "").slice(0, 10)}). First district to ${r.targets.creators} approved founding creators AND ${r.targets.businesses} founding businesses wins.`
      : r.state === "won"
        ? `${(r.districts.find((x) => x.id === r.winner) || {}).name || "A district"} has won the race, past both targets.`
        : `The 8-week backstop decided it on score (creators count 1, businesses count 2): ${(r.districts.find((x) => x.id === r.winner) || {}).name || "a district"} leads the final board.`;
  host.innerHTML = `
  <div class="card mb">
    <div class="flex-between"><strong>London district race</strong><span class="badge info">Your market only</span></div>
    <p class="small muted" style="margin:6px 0 10px">${esc(stateLine)}</p>
    ${r.districts.map((x) => `
    <p class="small" style="margin:0 0 6px"><strong>${esc(x.name)}:</strong> ${x.creators} of ${r.targets.creators} creators · ${x.businesses} of ${r.targets.businesses} businesses${r.state === "backstop_scored" || r.state === "running" ? ` · score ${x.score}` : ""}${x.qualifies ? ` · <span class="badge ok">Past both targets</span>` : ""}</p>`).join("")}
    <p class="small muted" style="margin:8px 0 0">Outside the race field: ${r.outsideField.creators} creators and ${r.outsideField.businesses} businesses elsewhere in London. They count toward London, just not toward a district.</p>
  </div>`;
}

