// Shared in-app notifications block (the no-ghosting surface):
// application outcomes, backfill offers, nudges, and decisions
// land here for both roles, newest first.
async function loadNotificationsInto(elId) {
  const el = document.getElementById(elId);
  if (!el) return;
  try {
    const data = await api("GET", "/notifications");
    if (!document.getElementById(elId)) return;
    if (!data.notifications.length) { el.innerHTML = ""; return; }
    state.badges = data.badges || state.badges;
    renderBottomNav();
    el.innerHTML = `<div class="panel"><h3 style="margin-top:0">Updates</h3>${data.notifications.slice(0, 8).map((n) => notifRow226(n)).join("")}</div>`;
    // Badges (Wave 3c fix): do NOT mark notes read here. This loader runs on
    // every dashboard render, so marking read on load wiped the tab badges
    // in the same paint they appeared (rendered QA 2026-10-24: business
    // badges never survived to a screenshot). Notes count as read once the
    // user navigates away from the dashboard showing the Updates panel;
    // go() flushes the pending read.
    if (data.unreadCount) state.notesReadPending = true;
  } catch (e) { /* notifications are an enhancement, never a blocker */ }
}

// The real Business Home: the Preview home's computations fed by
// this business's real bookings, offers, and applications (GET
// /me/business-home). Same layout, same definitions, real data.
// How post numbers reached us (UX redesign section 7): creator
// numbers are labeled as creator-reported unless the metrics sync
// supplied them, so a business never mistakes a hand-entered count
// for a platform pull.
function perfSourceLabel(source) {
  return source === "meta_sync" ? "Synced from Instagram" : "Creator-reported";
}

// The Home stat cell (Build -43, FIX A): the "Magpie ROAS Score"
// label belongs to Score v2 alone. When the payload carries v2
// (the live Home does), the cell shows the v2 current cohort with
// its state. Without v2 (the preview twin, older payloads) the
// legacy figure still renders, but under its honest name: a
// modeled estimate, with its basis lines (what is tracked, what
// is estimated from code uses at the average ticket, what is
// modeled media), and never a bare 0.00x.
function roasCellHtml(h, navButton) {
  const v2 = h.roasV2 || null;
  if (v2) {
    if (v2.state === "forming" || v2.score === null || v2.score === undefined) {
      return `<div class="stat-cell"><div class="stat-num grad-text" style="font-size:1.1rem">Forming</div><div class="stat-lbl">Magpie ROAS Score · $${fmtMoney(v2.countedBack)} counted back through your register so far. Your score starts when there is enough counted to mean something.</div>${navButton ? `<button class="btn small-btn" style="margin-top:6px" onclick="return go('dashboard','Visits &amp; Posts')">Go to Visits &amp; Posts</button>` : ""}</div>`;
    }
    // Build -45 (Halo): Home prints the same headline the
    // Receipt prints (the blend, when Halo has anything to
    // add), with the split in the label. One number, one
    // label, everywhere; the counted-only figure stays on
    // the Receipt's split, one tap away.
    const headNum = v2.headlineScore !== null && v2.headlineScore !== undefined && (v2.haloDollars || 0) > 0 ? v2.headlineScore : v2.score;
    return `<div class="stat-cell"><div class="stat-num grad-text">${Number(headNum).toFixed(1)}&times;</div><div class="stat-lbl">Magpie ROAS Score · ${esc(v2.stateLabel || "")}<br>$${fmtMoney(v2.countedBack)} counted back through your register${(v2.haloDollars || 0) > 0 ? ` · about $${fmtMoney(v2.haloDollars)} more Halo estimated` : ""}, on $${fmtMoney(v2.putIn)} all in. The full breakdown is on your Receipt.</div></div>`;
  }
  const r = h.roas || null;
  const score = h.roasScore;
  const hasTracked = !!(r && r.registerValue > 0);
  const hasEstimate = !!(r && r.estimatedRegisterValue > 0);
  const hasMedia = !!(r && r.mediaValue > 0);
  if ((score === null || score === undefined || Number(score) === 0) && !hasTracked && !hasEstimate && !hasMedia) {
    return `<div class="stat-cell"><div class="stat-num grad-text" style="font-size:1.1rem">No results yet</div><div class="stat-lbl">Modeled estimate — starts with your first register tally.</div>${navButton ? `<button class="btn small-btn" style="margin-top:6px" onclick="return go('dashboard','Visits &amp; Posts')">Go to Visits &amp; Posts</button>` : ""}</div>`;
  }
  const basis = [
    hasTracked ? `Register $${fmtMoney(r.registerValue)} tracked` : null,
    hasEstimate && r.registerEstimate ? `About $${fmtMoney(r.estimatedRegisterValue)} estimated from ${r.registerEstimate.uses} code uses at your $${fmtMoney(r.registerEstimate.avgTicket)} average ticket` : null,
    hasMedia ? `Media $${fmtMoney(r.mediaValue)} modeled` : null,
  ].filter(Boolean).join("<br>");
  return `<div class="stat-cell"><div class="stat-num grad-text">${score === null || score === undefined ? "n/a" : Number(score).toFixed(2) + "&times;"}</div><div class="stat-lbl">Modeled estimate (register tallies plus modeled media value)${basis ? `<br>${basis}` : ""}</div></div>`;
}

// ---------- business dashboard: a segmented report ----------
// Jeff (2026-10-25): the business dashboard was one endless
// scroll. It is a report now: a slim KPI band, then a segmented
// switch — Overview | Needs you (badged) | Campaigns | Results —
