// Feed taxonomy for the business home (Grin Feed pattern mapped
// to Magpie's real notification kinds + content records). Events
// only exist when a real record does; a chip with no records
// shows its own explained empty state.
const BIZ_FEED_KINDS = [["all", "All"], ["applications", "Applications"], ["invites", "Invites"], ["messages", "Messages"], ["posts", "Posts"], ["visits", "Visits"], ["licenses", "Licenses"]];
function bizFeedKindOf(noteKind) {
  const k = String(noteKind || "");
  if (/^application_|^backfill_|creator_declined|offer_declined/.test(k)) return "applications";
  if (k === "message_received") return "messages";
  if (/^performance_/.test(k)) return "posts";
  if (/license/.test(k)) return "licenses";
  if (/^offer_received$|^invite/.test(k)) return "invites";
  if (/visit|redeem|clock|deadline|booking|tally|window|overdue|complete|paid|payment|payout/.test(k)) return "visits";
  return "updates";
}
function bizFeedEvents(h, notes) {
  const evs = [];
  const actFor = (kind) => kind === "applications" ? { label: "Review", onclick: "return goApplicants()" }
    : kind === "messages" ? { label: "Open", onclick: "return go('dashboard','Messages')" }
    : kind === "posts" || kind === "licenses" ? { label: "Review", onclick: "return go('dashboard','Content')" }
    : { label: "Review", onclick: "return go('dashboard','Visits & Posts')" };
  for (const n of notes || []) {
    const kind = bizFeedKindOf(n.kind);
    const kindLabel = { applications: "Application", invites: "Invite", messages: "Message", posts: "Post", visits: "Visit", licenses: "License", updates: "Update" }[kind];
    evs.push({ kind, at: n.createdAt, title: esc(n.text), meta: kindLabel, icon: kind === "messages" ? "chat" : kind === "applications" ? "inbox" : "visits", act: actFor(kind) });
  }
  for (const r of h.contentLibrary || []) {
    evs.push({ kind: "posts", at: r.postedAt, title: `Post live: ${esc(r.title)}`, meta: `@${esc(r.creatorHandle)} · ${fmtNum(r.views || 0)} views · ${r.onTime ? "on time" : "late"}`, icon: "image", acc: true, act: actFor("posts") });
    if (r.license && r.license.type !== "native") {
      evs.push({ kind: "licenses", at: r.postedAt, title: `${r.license.type === "licensed" ? "Licensed post" : "Standard license"}: ${esc(r.title)}`, meta: r.license.daysLeft === null || r.license.daysLeft === undefined ? "90-day license window" : r.license.daysLeft < 0 ? `The reuse window ended ${r.license.windowEndsAt ? fmtDay(r.license.windowEndsAt) : ""}` : `${r.license.daysLeft} days left to repost and run ads${r.license.windowEndsAt ? ` · ends ${fmtDay(r.license.windowEndsAt)}` : ""}`, icon: "shield", acc: true, act: actFor("licenses") });
    }
  }
  evs.sort((a, b) => (Date.parse(b.at || "") || 0) - (Date.parse(a.at || "") || 0));
  return evs;
}
let bizFeedKind = "all";
function bizFeedSet(kind) {
  bizFeedKind = kind;
  const host = document.getElementById("biz-feed");
  if (host) host.innerHTML = bizFeedHtml(state.bizFeedEvents || []);
  return false;
}
function bizFeedHtml(events) {
  const chips = `<div class="feed-chips">${BIZ_FEED_KINDS.map(([k, label]) => `<button type="button" class="fchip ${bizFeedKind === k ? "on" : ""}" onclick="return bizFeedSet('${k}')">${label}</button>`).join("")}</div>`;
  const shown = bizFeedKind === "all" ? events : events.filter((e) => e.kind === bizFeedKind);
  if (!shown.length) {
    const label = (BIZ_FEED_KINDS.find(([k]) => k === bizFeedKind) || [])[1] || "Activity";
    return `${chips}<div class="feed-list"><div class="feed-empty"><div class="ec-t">Nothing here yet</div><div class="ec-s">${bizFeedKind === "all" ? "When a creator applies, visits, or posts, it shows up here." : `No ${label.toLowerCase()} events yet. They land here the moment they happen.`}</div></div></div>`;
  }
  return chips + feedListHtml(shown);
}

// Visit segments (spec §5.4 / §6.3): work organized by what
// the visit still needs, not by object type. Shared by the
// Visits screens and Sig's queue so the two never disagree.
function visitSegOf(b, role) {
  if (b.post) return "done";
  if (b.honorReportedAt || b.replacementRequestedAt) return "done";
  if (b.redeemedAt) return role === "business" ? "waiting" : "needs";
  if (b.status === "cancelled" || b.status === "expired") return "done";
  if (role === "business" && !b.visitDate && !b.redeemBy) return "needs";
  return "upcoming";
}

// ---------- Sig activation prompts (Jeff, 2026-10-28) ----------
// Sig as a proactive layer: deterministic queue items (class 5,
// "ideas") computed from the account's real record state and,
// for businesses, the market inventory in home.sigSignals. The
// full bank lives in files/signl-sig-activation-catalog-2026-10-28.md.
// Rules the builders below obey: a prompt renders only when its
// action can succeed now (a deep-linked search returns at least
// one real result; a named field is actually empty); every
// number is a live count or a stored fact; at most 2 idea
// prompts ride a queue at once (activation items for incomplete
// essentials are class 4 and sit above this cap); every idea is
// dismissible and a dismissal suppresses it for 14 days.
const SIG_IDEA_COOLDOWN_MS = 14 * 86400000;
function sigIdeaKey(userId, id) { return `signl_sig_idea:${userId}:${id}`; }
function sigIdeaDismissed(userId, id) {
  try {
    const t = Number(localStorage.getItem(sigIdeaKey(userId, id)) || 0);
    return !!t && (Date.now() - t) < SIG_IDEA_COOLDOWN_MS;
  } catch (e) { return false; }
}
function sigIdeaItem(userId, id, text, btn, act, short) {
  if (sigIdeaDismissed(userId, id)) return null;
  return { cls: 5, at: Date.now(), idea: true, text, btn, act, short, dismissKey: sigIdeaKey(userId, id) };
}
function capSigIdeas(items) {
  let n = 0;
  return items.filter((it) => {
    if (!it || !it.idea) return true;
    n += 1;
    return n <= 2;
  });
}
// Business idea copy banks: the campus lead-in per stored
// category, and the one category play per category (its button
// is the offer composer, which always succeeds, so no inventory
// gate applies to it).
const SIG_CAMPUS_LEADINS = {
  "Restaurant": "Students are your next regulars.",
  "Bar": "Campus nights are built, not found.",
  "Coffee & Bakery": "Study hours are your hours.",
  "Salon & Barbershop": "Campus marketing is key for a salon like yours.",
  "Fitness Studio": "A new term is a new membership season.",
  "Retail": "Students shop where students post.",
  "Attraction": "Campus groups look for things to do.",
  "Local Services": "Students need local everything, fast.",
  "Other": "Students are a market of their own.",
};
const SIG_CATEGORY_PLAYS = {
  "Restaurant": "Weekend tables are the prize. Post an offer with a Friday or Saturday window and let creators compete for it.",
  "Bar": "Slow nights are the opportunity. A creator visit on your quiet night turns it into content night.",
  "Coffee & Bakery": "Morning regulars are made, not born. One creator's study-session post puts your shop on the map.",
  "Salon & Barbershop": "A transformation post is your best ad. Book a creator before prom and homecoming weekends, when chairs fill anyway.",
  "Fitness Studio": "First-week energy sells memberships. A creator's first class post reaches people a flyer never will.",
  "Retail": "New arrivals deserve an audience. A creator unboxing or try-on turns stock into a story.",
  "Attraction": "Groups book what groups see. A creator visit makes your place the plan, not an option.",
  "Local Services": "Trust is the product. A creator showing the job done well is worth more than any review.",
  "Other": "Your first offer teaches the roster what you love. Post it, and watch who applies.",
};
const SIG_MUSIC_CATEGORIES = ["Bar", "Restaurant", "Coffee & Bakery", "Attraction", "Local Services", "Retail", "Fitness Studio"];

// Campus season windows (U4): generic US academic-calendar
// windows, deliberately NOT any school's real dates. At most
// one window matches at a time; the first match wins. The
// prompt copy names seasons, never schools.
const CAMPUS_SEASONS = [
  { id: "move_in", from: [8, 1], to: [9, 10], short: "Students are moving back in", text: "Students are moving back in around local campuses. Student creators book fast in the first weeks of term." },
  { id: "homecoming", from: [9, 25], to: [11, 10], short: "Homecoming season is on", text: "Homecoming season is on at local universities. It is one of the busiest stretches of the year for the businesses around a campus." },
  { id: "spring_start", from: [1, 5], to: [1, 25], short: "A new term is starting", text: "A new term is starting at local universities. Student creators are settling their schedules now." },
  { id: "graduation", from: [4, 20], to: [5, 20], short: "Graduation season is coming", text: "Graduation season is coming at local universities. Families in town means full tables for the businesses near campus." },
];
function campusSeasonNow(when) {
  const d = when || new Date();
  const md = (m, day) => m * 100 + day;
  const cur = md(d.getMonth() + 1, d.getDate());
  for (const s of CAMPUS_SEASONS) {
    if (cur >= md(s.from[0], s.from[1]) && cur <= md(s.to[0], s.to[1])) return s;
  }
  return null;
}

async function loadBusinessHome() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  const u = state.user;
  el.innerHTML = `${wsHead("Home", { sub: "Start here. Maggie shows you what needs you, in order.", subKey: "biz-home" })}${skelHtml("Loading your home...", 3)}`;
  try {
    // Perf (2026-10-28): notifications, offers and bookings do not
    // depend on the business-home payload, so all four requests now
    // fire together instead of as a sequential chain. Each keeps
    // its own degrade-to-empty behavior.
    const notesPromise = api("GET", "/notifications").catch(() => null);
    // Build -95: Regulars + licences ending soon ride the same
    // parallel fetch block for Sig's queue below.
    const regularsPromise = api("GET", "/me/regulars").catch(() => null);
    const licencesExpiringPromise = api("GET", "/me/licences-expiring").catch(() => null);
    // Build -96: last month's export, for the receipt-ready
    // prompt below (renders only when that month has activity).
    const prevMonthKey = (() => { const n = new Date(); const p = new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth() - 1, 1)); return `${p.getUTCFullYear()}-${String(p.getUTCMonth() + 1).padStart(2, "0")}`; })();
    const receiptPrevPromise = api("GET", `/me/receipt-export?month=${prevMonthKey}`).catch(() => null);
    const offersPromise = api("GET", "/offers").catch(() => null);
    const bookingsPromise = api("GET", "/bookings").catch(() => null);
    const readoutPromise = api("GET", "/me/performance-readout").catch(() => null);
    const d = await api("GET", "/me/business-home");
    const h = d.home;
    if (!document.getElementById("tab-body")) return;
    let notes = [];
    const nd = await notesPromise;
    if (nd) {
      notes = nd.notifications || [];
      if (nd.unreadCount) state.notesReadPending = true;
      if (nd.badges) state.badges = nd.badges;
    } /* else the feed degrades to content events only */
    let offers = [];
    let bookings = [];
    const od = await offersPromise; if (od) offers = od.offers || []; /* else queue degrades */
    const bd = await bookingsPromise; if (bd) bookings = bd.bookings || []; /* else queue degrades */
    // Perf (2026-10-28): the per-offer application stacks used to
    // load one sequential request at a time (up to 12 round trips);
    // they are independent, so they now load in parallel and are
    // flattened in the original offer order.
    const waiting = [];
    const stacks = await Promise.all(
      offers.filter((x) => (x.applicationCount || 0) > 0).slice(0, 12).map(async (o) => {
        try {
          const ad = await api("GET", `/offers/${o.id}/applications`);
          return (ad.applications || []).filter((a) => a.status === "applied").map((a) => ({ offer: ad.offer || o, app: a }));
        } catch (e) { return []; /* one offer's stack never blocks the home */ }
      })
    );
    for (const stack of stacks) waiting.push(...stack);
    state.waitCounts = state.waitCounts || {};
    state.waitCounts.bizApps = waiting.length;
    state.myOffers = offers;
    state.nudgeBookings = state.nudgeBookings || {};
    for (const bk of bookings) state.nudgeBookings[bk.id] = bk;

    // Sig's queue (spec §4.2/§4.3): deadlines first, then
    // people waiting, then new results, then setup gaps.
    // Within a class, oldest waiting first.
    const now = Date.now();
    const items = [];
    const add = (cls, at, text, btn, act, short) => items.push({ cls, at: at || now, text, btn, act, short });
    const due = waiting.filter((w) => addBizDays(Date.parse(w.app.createdAt) || now, 2) - now < 86400000)
      .sort((a, b) => (Date.parse(a.app.createdAt) || 0) - (Date.parse(b.app.createdAt) || 0));
    if (due.length) {
      const first = due[0];
      add(1, Date.parse(first.app.createdAt) || now, due.length === 1 ? `A decision is due today: ${first.app.creator.name} applied to "${first.offer.title}".` : `${due.length} decisions are due today. The oldest is ${first.app.creator.name} for "${first.offer.title}".`, "Decide", () => { if (!reqState) reqState = reqFreshState(); reqState.open[first.app.id] = true; goApplicants(first.offer.id); }, due.length === 1 ? `Decision due: ${first.app.creator.name}` : `${due.length} decisions due today`);
    }
    const startOfDay = new Date(); startOfDay.setHours(0, 0, 0, 0);
    const sameDay = (iso) => { const t = Date.parse(iso || ""); return !Number.isNaN(t) && t >= startOfDay.getTime() && t < startOfDay.getTime() + 86400000; };
    const visitToday = bookings.filter((b) => !b.redeemedAt && !b.post && b.status !== "cancelled" && b.status !== "expired" && (sameDay(b.visitDate) || sameDay(b.redeemBy)));
    if (visitToday.length) {
      add(1, now, visitToday.length === 1 ? `${visitToday[0].creatorName} is visiting today.` : `${visitToday.length} visits are happening today.`, "Open counter", () => go("dashboard", "Counter"), visitToday.length === 1 ? `Visit today: ${visitToday[0].creatorName}` : `${visitToday.length} visits today`);
    }
    const postDue = bookings.filter((b) => b.redeemedAt && !b.post && b.postDeadline && (Date.parse(b.postDeadline) - now) <= 48 * 3600000 && b.status !== "cancelled")
      .sort((a, b) => (Date.parse(a.postDeadline) || 0) - (Date.parse(b.postDeadline) || 0));
    if (postDue.length) {
      const b = postDue[0];
      const overdue = Date.parse(b.postDeadline) < now;
      add(1, Date.parse(b.postDeadline) || now, `${b.creatorName} visited ${fmtDay(b.redeemedAt)} and the post is ${overdue ? "overdue" : "due " + dueDayWords(b.postDeadline)}.`, "Send a nudge", (btn) => sendNudge(b.id, btn), overdue ? `Post late: ${b.creatorName}` : `Post due ${dueDayWords(b.postDeadline)}: ${b.creatorName}`);
    }
    if (waiting.length) {
      const oldest = waiting.slice().sort((a, b) => (Date.parse(a.app.createdAt) || 0) - (Date.parse(b.app.createdAt) || 0))[0];
      add(2, Date.parse(oldest.app.createdAt) || now, `${waiting.length} creator${waiting.length === 1 ? " is" : "s are"} waiting on your answer.`, "Review", () => goApplicants(), `${waiting.length} waiting on your answer`);
    }
    const needsTime = bookings.filter((b) => visitSegOf(b, "business") === "needs");
    if (needsTime.length) add(2, now, `${needsTime.length} visit${needsTime.length === 1 ? " needs" : "s need"} a time.`, "Set the visit", () => { state.visitsSeg = "needs"; go("dashboard", "Visits & Posts"); }, `${needsTime.length} visit${needsTime.length === 1 ? "" : "s"} without a time`);
    const msgCount = (state.badges && state.badges.messages) || 0;
    if (msgCount) add(2, now, `${msgCount} message${msgCount === 1 ? " is" : "s are"} waiting.`, "Read", () => go("dashboard", "Messages"), `${msgCount} unread message${msgCount === 1 ? "" : "s"}`);
    const lib = h.contentLibrary || [];
    const freshPost = lib.filter((r) => r.postedAt && now - Date.parse(r.postedAt) < 14 * 86400000).sort((a, b) => (Date.parse(b.postedAt) || 0) - (Date.parse(a.postedAt) || 0))[0];
    if (freshPost) add(3, Date.parse(freshPost.postedAt) || now, `${freshPost.creatorName || "A creator"}'s post is live: "${freshPost.title}".`, "See the post", () => go("dashboard", "Content"), `Post live: "${freshPost.title}"`);
    const licRow = lib.find((r) => r.license && r.license.type === "native" && bookings.some((b) => b.post && b.id === r.bookingId && Number(b.creatorLicensingFee) > 0));
    if (licRow) {
      const bk = bookings.find((b) => b.id === licRow.bookingId);
      add(3, Date.parse(licRow.postedAt) || now, `You can license ${licRow.creatorName}'s post for $${fmtPrice(bk.creatorLicensingFee)}.`, "License it", () => go("dashboard", "Content"), `License ${licRow.creatorName}'s post · $${fmtPrice(bk.creatorLicensingFee)}`);
    }
    // Build -95 proactive prompts, from real records only: a
    // licence inside its 14-day window, and a Regular who has
    // not been rebooked since their visit. Nothing true to say,
    // nothing renders.
    const expD = await licencesExpiringPromise;
    const expRows = (expD && expD.licences) || [];
    if (expRows.length) {
      const first = expRows[0];
      add(2, now, expRows.length === 1
        ? `Your licence on ${first.creatorName}'s post ends ${fmtDay(first.windowEndsAt)}${first.ended ? " (already ended)" : ""}. Ask to renew and the creator decides.`
        : `${expRows.length} licences are ending soon. The soonest is ${first.creatorName}'s post, ending ${fmtDay(first.windowEndsAt)}. Ask to renew and the creator decides.`,
        "Ask to renew", () => go("dashboard", "Content"),
        expRows.length === 1 ? `Licence ends ${fmtDay(first.windowEndsAt)}: ${first.creatorName}` : `${expRows.length} licences ending soon`);
    }
    const regD = await regularsPromise;
    const unbooked = ((regD && regD.regulars) || []).filter((r) => !r.rebookedSince);
    if (unbooked.length) {
      const first = unbooked[0];
      add(3, Date.parse(first.lastVisitAt) || now, unbooked.length === 1
        ? `${first.creatorName} visited and posted, and has not been booked again since. Book again copies the last deal into a draft.`
        : `${unbooked.length} of your Regulars have not been booked again since their visits. Book again copies the last deal into a draft.`,
        "Book again", () => go("dashboard", "Regulars"),
        unbooked.length === 1 ? `Book again: ${first.creatorName}` : `${unbooked.length} Regulars to book again`);
    }
    // Build -96 proactive prompts, real records only: last
    // month's receipt is ready to forward when that month holds
    // real activity; standing availability unset is a setup gap
    // beside the About one below.
    const rxD = await receiptPrevPromise;
    const rxExp = rxD && rxD.export;
    if (rxExp && rxExp.hasActivity) {
      add(3, now, `Your ${rxExp.monthLabel} receipt is ready to forward: counted, recorded, and intent figures in three separate sections, with your founding credit and licence end dates.`, "Forward it", () => go("dashboard", "Analytics"), `${rxExp.monthLabel} receipt ready`);
    }
    // Build -97 proactive prompts, real records only: a draft
    // this (active) business started and never sent, and plan
    // visits still unused partway through the month. This home
    // only runs for active businesses, so a draft here is by
    // definition unfinished. Nothing true, nothing renders.
    const unfinishedDraft = offers.filter((o) => o.status === "draft").sort((a, b) => String(a.createdAt || "").localeCompare(String(b.createdAt || "")))[0];
    if (unfinishedDraft) {
      add(2, Date.parse(unfinishedDraft.createdAt) || now, `You started a draft campaign, "${unfinishedDraft.title}", and have not finished it yet. It sends nothing until you publish it.`, "Finish the draft", () => { state.offersSeg = "drafts"; go("dashboard", "My Offers"); }, `Draft waiting: "${unfinishedDraft.title}"`);
    }
    const pace97 = (() => { const n97 = new Date(); const dim97 = new Date(n97.getFullYear(), n97.getMonth() + 1, 0).getDate(); return n97.getDate() >= 3 && (h.visitsAllowance || 0) > 0 && (h.visitsRemaining || 0) > 0 && (h.visitsUsed || 0) < (h.visitsAllowance || 0) * (n97.getDate() / dim97); })();
    if (pace97) {
      add(4, now, `Partway through the month, ${h.visitsRemaining} of your ${h.visitsAllowance} plan visits are still unused. A new campaign is how they turn into visits.`, "Start a campaign", () => go("dashboard", "Campaign Setup"), `${h.visitsRemaining} visits unused this month`);
    }
    // Capture-gap diagnostic (Build -39): creator-reported
    // reach ran far ahead of counted register customers. The
    // line names the check, never a culprit, with real counts.
    const gap39 = h.captureGap || {};
    if (gap39.state === "thin") {
      add(3, now, `Counting looks thin: posts from your visits were seen about ${fmtNum(gap39.reach)} times (creators reported), but only ${gap39.countedFirsts} customers were counted at the register. Here is what we can check: the code in the captions, code cards at the counter, an audience offer on the visit.`, "See the check", () => { receiptTab = "counts"; const t = document.getElementById("biz-receipt"); if (t) { loadReceipt().then(() => { const el = document.getElementById("biz-receipt"); if (el) el.scrollIntoView({ behavior: "smooth", block: "start" }); }); } }, "Counting looks thin");
    }
    const bz = u.business || {};
    if (!bz.about) add(4, now, "Your business page is missing its About.", "Add about", () => go("dashboard", "Profile"), "About missing on your page");
    if (!bz.standingAvailability) add(4, now, "Set your standing hours once, and creators see them on your offers while new offers pre-fill their timing from them.", "Set hours", () => go("dashboard", "Profile"), "Standing hours not set");
    // Which till (Build -101): the one-time prompt fires only
    // when the field is empty on a business that is otherwise
    // set up (its page carries an About), so a brand-new
    // business is not nagged about a till before its own page
    // exists. The checklist item asks the same question in
    // place; this is the Sig-side nudge, once, from real state.
    if (!bz.posProvider && bz.about) add(5, now, "Tell us which till you run: Square, Clover, Toast, Lightspeed, or another system. It only changes how visits get counted later; codes count at every till today.", "Answer on Home", () => go("dashboard", "Home"), "What you use at the register");
    if (d.staffPinSet === false) add(4, now, "Set your staff PIN so your team can redeem visits: the creator shows their visit code at your counter, your team enters it with this PIN, and that is what counts the visit.", "Set PIN", () => go("dashboard", "Settings"), "Staff PIN not set");
    // Build -99 proactive prompt, real records only: the
    // setup checklist's register item is undone and Square is
    // switched on for this account. Connected or paused
    // registers, and accounts Square is not switched on for,
    // hear nothing here.
    const sc99 = d.setupChecklist;
    if (sc99 && sc99.register && sc99.register.configured && sc99.register.state === "not_connected") add(4, now, "Your register isn't connected yet. Connect it and code visits count themselves.", "Connect Square", () => { const c = document.getElementById("setup-checklist"); if (c) c.scrollIntoView({ behavior: "smooth", block: "start" }); }, "Register not connected");
    if ((h.visitsCarried || 0) > 0 && h.carriedExpiresAt) add(4, now, `${h.visitsCarried} rolled visit${h.visitsCarried === 1 ? "" : "s"} expire ${dueDayWords(h.carriedExpiresAt)}.`, "See plan", () => go("dashboard", "Plan"), `Rollover expires ${dueDayWords(h.carriedExpiresAt)}`);
    else if ((h.visitsRemaining || 0) <= 1) add(4, now, `You have ${h.visitsRemaining || 0} visit${(h.visitsRemaining || 0) === 1 ? "" : "s"} left this month.`, "See plan", () => go("dashboard", "Plan"), `${h.visitsRemaining || 0} visit${(h.visitsRemaining || 0) === 1 ? "" : "s"} left this month`);
    // Campus moments (university layers U4, Jeff, 2026-10-28):
    // a business that flagged itself open to student creators
    // (U3) gets one seasonal prompt in its Sig queue while a
    // generic campus window is open. Seasons only: the copy
    // never names a school and never states a real campus date.
    // Dismissible per season (localStorage key carries the
    // season id, so next season's prompt returns on its own).
    const season = campusSeasonNow();
    if (season && bz.studentOpen === true) {
      const dismissKey = `signl_campus_prompt:${u.id}:${season.id}`;
      let dismissed = false;
      try { dismissed = !!localStorage.getItem(dismissKey); } catch (e) { /* storage unavailable: show the prompt */ }
      if (!dismissed) items.push({ cls: 4, at: now, text: season.text, short: season.short, btn: "Find creators", act: () => go("dashboard", "Discover"), dismissKey });
    }
    // Sig activation (Jeff, 2026-10-28): first-move prompts
    // (class 4) for a set-up business with nothing posted yet,
    // then the idea bank (class 5) driven by home.sigSignals.
    // Every signal play cites the count of the exact cohort its
    // button's Discover search returns and renders only when
    // that count is at least 1; the category play's button is
    // the offer composer, which always succeeds.
    const sig = h.sigSignals || {};
    const mktName = marketTalkNameClient(u.market);
    const plural = (n) => (n === 1 ? "" : "s");
    const pushIdea = (id, text, btn, act, short) => { const it = sigIdeaItem(u.id, id, text, btn, act, short); if (it) items.push(it); };
    if (offers.length === 0 && bz.about && (sig.roster || 0) > 0) {
      add(4, now, d.marketLive
        ? `${sig.roster} creator${plural(sig.roster)} ${sig.roster === 1 ? "is" : "are"} on the roster in ${mktName}. Post your first offer and they can apply.`
        : `${sig.roster} creator${plural(sig.roster)} ${sig.roster === 1 ? "is" : "are"} on the founding roster in ${mktName}. Draft your first offer now; publishing switches on at launch.`,
        "Post offer", () => go("dashboard", "Campaign Setup"), "Post your first offer");
    }
    if (offers.length > 0 && !offers.some((o) => o.lane === "direct") && bookings.length === 0) {
      add(4, now, "Invite a creator directly at their listed rate. An invite goes to one creator, by name.", "Find creators", () => go("dashboard", "Discover"), "Invite a creator directly");
    }
    if ((sig.campus || 0) > 0 && sig.campusTop) {
      const lead = SIG_CAMPUS_LEADINS[bz.category] || SIG_CAMPUS_LEADINS.Other;
      pushIdea("biz_campus", `${lead} ${sig.campusTop.name} has ${sig.campusTop.count} student creator${plural(sig.campusTop.count)} on the roster in ${mktName}.`, "Find students", () => { state.discoverUniversity = sig.campusTop.name; go("dashboard", "Discover"); }, "Student creators on the roster");
    }
    if ((sig.musiciansPerform || 0) > 0 && SIG_MUSIC_CATEGORIES.includes(bz.category)) {
      pushIdea("biz_music_live", `A live set draws a crowd. ${sig.musiciansPerform} creator${plural(sig.musiciansPerform)} in ${mktName} ${sig.musiciansPerform === 1 ? "is" : "are"} open to performing live.`, "Find musicians", () => { state.discoverMusician = "perform"; go("dashboard", "Discover"); }, "Musicians open to live sets");
    }
    if ((sig.musiciansCreate || 0) > 0) {
      pushIdea("biz_music_create", `A sound of your own: ${sig.musiciansCreate} creator${plural(sig.musiciansCreate)} in ${mktName} make${sig.musiciansCreate === 1 ? "s" : ""} music for businesses.`, "Find musicians", () => { state.discoverMusician = "create"; go("dashboard", "Discover"); }, "Creators who make music");
    }
    if ((sig.spanish || 0) > 0) {
      pushIdea("biz_spanish", `Spanish-speaking customers are in ${mktName}: ${sig.spanish} creator${plural(sig.spanish)} here make${sig.spanish === 1 ? "s" : ""} content in Spanish.`, "Find creators", () => { state.discoverSpanish = true; go("dashboard", "Discover"); }, "Spanish-speaking creators here");
    }
    if ((sig.fresh || 0) > 0) {
      // Fresh-eyes A-14 + Jeff's no-small-counts rule: the number
      // only rides along at 10 or more; below that the fact stands
      // without a count (the named form at exactly one).
      const freshLine = sig.fresh >= 10
        ? `New on the roster: ${sig.fresh} creators finished profiles in ${mktName} in the last two weeks.`
        : sig.fresh === 1
          ? `New on the roster: a creator finished their profile in ${mktName} in the last two weeks.`
          : `New on the roster: new creators finished profiles in ${mktName} in the last two weeks.`;
      pushIdea("biz_fresh", freshLine, "Find creators", () => go("dashboard", "Discover"), "New creators on the roster");
    }
    pushIdea("biz_category_play", SIG_CATEGORY_PLAYS[bz.category] || SIG_CATEGORY_PLAYS.Other, "Post offer", () => go("dashboard", "Campaign Setup"), "An idea for your business");
    // R2 closed-loop repeat (Jeff, 2026-10-28): when the
    // readout's deterministic best performer exists, propose
    // running it again as a queue idea (14-day suppression and
    // the 2-idea cap apply via sigIdeaItem/capSigIdeas). The
    // button opens Sig's proposal; the clone still passes the
    // standard confirmation summary before anything posts.
    const rod = await readoutPromise;
    if (rod && !rod.empty && rod.recommendation && rod.recommendation.type === "repeat" && rod.recommendation.bookingId) {
      const recR = rod.recommendation;
      pushIdea("biz_repeat_" + recR.bookingId, `Repeat what worked: "${recR.title}"${recR.creatorName ? ` with ${recR.creatorName}` : ""}. ${recR.reason || ""}`, "Repeat it", () => { go("dashboard", "Sig"); setTimeout(() => sigRepeatProposal(rod), 400); }, `Repeat: "${recR.title}"`);
    }
    // Build -91: wishlist and roster-digest alerts ride the
    // queue as people-class items, off the same notes the feed
    // reads. Save / Invite actions follow the Sig linking rule:
    // they land on the real Discover and composer surfaces.
    for (const n of sigAlertNotes(notes)) {
      const a = sigAlertAction(n);
      add(2, Date.parse(n.createdAt) || now, n.text, a.btn, a.act, a.short);
    }
    state.waitCounts.bizVisits = visitToday.length + postDue.length + needsTime.length;
    items.sort((a, b) => a.cls - b.cls || a.at - b.at);
    const queue = capSigIdeas(items).slice(0, 7);

    // Build -99: the launch checklist, the start-here cards,
    // and the proof kit are ONE surface now: the setup
    // checklist in d.setupChecklist, rendered below. Its page
    // and campaign items carry the old launch steps' state.
    const fresh = !(bz.businessName && bz.category && bz.about) || !offers.length;
    const greetLine = fresh ? "Let's get your first campaign live. Maggie walks you through it, three steps." : (queue.length ? queue[0].text : "You're all caught up.");
    const greetDup = !fresh && queue.length > 0;
    const hasNumbers = (h.postsLive || 0) > 0 || (h.localReachDelivered || 0) > 0 || (h.visitsUsed || 0) > 0;
    const snapCells = hasNumbers ? [
      { num: fmtNum(h.localReachDelivered || 0), label: "Local audience" },
      { num: fmtNum(h.postsLive || 0), label: "Posts live" },
      { num: `${h.visitsUsed || 0} of ${h.visitsAllowance || 0}`, label: "Visits this month" },
      // Build -43 (FIX A): when Score v2 has a figure, it rides
      // the Home snapshot under its own name and state. The
      // legacy estimate never appears here; it lives, labeled as
      // a modeled estimate, on the Performance card below.
      ...(h.roasV2 && h.roasV2.score !== null && h.roasV2.score !== undefined ? [{ num: `${Number(h.roasV2.headlineScore !== null && h.roasV2.headlineScore !== undefined && (h.roasV2.haloDollars || 0) > 0 ? h.roasV2.headlineScore : h.roasV2.score).toFixed(1)}&times;`, label: `Magpie ROAS Score · ${h.roasV2.stateLabel || ""}${(h.roasV2.haloDollars || 0) > 0 ? ` · $${fmtMoney(h.roasV2.countedBack)} counted, about $${fmtMoney(h.roasV2.haloDollars)} Halo est.` : ""}` }] : []),
    ] : null;
    const caughtLinks = [
      { label: "Find creators", act: () => go("dashboard", "Discover") },
      { label: "Post an offer", act: () => go("dashboard", "Campaign Setup") },
    ];
    state.bizFeedEvents = bizFeedEvents(h, notes);
    bizFeedKind = "all";
    // V4.1: the Sig tab renders this same queue and badges its
    // count — one queue, two doors (see renderSigTab).
    state.sigQueue = queue;
    state.sigQueueLinks = caughtLinks;
    state.sigQueueCount = queue.length;
    // Build -119: ONE Next list. The setup-gap queue items
    // that duplicate the setup checklist (About, standing
    // hours, staff PIN, register) leave the queue whenever the
    // checklist card itself is on the page — the checklist
    // keeps its editors (Square connect, till chips, test
    // redemption), the Next list keeps every decision. The
    // hero is the most urgent item; with nothing waiting, the
    // hero is the design's: pick creators first, plumbing
    // later (the checklist sits under Money, not in front of
    // the roster).
    const clOn = !!(d.setupChecklist && !d.setupChecklist.allDone);
    const setupGap = (t) => clOn && (t.indexOf("Your business page is missing its About") === 0 || t.indexOf("Set your standing hours once") === 0 || t.indexOf("Set your staff PIN so your team can redeem") === 0 || t.indexOf("Your register isn't connected yet") === 0 || t.indexOf("Tell us which till you run") === 0);
    const nxQueueAll = queue.filter((it) => !setupGap(it.text || ""));
    let nxQueue = nxQueueAll;
    if (nxQueueAll.length) {
      const hi = nxQueueAll.findIndex((it) => (it.cls || 9) <= 2);
      if (hi > 0) nxQueue = [nxQueueAll[hi]].concat(nxQueueAll.slice(0, hi), nxQueueAll.slice(hi + 1));
    } else {
      nxQueue = [{ cls: 1, at: Date.now(), text: "Pick your first creators: see who is local, and what they charge.", btn: "Find creators", act: () => go("dashboard", "Discover"), short: "Pick your first creators" }];
    }
    // Build -137 home: Sig hero, Quick highlights (the
    // visits headline is COUNTED visits only), Next steps,
    // stop. The setup checklist stays under Next steps while
    // it is unfinished: its editors live nowhere else.
    const countedVisits = bookings.filter((b) => b.redeemedAt).length;
    const plan137 = d.plan || {};
    const credit137 = typeof plan137.foundingCredit === "number" ? plan137.foundingCredit : 100;
    const briefBiz = nxQueue.length ? nxQueue[0].text : "You're all caught up.";
    const nq3 = nxQueue.slice(0, 3);
    el.innerHTML = `
    <div data-dash>
    ${wsHead("Home", { sub: "Start here.", subKey: "biz-home" })}
    <div class="home-greet"><div class="hg-hi">Hi, ${esc(bz.businessName || u.name || "")}</div><div class="hg-line serif-line">${esc(greetLine)}</div></div>
    ${sqNoticeHtml()}
    ${sigHero137Html(briefBiz)}
    ${promptSlotHtml()}
    ${bizGuideStartersHtml()}
    ${highlights137Html([
      { label: "Creators waiting", sub: "Waiting on your answer", value: String(waiting.length) },
      { label: "Visits counted", sub: "Counted at your counter", value: String(countedVisits) },
      { label: "Posts live", sub: "Posts from your visits", value: String(h.postsLive || 0) },
      { label: "Wallet", sub: `$${fmtPrice(credit137)} founding credit left`, value: plan137.name || bz.planName || "Plan", tab: "Plan" },
    ])}
    ${nextSteps137Html(nq3, caughtLinks)}
    ${d.setupChecklist && !d.setupChecklist.allDone ? setupChecklistHtml(d.setupChecklist) : ""}
    </div>`;
    wireSigQueue(el, nq3, caughtLinks);
    loadSigTopNudges();
    loadPromptSlot();
    renderBottomNav();
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}
// ---------- Performance clarity (Jeff, 2026-10-28) ----------
// One readout, two doors: Sig speaks these exact numbers in chat
// (B3), and this card renders them on Home. The server computes
// (GET /me/performance-readout); nothing here estimates. With no
// completed data the card is the honest empty line plus the next
// action, never a zero grid.
function perfSeriesText(series) {
  if (!series) return "";
  const marks = [["Day 7", series.day7], ["Day 14", series.day14], ["Day 30", series.day30]].filter(([, v]) => v !== null && v !== undefined);
  return marks.length ? marks.map(([k, v]) => `${k} ${fmtNum(v)} views`).join(" · ") : "";
}
function performanceCardHtml(ro) {
  if (!ro) return "";
  if (ro.empty) {
    return `<div class="wcard"><h3>Performance</h3><p class="wc-sub" style="margin:4px 0 10px">Your funnel fills in once your campaigns are live. When a visit is redeemed and a post lands, your visits, posts, day 7 / 14 / 30 numbers, redemptions, and register value show up here, with one clear next move.</p><button type="button" class="btn small-btn" onclick="return go('dashboard','Campaign Setup')">Post an offer</button></div>`;
  }
  const o = ro.overall || {};
  const cells = [
    { num: `${o.visitsRedeemed || 0} of ${o.visitsBooked || 0}`, label: "Visits redeemed" },
    { num: fmtNum(o.postsLive || 0), label: "Posts live" },
  ];
  if (o.redemptions && o.redemptions.count > 0) cells.push({ num: `${fmtNum(o.redemptions.count)} · $${fmtMoney(o.redemptions.basketTotal || 0)}`, label: "Redemptions rung up" });
  if (o.registerValue) cells.push({ num: `$${fmtMoney(o.registerValue)}`, label: "Register value" });
  else if (o.estimatedRegisterValue) cells.push({ num: `$${fmtMoney(o.estimatedRegisterValue)}`, label: "Estimated register value" });
  // Never a bare 0 (Build -47, audit B1): a zero modeled estimate
  // is not a result; the cell appears once the estimate is real,
  // matching the Receipt's Forming doctrine.
  if (o.roasScore !== null && o.roasScore !== undefined && Number(o.roasScore) > 0) cells.push({ num: `${o.roasScore}`, label: "Modeled estimate" });
  const series = perfSeriesText(o.series);
  const rows = (ro.offers || []).filter((r) => (r.visitsBooked || 0) > 0 || (r.postsLive || 0) > 0).slice(0, 5).map((r) => {
    const s = perfSeriesText(r.series);
    return `<div class="lib-row"><div class="lib-main"><div class="lib-title">${esc(r.title)}</div><div class="lib-meta">${r.visitsBooked || 0} booked · ${r.visitsRedeemed || 0} redeemed · ${r.postsLive || 0} posts live${r.views ? ` · ${fmtNum(r.views)} views` : ""}${(r.redemptions && r.redemptions.count) ? ` · ${r.redemptions.count} redemptions ($${fmtMoney(r.redemptions.basketTotal || 0)})` : ""}${s ? `<br>${esc(s)}` : ""}</div></div></div>`;
  }).join("");
  const rec = ro.recommendation || {};
  const recHtml = rec.type === "repeat"
    ? `<div class="notice blue" style="margin-top:12px"><strong>Repeat this:</strong> ${esc(rec.title || "")}${rec.creatorName ? ` with ${esc(rec.creatorName)}` : ""}. ${esc(rec.reason || "")}${rec.offerId ? `<br><button type="button" class="btn small-btn" style="margin-top:8px" onclick="return perfRepeatFromCard()">Run it again</button>` : ""}</div>`
    : "";
  const lic = o.licenseRequests || {};
  const licLine = (lic.pending || 0) > 0 ? `<p class="small muted" style="margin:8px 0 0">${lic.pending} license request${lic.pending === 1 ? "" : "s"} waiting on a creator's answer.</p>` : "";
  return `<div class="wcard"><h3>Performance</h3>
  <div class="snap-strip" style="--snap-n:${cells.length};cursor:default">${cells.map((c) => `<span class="snap-cell"><span class="snap-num">${esc(c.num)}</span><span class="snap-lbl">${esc(c.label)}</span></span>`).join("")}</div>
  ${series ? `<p class="small muted" style="margin:8px 0 0">Post views over time: ${esc(series)}.</p>` : ""}
  ${rows}
  ${licLine}
  ${recHtml}
  </div>`;
}
async function loadPerformanceCard(root) {
  const host = (root || document).querySelector ? (root || document).querySelector("#perf-card") : document.getElementById("perf-card");
  if (!host) return;
  try {
    const ro = await api("GET", "/me/performance-readout");
    if (!document.getElementById("perf-card")) return;
    host.innerHTML = performanceCardHtml(ro);
  } catch (e) { /* the card is an enhancement; the home stands without it */ }
}
// ---------- Requests: the approvals queue (Grin Approvals) ----------
// Tabs with counts (Waiting / Decided / Later), search + offer
// filter + sort, aging with Magpie's real decision window (2
// business days — no invented auto-close), checkbox bulk select,
// expandable rows with a plain-words match reason, and a kebab
// menu mirroring Grin's: View creator profile / Ask Sig / Select
// / Request info / Later / Release. "Later" is a local park on
// this device; it never changes the application itself.
let reqState = null;
function reqFreshState() {
  return { tab: "waiting", q: "", offerId: "", sort: "fit", sel: {}, open: {}, later: JSON.parse(localStorage.getItem("signl-req-later") || "{}"), rows: [], offers: [], loaded: false };
}
function reqSaveLater() { try { localStorage.setItem("signl-req-later", JSON.stringify(reqState.later)); } catch (e) { /* private mode */ } }
function reqAgeLabel(iso) {
  const ms = Date.now() - (Date.parse(iso || "") || Date.now());
  const days = Math.floor(ms / 86400000);
  if (days >= 1) return `waiting ${days} day${days === 1 ? "" : "s"}`;
  const hrs = Math.max(Math.floor(ms / 3600000), 0);
  return hrs >= 1 ? `waiting ${hrs}h` : "just in";
}
function reqBuckets() {
  const rows = reqState.rows;
  const waiting = rows.filter((r) => r.app.status === "applied" && !reqState.later[r.app.id]);
  const later = rows.filter((r) => r.app.status === "applied" && reqState.later[r.app.id]);
  const decided = rows.filter((r) => r.app.status !== "applied");
  return { waiting, later, decided };
}
let reqEmbed = false;
async function renderRequestsTab(embed) {
  reqEmbed = !!embed;
  const el = document.getElementById(embed ? "offers-seg-body" : "tab-body");
  if (!el) return;
  if (!reqState) reqState = reqFreshState();
  el.innerHTML = `${embed ? `<div class="req-banner">Every applicant gets an answer within 2 business days. That is the deal.</div>` : wsHead("Applicants", { sub: "Creators waiting on your decision." })}<div id="req-main">${skelHtml("Loading applicants...", 2)}</div>`;
  try {
    if (!reqState.loaded) {
      const od = await api("GET", "/offers");
      const offers = (od.offers || []).filter((o) => (o.applicationCount || 0) > 0);
      reqState.offers = offers;
      const rows = [];
      for (const o of offers.slice(0, 12)) {
        const d = await api("GET", `/offers/${o.id}/applications`);
        for (const a of d.applications || []) rows.push({ offer: d.offer || o, app: a });
      }
      reqState.rows = rows;
      reqState.loaded = true;
      // One source of truth (spec §2.1): the waiting count
      // computed here is the Offers tab badge and the Home
      // queue count.
      const b = reqBuckets();
      state.waitCounts = state.waitCounts || {};
      state.waitCounts.bizApps = b.waiting.length;
      renderOffersSegTabs();
      renderBottomNav();
    }
    renderReqMain();
  } catch (err) {
    el.innerHTML = `${reqEmbed ? "" : wsHead("Applicants")}<div class="error-box">${esc(err.message)}</div>`;
  }
}
function reqFiltered(bucket) {
  let rows = bucket.slice();
  if (reqState.offerId) rows = rows.filter((r) => r.offer.id === reqState.offerId);
  const q = reqState.q.trim().toLowerCase();
  if (q) rows = rows.filter((r) => ((r.app.creator.name || "") + " " + (r.app.creator.handle || "")).toLowerCase().includes(q));
  if (reqState.sort === "newest") rows.sort((a, b) => (Date.parse(b.app.createdAt) || 0) - (Date.parse(a.app.createdAt) || 0));
  else if (reqState.sort === "local") rows.sort((a, b) => ((b.app.creator.localAudiencePct || 0) - (a.app.creator.localAudiencePct || 0)));
  else rows.sort((a, b) => ((b.app.rankScore || 0) - (a.app.rankScore || 0)));
  return rows;
}
function reqWhyHtml(r) {
  const c = r.app.creator || {};
  const rp = r.app.rankParts || {};
  const tr = c.trackRecord || {};
  const bits = [];
  if (c.localAudiencePct !== null && c.localAudiencePct !== undefined) bits.push(`${c.localAudiencePct}% of their audience lives in your market`);
  if (c.tierBand) bits.push(`${c.tierBand} tier`);
  if (rp.impactScore !== null && rp.impactScore !== undefined) bits.push(`local impact score ${rp.impactScore}`);
  if (tr.visitsCompleted) bits.push(`${tr.visitsCompleted} visit${tr.visitsCompleted === 1 ? "" : "s"} completed, ${tr.onTimePct === null || tr.onTimePct === undefined ? "no late posts" : tr.onTimePct + "% on time"}`);
  else bits.push("new to Magpie, no visits yet");
  if (rp.momentum) bits.push(`${rp.momentum} Momentum points`);
  return `<div class="req-why"><strong>Matched because:</strong> ${esc(bits.join(" · "))}.</div>`;
}
function reqRowHtml(r) {
  const a = r.app;
  const c = a.creator || {};
  const open = !!reqState.open[a.id];
  const statusBadge = { applied: `<span class="badge info">Waiting</span>`, selected: `<span class="badge ok">Selected</span>`, released: `<span class="badge">Released</span>`, expired: `<span class="badge">Window passed</span>`, backfill_offered: `<span class="badge warn">Backfill offered</span>`, backfill_accepted: `<span class="badge ok">Took backfill</span>` }[a.status] || esc(a.status);
  const menu = `<div class="kebab-menu">
    <button type="button" onclick="openCreatorProfile('${c.userId}')">View creator profile</button>
    <button type="button" onclick="openAgentSheet()">Ask Maggie</button>
    ${a.status === "applied" ? `<button type="button" data-ctx="${esc(r.offer.title)}" onclick="return openThreadCtx('${c.userId}', this.dataset.ctx)">Request info</button>
    <button type="button" onclick="return reqLater('${a.id}')">${reqState.later[a.id] ? "Move back to waiting" : "Later"}</button>
    <div class="km-sep"></div>
    <button type="button" class="danger" onclick="return reqReleaseOne('${r.offer.id}','${a.id}')">Release</button>` : `<button type="button" data-ctx="${esc(r.offer.title)}" onclick="return openThreadCtx('${c.userId}', this.dataset.ctx)">Message</button>`}
  </div>`;
  return `<div class="req-row" id="reqrow-${a.id}">
    <div class="req-top">
      ${a.status === "applied" && reqState.tab === "waiting" ? `<input type="checkbox" class="req-check" ${reqState.sel[a.id] ? "checked" : ""} onchange="reqToggleSel('${a.id}', this.checked)" aria-label="Select ${esc(c.name || "creator")}">` : ""}
      <span class="req-ava">${esc((c.name || "").trim().charAt(0).toUpperCase() || "S")}</span>
      <div class="req-main" onclick="return reqToggleOpen('${a.id}')" style="cursor:pointer">
        <div class="req-name">${esc(c.name || "")} ${statusBadge}</div>
        <div class="req-meta">${handleLabel(c.handle) ? `${esc(handleLabel(c.handle))} · ` : ""}for <strong>${esc(r.offer.title)}</strong></div>
      </div>
      <span class="kebab-wrap"><button type="button" class="kebab-btn" aria-label="More actions" onclick="return reqKebab(event,'${a.id}')">&#8943;</button>${reqState.kebab === a.id ? menu : ""}</span>
    </div>
    <div class="req-body">
      <div class="req-meta">applied ${fmtDay(a.createdAt)}${a.status === "applied" ? ` · ${reqAgeLabel(a.createdAt)}` : a.decidedAt ? ` · decided ${fmtDay(a.decidedAt)}` : ""}${c.localAudiencePct !== null && c.localAudiencePct !== undefined ? ` · ${c.localAudiencePct}% local` : ""}${c.totalAudience ? ` · ${fmtNum(c.totalAudience)} audience` : ""}${c.tierBand ? ` · ${esc(c.tierBand)}` : ""}</div>
      ${open ? reqWhyHtml(r) : ""}
      ${a.status === "applied" ? `<div class="req-acts">
        <button type="button" class="btn small-btn ws-primary" onclick="return reqSelectOne('${r.offer.id}','${a.id}')">Select</button>
        <button type="button" class="btn small-btn ws-outline" data-ctx="${esc(r.offer.title)}" onclick="return openThreadCtx('${c.userId}', this.dataset.ctx)">Request info</button>
        <button type="button" class="btn small-btn ws-outline" onclick="return reqLater('${a.id}')">${reqState.later[a.id] ? "Back to waiting" : "Later"}</button>
        <button type="button" class="btn small-btn ws-outline" onclick="return reqToggleOpen('${a.id}')">${open ? "Hide match" : "Why this match"}</button>
        <button type="button" class="btn small-btn ws-outline danger" onclick="return reqReleaseOne('${r.offer.id}','${a.id}')">Release</button>
      </div>` : ""}
    </div>
  </div>`;
}
function renderReqMain() {
  const host = document.getElementById("req-main");
  if (!host || !reqState) return;
  const b = reqBuckets();
  const bucket = reqState.tab === "waiting" ? b.waiting : reqState.tab === "later" ? b.later : b.decided;
  const rows = reqFiltered(bucket);
  const oldest = b.waiting.length ? Math.max(...b.waiting.map((r) => Date.now() - (Date.parse(r.app.createdAt) || Date.now()))) : 0;
  const selCount = Object.keys(reqState.sel).filter((k) => reqState.sel[k]).length;
  host.innerHTML = `
    ${wsTabs([
      { label: "Waiting", count: b.waiting.length, on: reqState.tab === "waiting", onclick: "return reqSetTab('waiting')" },
      { label: "Decided", count: b.decided.length, on: reqState.tab === "decided", onclick: "return reqSetTab('decided')" },
      { label: "Later", count: b.later.length, on: reqState.tab === "later", onclick: "return reqSetTab('later')" },
    ])}
    ${reqState.tab === "waiting" && b.waiting.length ? `<div class="req-alert"><strong>${b.waiting.length} unreviewed application${b.waiting.length === 1 ? "" : "s"}.</strong> Magpie's promise is a decision within 2 business days${oldest >= 2 * 86400000 ? ` — the oldest has been waiting ${Math.floor(oldest / 86400000)} days` : ""}. Every applicant hears back, either way.</div>` : ""}
    <div class="ws-tools">
      <span class="ws-search">${bnIcon("search")}<input id="req-q" type="search" placeholder="Search creators" value="${esc(reqState.q)}" oninput="reqSetQ(this.value)"></span>
      <select class="ws-select" onchange="reqSetOffer(this.value)" aria-label="Filter by offer"><option value="">All offers</option>${reqState.offers.map((o) => `<option value="${o.id}" ${reqState.offerId === o.id ? "selected" : ""}>${esc(o.title)}</option>`).join("")}</select>
      <select class="ws-select" onchange="reqSetSort(this.value)" aria-label="Sort requests">
        <option value="fit" ${reqState.sort === "fit" ? "selected" : ""}>Best fit</option>
        <option value="newest" ${reqState.sort === "newest" ? "selected" : ""}>Newest</option>
        <option value="local" ${reqState.sort === "local" ? "selected" : ""}>Local reach</option>
      </select>
    </div>
    ${rows.length ? `<div class="req-list">${uxCap203(rows.map(reqRowHtml), 8)}</div>` : `<div class="empty-card"><div class="ec-t">${reqState.tab === "waiting" ? "No applicants yet" : "No requests here"}</div><div class="ec-s">${reqState.tab === "waiting" ? "Invite creators directly, or share your offer, and applications land here. Every applicant gets an answer within 2 business days." : reqState.tab === "later" ? "Applications you park for later sit here. Parking never notifies the creator." : "Decisions you make show up here, so the record is never a mystery."}</div></div>`}
    ${selCount ? `<div class="req-bulk"><span>${selCount} selected</span><button type="button" class="btn small-btn" onclick="return reqBulk('select')">Select all</button><button type="button" class="btn small-btn ghost" style="color:#fff;border-color:#3A443C" onclick="return reqBulk('release')">Release</button><button type="button" class="linklike" style="color:#C6CFC6" onclick="return reqClearSel()">Clear</button></div>` : ""}`;
  wireReady(host);
}
function reqSetTab(t) { reqState.tab = t; reqState.kebab = null; renderReqMain(); return false; }
function reqSetQ(v) { reqState.q = v; const host = document.getElementById("req-main"); renderReqMain(); const inp = document.getElementById("req-q"); if (inp) { inp.focus(); inp.setSelectionRange(inp.value.length, inp.value.length); } return false; }
function reqSetOffer(v) { reqState.offerId = v; renderReqMain(); return false; }
function reqSetSort(v) { reqState.sort = v; renderReqMain(); return false; }
function reqToggleSel(id, on) { reqState.sel[id] = on; renderReqMain(); return false; }
function reqClearSel() { reqState.sel = {}; renderReqMain(); return false; }
function reqToggleOpen(id) { reqState.open[id] = !reqState.open[id]; renderReqMain(); return false; }
function reqKebab(e, id) { if (e) e.stopPropagation(); reqState.kebab = reqState.kebab === id ? null : id; renderReqMain(); return false; }
function reqLater(id) { if (reqState.later[id]) delete reqState.later[id]; else reqState.later[id] = 1; reqSaveLater(); reqState.kebab = null; renderReqMain(); return false; }
async function reqSelectOne(offerId, appId) {
  // Direct API (not selectApplicant): that helper re-renders My
  // Offers on success, which would fight this screen's refresh.
  try {
    await api("POST", `/offers/${offerId}/select`, { applicationId: appId });
  } catch (err) { alert(err.message); return false; }
  reqState.loaded = false; reqState.sel = {};
  renderRequestsTab(reqEmbed);
  return false;
}
async function reqReleaseOne(offerId, appId) {
  if (!window.confirm("Release this applicant? They are told right away, with the reason in plain words.")) return false;
  try {
    await api("POST", `/offers/${offerId}/release`, { applicationId: appId });
  } catch (err) { alert(err.message); return false; }
  reqState.loaded = false; reqState.kebab = null;
  renderRequestsTab(reqEmbed);
  return false;
}
async function reqBulk(which) {
  const b = reqBuckets();
  const chosen = b.waiting.filter((r) => reqState.sel[r.app.id]);
  if (!chosen.length) return false;
  if (!window.confirm(`${which === "select" ? "Select" : "Release"} ${chosen.length} application${chosen.length === 1 ? "" : "s"}? ${which === "select" ? "Each one books its visit." : "Each creator is told, kindly and with a reason."}`)) return false;
  for (const r of chosen) {
    try { await api("POST", `/offers/${r.offer.id}/${which === "select" ? "select" : "release"}`, { applicationId: r.app.id }); }
    catch (e) { alert(e.message); break; }
  }
  reqState.loaded = false; reqState.sel = {};
  renderRequestsTab(reqEmbed);
  return false;
}

// ---------- Content: posts + rights (Grin Content) ----------
let contentTab = "creator";
// ---------- Build -95: My Regulars ----------
// A creator becomes a Regular when a visit with them is
// completed and their post is live. Each row: the deal that
// ran on the last visit, that visit's results in the three
// honesty classes on their own labeled lines (counted at the
// register, recorded post numbers, intent as saves + shares;
// never added together), a private note only this business
// can see, and Book again, which clones the last booking's
// terms into a new draft. The draft sends nothing until the
// business publishes it from Campaigns.
function regularResultsHtml(r) {
  const res = r.results || {};
  const counted = res.counted
    ? `<div class="lib-meta"><strong>Counted:</strong> ${fmtNum(res.counted.customers)} customers counted at your register · $${fmtMoney(res.counted.registerDollars)} rung up</div>`
    : `<div class="lib-meta"><strong>Counted:</strong> no customers counted at the register for this visit yet</div>`;
  const rec = res.recorded || {};
  const recorded = (rec.views === null || rec.views === undefined) && (rec.likes === null || rec.likes === undefined)
    ? `<div class="lib-meta"><strong>Recorded:</strong> the creator has not reported this post's numbers yet</div>`
    : `<div class="lib-meta"><strong>Recorded:</strong> ${rec.views === null || rec.views === undefined ? "views not reported" : fmtNum(rec.views) + " views"} · ${rec.likes === null || rec.likes === undefined ? "likes not reported" : fmtNum(rec.likes) + " likes"} (reported by the creator)</div>`;
  const intent = res.intent
    ? `<div class="lib-meta"><strong>Intent:</strong> ${fmtNum(res.intent.shares || 0)} shares and ${fmtNum(res.intent.saves || 0)} saves recorded on this post (people planning to come)</div>`
    : `<div class="lib-meta"><strong>Intent:</strong> no saves or shares reported for this post yet</div>`;
  return counted + recorded + intent;
}
function regularRowHtml(r) {
  return `<div class="lib-row" style="align-items:flex-start">
    <div class="lib-main">
      <div class="lib-title">${esc(r.creatorName)} <span class="muted" style="font-weight:600">@${esc(r.creatorHandle)}</span> <span class="badge ok">Regular</span></div>
      <div class="lib-meta">${fmtNum(r.visits)} completed ${r.visits === 1 ? "visit" : "visits"} · last visit ${r.lastVisitAt ? fmtDay(r.lastVisitAt) : "on record"}${r.lastTitle ? ` · "${esc(r.lastTitle)}"` : ""}</div>
      <div class="lib-meta"><strong>Last deal:</strong> ${esc(r.deal.line)}</div>
      <div class="lib-meta">${esc(r.deal.rightsLine)}</div>
      ${regularResultsHtml(r)}
      <div class="field" style="margin-top:8px"><label>Your private note (only you can see this)</label>
        <textarea id="reg-note-${esc(r.creatorId)}" rows="2" maxlength="1000" placeholder="For example: great with the weekend brunch crowd, kids love her">${esc(r.note || "")}</textarea></div>
      <span class="small muted" id="reg-note-ok-${esc(r.creatorId)}"></span>
    </div>
    <div style="display:flex;flex-direction:column;gap:6px">
      <button type="button" class="btn small-btn ws-primary" onclick="return regularBookAgain('${esc(r.creatorId)}', this)">Book again</button>
      <button type="button" class="btn small-btn ghost" onclick="return regularSaveNote('${esc(r.creatorId)}', this)">Save note</button>
    </div>
  </div>`;
}
async function renderRegularsTab() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = `${wsHead("My Regulars", { sub: "Creators who have visited you and posted. Book them again in one tap.", subKey: "biz-regulars" })}${skelHtml("Loading your Regulars...", 2)}`;
  try {
    const d = await api("GET", "/me/regulars");
    const rows = d.regulars || [];
    if (!document.getElementById("tab-body")) return;
    el.innerHTML = `
    ${wsHead("My Regulars", { sub: "Creators who have visited you and posted. Book them again in one tap.", subKey: "biz-regulars" })}
    ${wsTabs([
      { label: "Browse", on: false, onclick: "return go('dashboard','Discover')" },
      { label: "My Regulars", on: true, onclick: "return go('dashboard','Regulars')" },
      { label: "Saved", on: false, onclick: "return go('dashboard','Favorites')" },
    ])}
    ${rows.length
      ? `<div class="wcard" style="padding-top:8px;padding-bottom:8px">${uxCap203(rows.map(regularRowHtml), 8)}</div>
         <p class="small muted" style="margin-top:10px">Book again copies the last visit's deal into a new draft in Campaigns. Nothing sends until you publish the draft. Your notes are yours alone: creators never see them, and no other business can.</p>`
      : `<div class="empty-card"><div class="ec-t">No Regulars yet</div><div class="ec-s">When a creator finishes a visit with you and their post goes live, they show up here with the deal that ran, what the visit did, and a Book again button. Your first Regular is one completed visit away.</div></div>`}`;
  } catch (err) {
    el.innerHTML = `${wsHead("My Regulars")}<div class="error-box">${esc(err.message)}</div>`;
  }
}
async function regularSaveNote(creatorId, btn) {
  const ta = document.getElementById("reg-note-" + creatorId);
  const ok = document.getElementById("reg-note-ok-" + creatorId);
  if (!ta) return false;
  try {
    await api("PUT", `/me/regulars/${creatorId}/note`, { note: ta.value });
    if (ok) ok.textContent = "Saved. Only you can see this note.";
  } catch (e) { if (ok) ok.textContent = e.message; }
  return false;
}
// Build -154: Have them back — the same Book again draft clone,
// started from the creator's page. One tap copies the last
// visit's terms into a new draft in Campaigns; nothing sends
// until the business checks it and publishes.
async function haveThemBack(creatorId, btn) {
  const label = btn ? btn.textContent : "Have them back";
  if (btn) { btn.disabled = true; btn.textContent = "Drafting..."; }
  try {
    const d = await api("POST", `/me/regulars/${creatorId}/book-again`, {});
    state.offersSeg = "drafts";
    toast(`Draft created: "${d.offer.title}" has the same terms as the last visit. Nothing was sent — open the draft to check it and publish when you are ready.`);
    return go("dashboard", "My Offers");
  } catch (e) {
    toast(e.message, true);
    if (btn) { btn.disabled = false; btn.textContent = label; }
  }
  return false;
}

async function regularBookAgain(creatorId, btn) {
  if (btn) { btn.disabled = true; btn.textContent = "Drafting..."; }
  try {
    const d = await api("POST", `/me/regulars/${creatorId}/book-again`, {});
    state.offersSeg = "drafts";
    alert(`Draft created: "${d.offer.title}" is saved in Your campaigns as a draft with the same terms as the last visit. Nothing was sent. Open the draft to check it and publish when you are ready.`);
    return go("dashboard", "My Offers");
  } catch (e) {
    alert(e.message);
    if (btn) { btn.disabled = false; btn.textContent = "Book again"; }
  }
  return false;
}

// ---------- Build -95: licence-expiry alert card ----------
// Rides the top of Posts & licenses: held licences ending
// within 14 days (or just ended), the exact end date on each,
// and Ask to renew, which sends a fresh request through the
// creator-approved licensing flow. Nothing renews on its own.
async function askRenewLicense(postId, fee, endsOn) {
  if (!fee) { alert("This creator has not listed a licensing fee, so this post cannot be renewed through Magpie. It stays shareable inside Instagram with credit."); return false; }
  const total = Math.round(fee * 1.03 * 100) / 100;
  const net = Math.round(fee * 0.97 * 100) / 100;
  if (!confirm(`Ask to renew this licence? Your current licence ends ${endsOn}. The request goes to the creator at their $${fmtPrice(fee)} fee: you pay $${fmtMoney(total)} (fee + 3%) only if they approve, the creator keeps $${fmtMoney(net)} (97%), and a fresh 90 days starts the day they approve. Nothing renews unless they say yes.`)) return false;
  try {
    await api("POST", `/posts/${postId}/license-request`, {});
    alert("Renewal request sent. It is waiting on the creator's yes or no, and the licence only continues if they approve.");
    if (state.tab === "Content") renderContentTab();
  } catch (err) { alert(err.message); }
  return false;
}
async function loadLicenceExpiryCard() {
  const host = document.getElementById("biz-lic-expiry");
  if (!host) return;
  try {
    const d = await api("GET", "/me/licences-expiring");
    const rows = d.licences || [];
    if (!document.getElementById("biz-lic-expiry")) return;
    if (!rows.length) { host.innerHTML = ""; return; }
    host.innerHTML = `<section class="wcard" style="margin-bottom:14px;border-left:4px solid var(--acc,#006AFC)">
      <h3 style="margin-top:0">Licences ending soon</h3>
      <p class="small muted" style="margin-top:0">When a licence ends, you can no longer repost that post or run it as an ad. Extend or license separately and the creator decides: a fresh 90 days at their listed fee, only with their approval. Nothing renews on its own.</p>
      ${rows.map((l) => `<div class="lib-row"><div class="lib-main"><div class="lib-title">${esc(l.title)}</div>
        <div class="lib-meta">@${esc(l.creatorHandle)} · ${l.kind === "standard" ? "standard licence from a paid booking (included)" : "licensed post"} · ${l.ended ? `<strong>ended ${fmtDay(l.windowEndsAt)}</strong>` : `ends <strong>${fmtDay(l.windowEndsAt)}</strong> (${l.daysLeft} ${l.daysLeft === 1 ? "day" : "days"} left)`}${l.postUrl ? ` · <a href="${esc(l.postUrl)}" target="_blank" rel="noopener">View post</a>` : ""}</div></div>
        <button type="button" class="btn small-btn ws-primary" onclick="return askRenewLicense('${esc(l.postId)}', ${l.fee || 0}, '${esc(fmtDay(l.windowEndsAt))}')">Extend or license separately</button></div>`).join("")}
    </section>`;
  } catch (e) { /* the library below still renders; the card is an alert, never a blocker */ }
}

function contentSetTab(t) { contentTab = t; renderContentTab(); return false; }
function libRowsHtml(h, mode, licMap) {
  const lib = h.contentLibrary || [];
  const rows = mode === "yours" ? lib.filter((r) => r.license && r.license.type !== "native") : lib;
  if (!rows.length) return `<div class="empty-card"><div class="ec-t">${mode === "yours" ? "Nothing licensed yet" : "No posts yet"}</div><div class="ec-s">${mode === "yours" ? "Posts you can repost or run as ads appear here: paid bookings carry one 90-day license, and comped posts can be licensed from the creator." : "When a creator posts about your business, it lands here, and you can license the ones you want to reuse."}</div></div>`;
  return `<div class="wcard" style="padding-top:8px;padding-bottom:8px">${uxCap203(rows.map((r) => {
    const lic = (licMap || {})[r.bookingId];
    const canLicense = mode === "creator" && r.license && r.license.type === "native" && lic && lic.fee > 0 && lic.postId;
    const canExtend = r.license && r.license.type !== "native" && lic && lic.postId && !lic.requested;
    return `
    <div class="lib-row"><div class="lib-main"><div class="lib-title">${esc(r.title)}</div>
    <div class="lib-meta">@${esc(r.creatorHandle)} · ${r.postedAt ? fmtDay(r.postedAt) : ""} · ${fmtNum(r.views)} views · ${fmtNum(r.likes)} likes · ${fmtNum(r.localReach || 0)} local reach · ${r.onTime ? "on time" : "late"}${r.kind === "coupon" ? " · Coupon post" : r.kind === "paid" ? " · Paid post" : ""}${r.redemptions && r.redemptions.count ? ` · ${r.redemptions.count} code uses · $${fmtMoney(r.redemptions.basketTotal)} rung up` : ""}${r.postUrl ? ` · <a href="${esc(r.postUrl)}" target="_blank" rel="noopener">View post</a>` : ""}</div>${licWindowLine(r.license)}</div>${licPillHtml(r.license)}${canLicense ? (lic.requested ? `<span class="lic-pill">License requested</span>` : `<button type="button" class="btn small-btn ws-primary" onclick="requestLicense('${lic.postId}', ${lic.fee})">Request license</button>`) : canExtend ? `<button type="button" class="btn small-btn ws-outline" onclick="return extendLicence('${lic.postId}', ${lic.fee || 0}, '${esc(r.license.windowEndsAt || "")}')">Extend or license separately</button>` : ""}</div>`;
  }), 8)}</div>`;
}
async function renderContentTab() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = `${wsHead("Posts & licenses")}${skelHtml("Loading posts...", 2)}`;
  try {
    // Build -68: business-home refuses founding businesses by
    // design; the editor degrades to zeros so a founding
    // business can still open and edit its page.
    const d = await api("GET", "/me/business-home").catch(() => null);
    const h = (d && d.home) || { localReachDelivered: 0, postsLive: 0 };
    const lib = h.contentLibrary || [];
    const usable = lib.filter((r) => r.license && r.license.type !== "native").length;
    // License actions join each post to its booking: the fee
    // and post id live on the booking, not the library row.
    const licMap = {};
    try {
      const bd = await api("GET", "/bookings");
      const lr = await api("GET", "/license-requests").catch(() => ({ licenseRequests: [] }));
      const pendingPosts = new Set((lr.licenseRequests || []).filter((l) => l.status === "pending").map((l) => l.postId));
      for (const b of bd.bookings || []) if (b.post) licMap[b.id] = { postId: b.post.id, fee: Number(b.creatorLicensingFee) || 0, requested: pendingPosts.has(b.post.id) };
    } catch (e) { /* rows simply render without the action */ }
    el.innerHTML = `
    ${wsHead("Posts & licenses", { sub: "Every post about you, and the ones you can reuse.", subKey: "biz-content" })}
    <div id="biz-lic-expiry"></div>
    <div class="rights-line">${bnIcon("shield")}<span><strong>Seeing a post here is not the right to reuse it.</strong> You may always reshare the post inside Instagram, with credit. Paid bookings include one standard license: 90 days to repost and run ads. A comped post can be licensed at the creator's listed fee, and the creator approves each use. That license is what makes the post UGC you can use: repost it and run it as an ad for those 90 days. Every license below shows its end date, and no license ever runs longer than 90 days.</span></div>
    ${lib.length ? `<div class="track-card"><span class="feed-dot acc">${bnIcon("image")}</span><div class="tc-main"><div class="tc-t">Post tracking is on</div><div class="tc-s">${h.postsTracked30 || 0} post${(h.postsTracked30 || 0) === 1 ? "" : "s"} tracked in the last 30 days. Magpie tracks every visit's post from the creator's report, timed against the 48 hour standard.</div></div><button type="button" class="btn small-btn ws-outline" onclick="return go('dashboard','Visits & Posts')">Visits</button></div>`
      : `<div class="track-card"><span class="feed-dot acc">${bnIcon("image")}</span><div class="tc-main"><div class="tc-t">Post tracking</div><div class="tc-s">Post tracking starts with your first visit.</div></div></div>`}
    ${wsTabs([
      { label: "Creator posts", count: lib.length, on: contentTab === "creator", onclick: "return contentSetTab('creator')" },
      { label: "Yours to use", count: usable, on: contentTab === "yours", onclick: "return contentSetTab('yours')" },
    ])}
    ${libRowsHtml(h, contentTab, licMap)}`;
    loadLicenceExpiryCard();
  } catch (err) {
    el.innerHTML = `${wsHead("Posts & licenses")}<div class="error-box">${esc(err.message)}</div>`;
  }
}
// ---------- Analytics: charts, funnel, leaderboard (Grin mirror) ----------
let anaDays = 30;
function anaSetDays(v) { anaDays = Number(v) || 30; renderAnalyticsTab(); return false; }
// ---------- Build -58: role stats views ----------
// The Command Center's Money-overview discipline, scoped to
// the signed-in record owner: one stats card inside each
// role's existing surface (business Results, partner
// Performance, creator Your numbers), fed by GET /me/stats
// and re-fetched on the Week / Month / Year / All time
// toggle. Classes never blend in the rendering either:
// counted, recorded and charged get their own panels and
// chips, exactly as on Admin's Money view.
const ROLE_PERIODS = [
  { v: "week", label: "Week" }, { v: "month", label: "Month" },
  { v: "year", label: "Year" }, { v: "all", label: "All time" },
];
let bizStatsP = "month", ptStatsP = "month", crStatsP = "month";
const rsPl = (n, one) => n + " " + one + (n === 1 ? "" : "s");
function roleStatsHead(title, cur, fn) {
  return `<div class="flex-between" style="align-items:flex-start;gap:10px;flex-wrap:wrap"><h3 style="margin:0">${esc(title)}</h3>${segSw(ROLE_PERIODS, cur, fn)}</div>`;
}

// Business — "Your numbers" at the top of Results. The
// Receipt stays below it as the proof deep-view; the counted
// figure here and the Receipt's counted figure are the same
// records, so the two always agree.
async function loadBizStats() {
  if (!document.getElementById("biz-stats")) return;
  try {
    const d = await api("GET", `/me/stats?period=${bizStatsP}`);
    const host = document.getElementById("biz-stats");
    if (host) host.innerHTML = bizStatsHtml(d);
    loadBizStats226();
  } catch (e) { /* Results still carries the Receipt; a stats failure never breaks the page */ }
}
function bizStatsPeriod(v) { bizStatsP = v; loadBizStats(); return false; }
function bizStatsHtml(d) {
  const s = d.stats || {};
  const per = d.period || {};
  const head = roleStatsHead("Your numbers", per.key || bizStatsP, "bizStatsPeriod");
  if (!s.hasData) {
    return `<div class="panel">${head}
      <p class="small" style="margin:8px 0 0">Nothing has landed yet — and nothing here is invented to fill the space. When your first offer runs, this fills in with what you spent (your plan at what was actually charged, comp costs, paid bookings, licenses), what came back counted at your register, and the deals that finished. Your Receipt below carries the proof, visit by visit.</p></div>`;
  }
  const cnt = s.counted || {};
  const rec = s.recorded || { rows: {} };
  const rr = rec.rows || {};
  const chg = s.charged || { rows: {} };
  const cr = chg.rows || {};
  const cc = s.compCosts || {};
  const deals = s.deals || {};
  const escw = s.escrow || {};
  const sub = rr.subscriptions || {};
  const tiles = `<div class="cc-tiles" style="margin-top:10px">
    <div class="cc-tile cc-hero"><div class="cc-tlabel">Counted at your register <span class="cc-chip counted">Counted</span></div><div class="cc-tnum">${ccMoneyFmt(cnt.total || 0)}</div><div class="cc-tsub">${ccMoneyFmt(cnt.firsts || 0)} on first visits (${cnt.visitsCounted || 0} counted) &middot; ${ccMoneyFmt(cnt.returns || 0)} on come-backs</div></div>
    <div class="cc-tile"><div class="cc-tlabel">Money out, on cards <span class="cc-chip charged">Charged</span></div><div class="cc-tnum">${ccMoneyFmt(chg.netTotal || 0)}</div><div class="cc-tsub">Real charges this period, refunds out</div></div>
    <div class="cc-tile"><div class="cc-tlabel">Money out, on the books <span class="cc-chip recorded">Recorded</span></div><div class="cc-tnum">${ccMoneyFmt((rec.totals || {}).flowed || 0)}</div><div class="cc-tsub">Plan, paid bookings and licenses on record</div></div>
    <div class="cc-tile"><div class="cc-tlabel">Deals finished</div><div class="cc-tnum">${deals.total || 0}</div><div class="cc-tsub">${rsPl(deals.compVisits || 0, "comp visit")} &middot; ${rsPl(deals.paidBookings || 0, "paid booking")} &middot; ${rsPl(deals.licenses || 0, "license")}</div></div>
    <div class="cc-tile"><div class="cc-tlabel">Comps posted</div><div class="cc-tnum">${s.compsCompleted || 0}</div><div class="cc-tsub">${s.compsCounted || 0} counted at the register &middot; costs entered on ${cc.entered || 0} of ${cc.completed || 0}${cc.missing ? ` &middot; ${cc.missing} still missing theirs` : ""}</div></div>
    <div class="cc-tile"><div class="cc-tlabel">Offers live now</div><div class="cc-tnum">${s.offersLive || 0}</div><div class="cc-tsub">Open right now, in every period</div></div>
  </div>`;
  const recordedPanel = `<div class="panel">
    <h3 style="margin:0 0 2px">Money out — on the books <span class="cc-chip recorded">Recorded</span></h3>
    <p class="muted small" style="margin:0 0 8px">What your records say moved this period, whether or not a card was charged.</p>
    <div class="table-wrap ct199"><table>
      <tr><th>What</th><th>Amount</th><th>Notes</th></tr>
      ${typeof sub.monthlyRate === "number" ? `<tr><td>Your plan${sub.planName ? ` — ${esc(sub.planName)}` : ""} <span class="cc-chip recorded">Recorded</span></td><td data-label="Amount">${ccMoneyFmt(sub.monthlyRate)}/mo</td><td data-label="Notes">On record; the Charged panel below shows what a card actually paid</td></tr>` : ""}
      <tr><td>Paid bookings <span class="cc-chip recorded">Recorded</span></td><td data-label="Amount">${ccMoneyFmt((rr.paidBookings || {}).flowed || 0)}</td><td data-label="Notes">${(rr.paidBookings || {}).count || 0} released &middot; creators kept ${ccMoneyFmt((rr.paidBookings || {}).creatorsEarned || 0)}</td></tr>
      <tr><td>Licenses <span class="cc-chip recorded">Recorded</span></td><td data-label="Amount">${ccMoneyFmt((rr.licenses || {}).flowed || 0)}</td><td data-label="Notes">${(rr.licenses || {}).count || 0} granted &middot; creators kept ${ccMoneyFmt((rr.licenses || {}).creatorsEarned || 0)}</td></tr>
      <tr><td>Comp costs <span class="cc-chip recorded">Recorded</span></td><td data-label="Amount">${ccMoneyFmt(cc.total || 0)}</td><td data-label="Notes">Costs you entered on ${cc.entered || 0} of ${cc.completed || 0} completed comps${cc.missing ? ` — ${cc.missing} still to enter (a visit's cap is an estimate, never counted as a cost)` : ""}</td></tr>
    </table></div>
    ${(escw.paidHeld || {}).count ? `<p class="small" style="margin:6px 0 0">In escrow right now: ${ccMoneyFmt((escw.paidHeld || {}).businessTotal || 0)} across ${(escw.paidHeld || {}).count} paid booking${(escw.paidHeld || {}).count === 1 ? "" : "s"} — recorded, not yet flowed.</p>` : ""}
  </div>`;
  const chargedPanel = `<div class="panel">
    <h3 style="margin:0 0 2px">Money out — on cards <span class="cc-chip charged">Charged</span></h3>
    <p class="muted small" style="margin:0 0 8px">Real card charges this period. A plan with no charge yet lives in Recorded above, never here.</p>
    <div class="table-wrap ct199"><table>
      <tr><th>Source</th><th>Gross</th><th>Founding credit</th><th>Net charged</th></tr>
      <tr><td>Plan charges (${(cr.subscriptions || {}).count || 0})</td><td data-label="Gross">${ccMoneyFmt((cr.subscriptions || {}).gross || 0)}</td><td data-label="Founding credit">&minus;${ccMoneyFmt((cr.subscriptions || {}).creditApplied || 0)}</td><td data-label="Net charged">${ccMoneyFmt((cr.subscriptions || {}).net || 0)}</td></tr>
      <tr><td>Paid bookings (${(cr.paidBookings || {}).count || 0})</td><td data-label="Gross">&mdash;</td><td data-label="Founding credit">&mdash;</td><td data-label="Net charged">${ccMoneyFmt((cr.paidBookings || {}).net || 0)}</td></tr>
      <tr><td>Licenses (${(cr.licenses || {}).count || 0})</td><td data-label="Gross">&mdash;</td><td data-label="Founding credit">&mdash;</td><td data-label="Net charged">${ccMoneyFmt((cr.licenses || {}).net || 0)}</td></tr>
      <tr><td>Refunds</td><td data-label="Gross">&mdash;</td><td data-label="Founding credit">&mdash;</td><td data-label="Net charged">${ccMoneyFmt((cr.refunds || {}).net || 0)}</td></tr>
      <tr class="cc-total-row"><td><strong>Net charged</strong></td><td data-label="Gross">&mdash;</td><td data-label="Founding credit">&mdash;</td><td data-label="Net charged"><strong>${ccMoneyFmt(chg.netTotal || 0)}</strong></td></tr>
    </table></div>
    ${chg.failedCount ? `<p class="small" style="margin:6px 0 0">${chg.failedCount} failed charge attempt${chg.failedCount === 1 ? "" : "s"} this period — never in the totals.</p>` : ""}
  </div>`;
  const countedPanel = `<div class="panel">
    <h3 style="margin:0 0 2px">Counted at your register <span class="cc-chip counted">Counted</span></h3>
    <p class="small" style="margin:0">${ccMoneyFmt(cnt.total || 0)} counted at your register this period — ${ccMoneyFmt(cnt.firsts || 0)} on first visits and ${ccMoneyFmt(cnt.returns || 0)} on come-backs. Register dollars are your revenue, counted by Magpie; they are never added to the money-out panels above. Your Receipt below proves them visit by visit, and the two always agree.</p>
  </div>`;
  return `<div class="panel">${head}${tiles}</div>${recordedPanel}${chargedPanel}${countedPanel}`;
}

