// Sig in Admin (Jeff, 2026-10-28): Jeff's attention list, in
// plain sentences with real counts, computed from the same three
// payloads Admin already loads (applications, markets, partners).
// No new endpoints. READ-ONLY guidance: each item routes to the
// Admin tab where the action lives, and Jeff's taps there remain
// the only writes. Sig's face rides the shared hero stack (poster
// + idle loop; stills under reduced motion).
function adminSigItems(apps, marketsData, partnersData) {
  const items = [];
  if (apps) {
    const pending = apps.pending || [];
    const pendCreators = pending.filter((u) => u.role === "creator").length;
    const pendBiz = pending.filter((u) => u.role === "business").length;
    if (pendCreators) items.push({ text: `${pendCreators} creator ${pendCreators === 1 ? "application is" : "applications are"} waiting for a decision.`, tab: "Applications", btn: "Review queue" });
    if (pendBiz) items.push({ text: `${pendBiz} founding business ${pendBiz === 1 ? "application is" : "applications are"} waiting for a decision.`, tab: "Applications", btn: "Review queue" });
    const all = pending.concat(apps.decided || []);
    const now = new Date();
    const isToday = (iso) => { const dt = new Date(iso || ""); return dt.getFullYear() === now.getFullYear() && dt.getMonth() === now.getMonth() && dt.getDate() === now.getDate(); };
    const claimsToday = all.filter((u) => u.role === "creator" && isToday(u.createdAt));
    if (claimsToday.length) {
      const byMarket = new Map();
      for (const u of claimsToday) byMarket.set(u.market || "Unlisted", (byMarket.get(u.market || "Unlisted") || 0) + 1);
      const parts = [...byMarket.entries()].sort((a, b) => b[1] - a[1]).map(([m, n]) => `${marketDisplayName(m)} ${n}`).join(" · ");
      items.push({ text: `Claims today: ${claimsToday.length} (${parts}).`, tab: "Applications", btn: "Review queue" });
    }
  }
  if (marketsData) {
    for (const m of marketsData.markets || []) {
      if (m.businessesFounding > 0) items.push({ text: `${m.businessesFounding} approved founding ${m.businessesFounding === 1 ? "business" : "businesses"} in ${m.label} ${m.businessesFounding === 1 ? "is" : "are"} waiting on activation.`, tab: "Markets", btn: "Open Markets" });
    }
    // Build -116: the reach leader, from the same combined
    // totals the Markets cards print (never a second source).
    const reachRows = (marketsData.markets || []).filter((m) => (m.combinedFollowers || 0) > 0);
    if (reachRows.length) {
      const top = reachRows.slice().sort((a, b) => (b.combinedFollowers || 0) - (a.combinedFollowers || 0))[0];
      items.push({ text: `${top.label} carries the most combined reach: ${fmtNum(top.combinedFollowers)} combined followers across ${fmtNum(top.creatorsListed || 0)} listed ${(top.creatorsListed || 0) === 1 ? "creator" : "creators"} (as reported by creators).`, tab: "Markets", btn: "Open Markets" });
    }
  }
  if (partnersData) {
    const partners = partnersData.partners || [];
    if (!partners.length) items.push({ text: "No partners yet. Create the first one, or seed the demo to show the partner dashboard.", tab: "Partners", btn: "Open Partners" });
    else {
      if (!partners.some((p) => p.demo)) items.push({ text: "The demo partner is not seeded. Seed Demo Media Group before you demo the partner dashboard.", tab: "Partners", btn: "Open Partners" });
      const paused = partners.filter((p) => p.status !== "active").length;
      if (paused) items.push({ text: `${paused} ${paused === 1 ? "partner is" : "partners are"} paused.`, tab: "Partners", btn: "Open Partners" });
    }
  }
  return items;
}

// Build -121: the Admin home summary strip — the counts
// Jeff scans for (applications waiting, claims today,
// businesses waiting on activation), computed from the same
// three payloads Sig's attention list reads, rendered as
// tappable chips that land on the tab where the work lives.
function adminSummaryCounts121(apps, marketsData, partnersData) {
  const c = { waiting: 0, claimsToday: 0, bizWaiting: 0, partnersPaused: 0 };
  if (apps) {
    const pending = apps.pending || [];
    c.waiting = pending.length;
    const now = new Date();
    const isToday = (iso) => { const dt = new Date(iso || ""); return dt.getFullYear() === now.getFullYear() && dt.getMonth() === now.getMonth() && dt.getDate() === now.getDate(); };
    c.claimsToday = pending.concat(apps.decided || []).filter((u) => u.role === "creator" && isToday(u.createdAt)).length;
  }
  if (marketsData) for (const m of marketsData.markets || []) c.bizWaiting += m.businessesFounding || 0;
  if (partnersData) c.partnersPaused = (partnersData.partners || []).filter((p) => p.status !== "active").length;
  return c;
}
function adminSummaryHtml121(c) {
  const chip = (n, label, tab) => `<button type="button" class="sum-chip121" onclick="return go('dashboard','${tab}')"><span class="sum-num121">${fmtNum(n)}</span><span class="sum-lbl121">${label}</span></button>`;
  const chips = [
    chip(c.waiting, c.waiting === 1 ? "application waiting" : "applications waiting", "Applications"),
    chip(c.claimsToday, "claims today", "Applications"),
    chip(c.bizWaiting, c.bizWaiting === 1 ? "business waiting on activation" : "businesses waiting on activation", "Markets"),
  ];
  if (c.partnersPaused) chips.push(chip(c.partnersPaused, c.partnersPaused === 1 ? "partner paused" : "partners paused", "Partners"));
  return chips.join("");
}

// Build -213: while a Sig surface is showing the summary's
// fallback numbers (or the bare preparing panel), it re-checks
// for the stored summary so the surface upgrades itself when
// the background compute lands. Capped per host; a real
// summary paint clears the counter.
const sigUpgrade213 = {};
function scheduleSigUpgrade213(hid) {
  const n = (sigUpgrade213[hid] || 0) + 1;
  if (n > 12) return;
  sigUpgrade213[hid] = n;
  setTimeout(() => { if (document.getElementById(hid)) loadAdminSig(hid); }, 5000);
}
async function loadAdminSig(hostId) {
  const hid = hostId || "admin-sig";
  const host = document.getElementById(hid);
  // Build -218: Review no longer carries the #admin-sig panel
  // (it is a queue view now), but its summary strip still comes
  // from this loader. Summary-only mode: fill #admin-summary
  // from the same payload and skip every panel write.
  const summaryOnly218 = !host && !!document.getElementById("admin-summary");
  if (!host && !summaryOnly218) return;
  // Build -212: the attention list reads the same precomputed
  // summary Admin Home reads (one fetch), not three aggregate
  // computes.
  const summary = await loadAdminHomeSummary212();
  if (summaryOnly218 ? !document.getElementById("admin-summary") : !document.getElementById(hid)) return;
  if (summary && summary.preparing && !summary.fallback) {
    if (summaryOnly218) {
      pingAdminHomeRefresh212();
      setTimeout(() => { if (document.getElementById("admin-summary") && !document.getElementById(hid)) loadAdminSig(hostId); }, 4000);
      return;
    }
    host.innerHTML = `<div class="panel"><p class="small muted" style="margin:0">Maggie is preparing the Admin numbers. They will be ready in a moment.</p></div>`;
    pingAdminHomeRefresh212();
    scheduleSigUpgrade213(hid);
    return;
  }
  // Build -213: a preparing answer WITH the fallback numbers
  // paints the attention list from the records on file (the
  // summary chips stay unpainted — their market/partner counts
  // are not in the fallback, and a zero there would read as a
  // fact), flagged as provisional, and the surface re-checks
  // until the stored summary lands.
  const isFallback213 = !!(summary && summary.fallback);
  if (isFallback213) {
    pingAdminHomeRefresh212();
    if (!summaryOnly218) scheduleSigUpgrade213(hid);
  } else if (summary) {
    delete sigUpgrade213[hid];
  }
  const { apps, marketsData, partnersData } = summary ? homeSummaryAdapters212(summary) : { apps: null, marketsData: null, partnersData: null };
  const items = adminSigItems(apps, marketsData, partnersData);
  const sumEl = document.getElementById("admin-summary");
  if (sumEl && !isFallback213) sumEl.innerHTML = adminSummaryHtml121(adminSummaryCounts121(apps, marketsData, partnersData));
  if (summaryOnly218) return;
  const loaded = apps || marketsData || partnersData;
  host.innerHTML = `
  <div class="panel admin-sig-panel">
    <div class="admin-sig-head">
      <span class="admin-sig-media">${sigHeroMediaHtml()}</span>
      <div>
        <div class="flex-between"><strong>Maggie</strong><span class="badge info">Attention list</span></div>
        <p class="small muted" style="margin:4px 0 0">Plain sentences, real counts, from the same records Admin shows. Maggie points; your taps decide.</p>
      </div>
    </div>
    ${items.length ? items.map((it) => `
    <div class="admin-sig-item">
      <span class="admin-sig-dot" aria-hidden="true"></span>
      <p class="small" style="margin:0;flex:1">${esc(it.text)}</p>
      <button class="btn small-btn ghost" onclick="return go('dashboard','${it.tab}')">${esc(it.btn)}</button>
    </div>`).join("") : `<p class="small" style="margin:10px 0 0">${loaded ? "Nothing needs a decision right now. Approvals, claims, activations, and partners are all caught up." : "Maggie could not load the Admin numbers just now. The tabs below carry the same records."}</p>`}
    ${isFallback213 ? `<p class="small muted" style="margin:8px 0 0">Maggie is still preparing the full Admin numbers — this list covers the latest records on file.</p>` : (loaded && (!apps || !marketsData || !partnersData) ? `<p class="small muted" style="margin:8px 0 0">Some Admin numbers could not load; this list covers what answered.</p>` : "")}
  </div>`;
  sigHeroSet("idle");
}

// Sig in Admin, the destination (Jeff, 2026-10-28): the rail
// rail destination lands here. Same chat machinery
// as the business and creator Sig tab (one thread, sigAskSubmit,
// POST /sig/ask with the admin counts as grounding), with the
// Admin attention list as the starting brief on top. READ-ONLY
// by contract: Sig answers, explains, and points; the attention
// buttons and the destination rows navigate, and Jeff's taps on
// those screens remain the only writes. The operator never runs
// here (sigOpTry already refuses non-business/creator roles).
// ================= Build -138 Admin rooms =================
// Automations & connections, Marketing, Social, Team, Templates,
// Learn. Each room reads its own endpoint; the server enforces
// every permission again at the data layer, so a control a role
// cannot use is simply not rendered for them.
const a138 = { autoEntry: null, tplRef: null, teamMember: null, learnDraft: null, mkCampaign: null };
function a138Err(el, e) { if (el) el.innerHTML = `<div class="error-box">${esc(e.message || String(e))}</div>`; }
function a138When(iso) { if (!iso) return "never"; try { return new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }); } catch (e) { return String(iso); } }

// ---- Automations & connections ----
async function loadAdminAutomations138() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = `<p class="muted">Loading…</p>`;
  try {
    const [auto, conn] = await Promise.all([api("GET", "/admin/automations"), api("GET", "/admin/connections")]);
    const srcTag = (r) => r.source === "live" ? `<span class="a138-tag live">Live check</span>` : r.source === "record" ? `<span class="a138-tag">Record</span>` : `<span class="a138-tag note">Note · ${esc(r.asOf || "")}</span>`;
    const connHtml = (conn.rows || []).map((r) => `<div class="a138-conn">
      <div class="a138-conn-main"><strong>${esc(r.name)}</strong><span class="small muted">${esc(r.doesPlain)}</span>
      <span class="a138-conn-state">${esc(r.state)}</span>${r.note ? `<span class="small muted">Note (${esc(r.note.asOf || "")}): ${esc(r.note.text)}</span>` : ""}</div>
      <div class="a138-conn-side">${srcTag(r)}${conn.canManage ? `<button type="button" class="btn small-btn ghost" onclick="return a138ConnNote('${r.id}')">Note</button>` : ""}</div>
    </div>`).join("");
    const stateChip = (e) => e.state === "always_on" ? `<span class="a138-tag">Always on</span>` : e.state === "recipient" ? `<span class="a138-tag">On — follows their own settings</span>` : e.state === "off" ? `<span class="a138-tag off">Off</span>` : `<span class="a138-tag live">On</span>`;
    const groupsHtml = (auto.groups || []).map((g) => `<h3 class="a138-h">${esc(g.name)}</h3>${g.entries.map((e) => `<div class="a138-row">
      <div class="a138-row-main"><strong>${esc(e.name)}</strong><span class="small muted">${esc(e.trigger)} → ${esc(e.recipient)}</span>
      ${e.envNote ? `<span class="small muted">${esc(e.envNote)}</span>` : ""}${e.overridden ? `<span class="small muted">Wording edited in Templates</span>` : ""}</div>
      <div class="a138-row-side">${stateChip(e)}
      ${e.state === "on" || e.state === "off" || e.state === "recipient" ? `<label class="tgl-row a138-tgl"><input type="checkbox" class="sw" ${e.state === "off" ? "" : "checked"} ${auto.canManage ? "" : "disabled"} onchange="return a138AutoToggle('${e.id}', this.checked)"><span>${e.state === "off" ? "Off" : "On"}</span></label>` : ""}
      <button type="button" class="btn small-btn ghost" onclick="return a138AutoOpen('${e.id}')">Open</button></div>
    </div>`).join("")}`).join("");
    el.innerHTML = `<h3>Automations & connections</h3>
    <p class="muted">Every email and text Magpie sends on its own, what sets it off, and its switch. The ones that keep people in their accounts — password reset, sign-in link, approval, account deletion — can never be turned off. Last checked ${a138When(auto.generatedAt)}.</p>
    <div class="panel"><h4 style="margin-top:0">Connections</h4>${connHtml}</div>
    <div id="a138-auto-detail"></div>
    ${groupsHtml}`;
    if (a138.autoEntry) a138AutoOpen(a138.autoEntry);
  } catch (e) { a138Err(el, e); }
}
async function a138ConnNote(id) {
  const text = prompt("Dated note for this connection (leave empty to clear):", "");
  if (text === null) return false;
  try { await api("POST", `/admin/connections/${id}/note`, { text }); showToast("Note saved"); loadAdminAutomations138(); }
  catch (e) { alert(e.message); }
  return false;
}
async function a138AutoToggle(id, on) {
  try { await api("POST", `/admin/automations/${id}/toggle`, { on }); showToast(on ? "Automation on" : "Automation off"); loadAdminAutomations138(); }
  catch (e) { alert(e.message); loadAdminAutomations138(); }
  return false;
}
async function a138AutoOpen(id) {
  a138.autoEntry = id;
  const box = document.getElementById("a138-auto-detail");
  if (!box) return false;
  box.innerHTML = `<div class="panel"><p class="muted">Loading…</p></div>`;
  try {
    const d = await api("GET", `/admin/automations/${id}`);
    const e = d.entry;
    const pv = d.preview || {};
    box.innerHTML = `<div class="panel a138-detail">
      <div class="a138-detail-head"><h4 style="margin:0">${esc(e.name)}</h4><button type="button" class="btn small-btn ghost" onclick="a138.autoEntry=null; document.getElementById('a138-auto-detail').innerHTML=''; return false;">Close</button></div>
      <p class="small muted" style="margin:6px 0">${esc(e.trigger)} → ${esc(e.recipient)} · ${e.lane === "rail" ? "Text + email (notification rail)" : "Email"}</p>
      ${d.lastSent ? `<p class="small">Last sent ${a138When(d.lastSent.at)}${d.lastSent.to ? ` to ${esc(d.lastSent.to)}` : ""}${d.lastSent.sandbox ? " (sandbox — recorded, not delivered)" : ""}</p>` : `<p class="small muted">No send recorded yet.</p>`}
      ${pv.note ? `<div class="a138-notebox">${esc(pv.note)}</div>` : `<div class="a138-preview"><div class="a138-pv-k">Subject</div><div class="a138-pv-sub">${esc(pv.subject || "")}</div><div class="a138-pv-k">Email</div><pre class="a138-pv-body">${esc(pv.text || "")}</pre>${pv.sms ? `<div class="a138-pv-k">Text</div><pre class="a138-pv-body">${esc(pv.sms)}</pre>` : ""}</div>`}
      ${d.overridden || pv.overridden ? `<p class="small muted">Showing the edited wording from Templates (v${pv.overrideVersion || (d.override && d.override.currentVersion) || ""}).</p>` : ""}
      <div class="a138-actions">
        ${d.canManage ? `<button type="button" class="btn small-btn" onclick="return a138AutoTest('${e.id}')">Send test to my inbox</button>` : ""}
        <button type="button" class="btn small-btn ghost" onclick="return a138TplOpen('${e.templateRef}')">Edit wording in Templates</button>
      </div>
    </div>`;
    box.scrollIntoView({ behavior: "smooth", block: "start" });
  } catch (e) { a138Err(box, e); }
  return false;
}
