// ---------- Admin: Requests (Build -53) ----------
// Everything that shared the old Applications destination and is
// not the application queue: a pointer to the Messages home
// (Build -163 moved the platform-message panel there — all
// correspondence lives in Messages now; the queue's Message
// buttons open the person's thread in that home), the Finish
// Engine panel, and the founding roster counts strip.
async function loadAdminRequests() {
  const el = document.getElementById("tab-body");
  try {
    const data = await api("GET", "/admin/applications");
    // The compose box targets creators from these rows; keep the
    // records by id so "Message" knows the creator's name and
    // market without another fetch (same map the queue builds).
    state.adminMsgUsers = {};
    for (const u of [...(data.pending || []), ...(data.decided || [])]) state.adminMsgUsers[u.id] = u;
    const s = data.summary;
    const summaryStrip = s ? `
      <h3>Founding roster counts</h3>
      <p class="muted small">Creators only, counted from the records. Approved is the launch number: a market opens at 50 approved. Approved + complete shows how many of them businesses can book today.</p>
      <div class="table-wrap ct199 panel"><table><tr><th>Market</th><th>Counts</th></tr>
      ${s.markets.map((m) => `<tr><td>${esc(m.label)}</td><td><strong>${m.pending}</strong> pending &middot; <strong>${m.approved}</strong> approved &middot; <strong>${m.approvedComplete}</strong> approved + complete</td></tr>`).join("")}
      <tr><td><strong>All markets</strong></td><td><strong>${s.all.pending}</strong> pending &middot; <strong>${s.all.approved}</strong> approved &middot; <strong>${s.all.approvedComplete}</strong> approved + complete</td></tr>
      </table></div>
      ${s.auto ? `<p class="muted small">Auto-decided under the standing rules: ${s.auto.approved} approved, ${s.auto.rejected} rejected all time; today ${s.auto.approvedToday} approved, ${s.auto.rejectedToday} rejected. Referred claims always wait for a person.</p>` : ""}` : "";
    const devPanels189 = ["localhost", "127.0.0.1"].includes(location.hostname) || window.__MAGPIE_DEV__ === true;
    el.innerHTML = `
      <h2 style="margin:0 0 4px">Requests</h2>
      <p class="muted small" style="margin:0 0 12px">The finishing room: approved creators whose profiles are not finished yet, the engine that nudges them done, and the founding roster counts. Conversations themselves live in Messages.</p>
      <div class="panel">
        <h3 style="margin-top:0">Creator messages</h3>
        <p class="muted small">All conversations moved to Messages — every thread, every reply and every send to many people lives there now, in one place.</p>
        <button type="button" class="btn" onclick="return go('dashboard','Messages')">Open Messages</button>
      </div>
      <div id="admin-finish-panel"></div>
      ${devPanels189 ? `<div id="admin-demo-showcase"></div><div id="admin-test-offers"></div>` : ""}
      ${summaryStrip}`;
    renderAdminFinishEngine();
    if (devPanels189) { loadDemoShowcasePanel(); loadTestOffersPanel(); }
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// Admin profile view (Jeff, 2026-10-26): "View profile" on an
// Applications card opens the applicant's full Magpie profile exactly
