// Tester designation (Jeff, 2026-10-19): an approved creator moved
// to Tester keeps signing in and using the creator side to test the
// app, but businesses never see them: discovery excludes them, their
// public profile page 404s, campaign sends skip their email, and
// roster / approved counts leave them out. Moving back to the
// roster restores all of it.
// Admin-side editor for a business's public review-page links
// (the founding application side of the field; businesses can also
// edit their own from the Plan tab). Host-validated server-side.
function toggleReviewLinks(userId) {
  const el = document.getElementById("rl-edit-" + userId);
  if (el) el.style.display = el.style.display === "none" ? "" : "none";
}

async function saveReviewLinks(userId) {
  try {
    await api("POST", "/admin/review-links", {
      userId,
      links: {
        google: document.getElementById("rl-google-" + userId).value,
        yelp: document.getElementById("rl-yelp-" + userId).value,
        tripadvisor: document.getElementById("rl-tripadvisor-" + userId).value,
        facebook: document.getElementById("rl-facebook-" + userId).value,
      },
    });
    showToast("Saved.");
    loadApplications();
  } catch (err) { alert(err.message); }
}

// Admin-side editor for a business's audience-code discount
// setting (the founding-application side of the field; the
// business can also set its own from the Plan tab). Discounts
// are opt-in; the server validates the percentage range.
function toggleDiscountEditor(userId) {
  const el = document.getElementById("disc-edit-" + userId);
  if (el) el.style.display = el.style.display === "none" ? "" : "none";
}

async function saveDiscountSetting(userId) {
  try {
    const pctRaw = document.getElementById("disc-pct-" + userId).value;
    await api("POST", "/admin/discount-setting", {
      userId,
      enabled: document.getElementById("disc-enabled-" + userId).checked,
      pct: pctRaw === "" ? undefined : Number(pctRaw),
    });
    showToast("Saved.");
    loadApplications();
  } catch (err) { alert(err.message); }
}

async function setTester(userId, tester, role) {
  const isBiz = role === "business";
  const msg = tester
    ? (isBiz
      ? "They keep full business access for testing, but campaign sends skip them and the tester count in Stats includes them. Their offers and visits keep working."
      : "They keep full creator access for testing, but businesses will not see them, their public profile page comes down, campaign sends skip them, and roster counts exclude them.")
    : (isBiz
      ? "The business leaves the tester set: campaign sends can reach them again and the Stats tester count drops."
      : "Businesses will see them in discovery again, their public profile page returns, and roster counts will include them.");
  const ok = await showConfirmSheet(tester ? `Move this ${isBiz ? "business" : "creator"} to Tester?` : `Move this ${isBiz ? "business" : "creator"} back to the roster?`, msg, tester ? "Move to Tester" : "Move to roster");
  if (!ok) return;
  try {
    await api("POST", "/admin/tester", { userId, tester });
    loadApplications();
  } catch (err) { alert(err.message); }
}

// Event Log search (Build -47, audit A3): the type filter was
// server-side already; the page gains a text search over the
// loaded rows (type, actor, market, and the data payload), and
// the Data cell truncates long payloads instead of running one
// row to thousands of characters. Full payload stays one tap
// away on the row's toggle.
let adminEventsCache = [];
let adminEventsQ = "";
// Build -206: Event Log human-readable labels. Curated labels for the
// common event codes; every other code falls back to a prettified form
// (snake_case words, first letter capped) so no raw code or raw type
// string is ever the only thing an admin sees. The raw code stays in
// the badge title for support lookups.
const EVENT_LABELS_206 = {
  user_signed_in: "Signed in", user_signed_up: "Signed up", signup_completed: "Signup completed",
  application_submitted: "Application submitted", application_approved: "Application approved",
  application_rejected: "Application rejected", application_held_under_minimum: "Application held (under minimum)",
  application_released: "Application released", application_selected: "Application selected",
  application_withdrawn: "Application withdrawn", account_banned: "Account banned",
  account_paused: "Account paused", account_paused_strikes: "Account paused (strikes)",
  account_unpaused: "Account unpaused", account_reinstated: "Account reinstated",
  account_removed: "Account removed", account_deleted: "Account deleted",
  account_side_added: "Account side added", account_side_switched: "Account side switched",
  admin_corrected_account_email: "Admin corrected account email",
  admin_sent_signin_link: "Admin sent sign-in link",
  admin_viewed_business_account: "Admin viewed a business account",
  admin_viewed_creator_account: "Admin viewed a creator account",
  admin_viewed_partner_account: "Admin viewed a partner account",
  audience_markets_updated: "Audience markets updated", audience_count_corrected: "Audience count corrected",
  audience_redemption: "Audience code redeemed", audience_code_taken: "Audience code taken",
  booking_created: "Booking created", booking_confirmed: "Booking confirmed",
  booking_completed: "Booking completed", booking_cancelled: "Booking cancelled",
  claim_hook_view: "Claim link viewed", claim_started: "Claim started", claim_completed: "Claim completed",
  offer_created: "Offer created", offer_updated: "Offer updated",
  post_submitted: "Post submitted", post_verified: "Post verified",
  message_sent: "Message sent", automation_toggled: "Automation toggled",
  automation_test_sent: "Automation test sent", suggestion_shown: "Suggestion shown",
  bdev_lead_added: "Biz Dev lead added", bdev_claim: "Biz Dev claim filed",
  bdev_claim_confirmed: "Biz Dev claim confirmed", bdev_seat_assigned: "Biz Dev seat assigned",
  bdev_escalation: "Biz Dev escalation", bdev_visit: "Biz Dev visit logged",
  bdev_market_state: "Biz Dev market state changed", bdev_activation_confirmed: "Biz Dev activation confirmed",
};
function eventTypeLabel206(t) {
  const raw = String(t || "");
  if (EVENT_LABELS_206[raw]) return EVENT_LABELS_206[raw];
  const pretty = raw.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  return pretty || "Event";
}
function adminEventRowHtml(e, i) {
  const raw = JSON.stringify(e.data || {});
  const long = raw.length > 240;
  return `<tr><td class="small" data-label="When">${fmtDate(e.ts)}</td><td><span class="badge info" title="${esc(e.type)}">${esc(eventTypeLabel206(e.type))}</span></td><td class="small">${esc(e.actorRole || "")}</td><td class="small">${esc(e.market || "")}</td><td class="small"><span id="ev-data-${i}">${esc(long ? raw.slice(0, 240) + "…" : raw)}</span>${long ? ` <button type="button" class="linklike" onclick="return adminEventToggleData(${i})">Show all</button>` : ""}</td></tr>`;
}
function adminEventToggleData(i) {
  const e = adminEventsCache[i];
  const host = document.getElementById("ev-data-" + i);
  if (e && host) host.textContent = JSON.stringify(e.data || {});
  return false;
}
function adminEventsRenderRows() {
  const host = document.getElementById("ev-rows");
  if (!host) return;
  const q = adminEventsQ.trim().toLowerCase();
  const shown = adminEventsCache.map((e, i) => ({ e, i })).filter(({ e }) => !q || `${e.type} ${e.actorRole || ""} ${e.market || ""} ${JSON.stringify(e.data || {})}`.toLowerCase().includes(q));
  const wrap203 = host.closest("[data-uxmore]");
  const open203 = !!(wrap203 && wrap203.classList.contains("ux-open"));
  host.innerHTML = shown.length ? shown.map(({ e, i }, xi203) => uxMark203(adminEventRowHtml(e, i), xi203 >= 12 && !open203)).join("") : `<tr><td colspan="5" class="small muted">No events match that search in the loaded page.</td></tr>`;
  const mb203 = document.getElementById("ev-morebtn");
  if (mb203) { mb203.innerHTML = shown.length > 12 ? uxMoreBtn(shown.length) : ""; const b203 = mb203.querySelector("button"); if (b203 && open203) b203.textContent = "Show less"; }
  const cnt = document.getElementById("ev-count");
  if (cnt) cnt.textContent = q ? `${shown.length} of ${adminEventsCache.length} loaded events match.` : "";
}
function adminEventsSetQ(v) { adminEventsQ = v || ""; adminEventsRenderRows(); return false; }
async function loadEvents() {
  const el = document.getElementById("tab-body");
  try {
    const type = document.getElementById("ev-type") ? document.getElementById("ev-type").value : "";
    const data = await api("GET", "/admin/events?limit=300" + (type ? "&type=" + encodeURIComponent(type) : ""));
    const types = [...new Set(data.events.map((e) => e.type))].sort();
    adminEventsCache = data.events || [];
    el.innerHTML = `
      <div class="filters">
        <div><label>Event type</label><select id="ev-type" onchange="loadEvents()"><option value="">All types</option>${types.map((t) => `<option ${t === type ? "selected" : ""}>${esc(t)}</option>`).join("")}</select></div>
        <div><label>Search</label><input id="ev-q" type="search" placeholder="Type, actor, market, or data" value="${esc(adminEventsQ)}" oninput="adminEventsSetQ(this.value)"></div>
      </div>
      ${data.degraded ? `<div class="error-box">The event log could not be loaded just now. Refresh in a moment; nothing here was changed.</div>` : ""}
      <p class="muted small">${data.total} events, newest first. Every state change in the product writes one of these. This is the dataset. <span id="ev-count"></span></p>
      <div class="table-wrap panel" data-uxmore><table>
        <tr><th>When</th><th>Type</th><th>Actor</th><th>Market</th><th>Data</th></tr>
        <tbody id="ev-rows"></tbody>
      </table><span id="ev-morebtn"></span></div>`;
    adminEventsRenderRows();
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// ---------- Admin Stats: sign-up board (Build -53) ----------
// The top of Stats (Jeff, 2026-10-30): totals in plain words,
// then one row per market — a two-segment bar (green creators,
// dark businesses) sized against the biggest market, the counts
// in words, and the state split under the row. Tapping a market
// opens the Applications tab filtered to that market. The
// Unlisted section lists the typed cities collecting outside
// every market — where the next Clarksville shows up first —
// and taps through to that city's queue. Data: the signupBoard
// aggregate on GET /admin/stats (admin-gated, computed from the
// records on every read; it rides no other payload). Everything
// Stats already carried stays below the board.
let adminBoardMarkets = [];
let adminBoardUnlistedRows = [];

function adminBoardGoMarket(i) {
  const m = adminBoardMarkets[i];
  if (!m) return false;
  adminAppFilter = { kind: "market", market: m.market, label: m.label || m.market };
  return go("dashboard", "Applications");
}
function adminBoardGoUnlisted(i) {
  const r = adminBoardUnlistedRows[i];
  if (!r) return false;
  adminAppFilter = { kind: "unlisted", city: r.city, place: r.place };
  return go("dashboard", "Applications");
}
function adminSignupBoardHtml(b) {
  if (!b) return "";
  adminBoardMarkets = b.markets || [];
  adminBoardUnlistedRows = b.unlisted || [];
  const t = b.totals || { users: 0, creators: 0, businesses: 0, awaitingCreators: 0, awaitingBusinesses: 0 };
  const max = Math.max(1, ...adminBoardMarkets.map((m) => m.total));
  const pct = (n) => Math.max(0, Math.min(100, (n / max) * 100)).toFixed(1);
  const splits = (c, isCreator) => `${c.awaitingReview} awaiting review &middot; ${c.approved} approved${isCreator ? ` &middot; ${c.profileFinished} profile finished` : ""}`;
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const marketRow = (m, i) => `
    <button type="button" class="sb-row" onclick="return adminBoardGoMarket(${i})">
      <span class="sb-head"><strong>${esc(m.label || m.market)}</strong><span class="sb-total">${m.total} signed up</span></span>
      <span class="sb-bar"><i class="sb-seg sb-creators" style="width:${pct(m.creators.signedUp)}%"></i><i class="sb-seg sb-biz" style="width:${pct(m.businesses.signedUp)}%"></i></span>
      <span class="sb-counts">${plural(m.creators.signedUp, "creator", "creators")} &middot; ${plural(m.businesses.signedUp, "business", "businesses")}</span>
      <span class="sb-splits">Creators: ${splits(m.creators, true)}<br>Businesses: ${splits(m.businesses, false)}</span>
    </button>`;
  const unlistedRow = (r, i) => `
    <button type="button" class="sb-row" onclick="return adminBoardGoUnlisted(${i})">
      <span class="sb-head"><strong>${esc(r.place)}</strong><span class="sb-total">${r.total} signed up</span></span>
      <span class="sb-counts">${plural(r.creators, "creator", "creators")} &middot; ${plural(r.businesses, "business", "businesses")}${r.awaitingReview ? ` &middot; ${r.awaitingReview} awaiting review` : ""}</span>
    </button>`;
  return `
  <div class="panel sb-board">
    <h3 style="margin:0 0 4px">Sign-ups by market</h3>
    <p class="muted small" style="margin:0 0 12px">Everyone who has signed up, and where. <span class="sb-dot sb-creators"></span> Creators &middot; <span class="sb-dot sb-biz"></span> Businesses. Bars are sized against the biggest market. Tap a market to review its applications.</p>
    <div class="stat-row">
      <div class="stat"><div class="num">${t.users}</div><div class="lbl">Signed up</div></div>
      <div class="stat"><div class="num">${t.creators}</div><div class="lbl">Creators (${t.awaitingCreators} awaiting review)</div></div>
      <div class="stat"><div class="num">${t.businesses}</div><div class="lbl">Businesses (${t.awaitingBusinesses} awaiting review)</div></div>
    </div>
    ${adminBoardMarkets.length ? adminBoardMarkets.map(marketRow).join("") : `<p class="muted">No market sign-ups yet.</p>`}
    ${adminBoardUnlistedRows.length ? `
    <h4 style="margin:16px 0 2px">Not in a market yet</h4>
    <p class="muted small" style="margin:0 0 4px">Sign-ups from cities outside every market, counted by the city they typed. Tap one to see those applications.</p>
    ${adminBoardUnlistedRows.map(unlistedRow).join("")}` : ""}
    ${(b.emptyMarkets || []).length ? `<p class="muted small" style="margin-top:12px">No sign-ups yet in: ${(b.emptyMarkets || []).map(esc).join(" &middot; ")}</p>` : ""}
  </div>`;
}


// ---------- Admin: Creators (Build -130, Part 9) ----------
// Every signed-up creator in one place: the roster the totals
// strip counts, with the local numbers beside each name. Data is
// the applications payload (pending + decided), tester accounts
// excluded. A row tap opens the creator's full profile exactly
// as a business sees it (adminViewCreator).
let adminCreators130Cache = [];
function adminCreators130RowsHtml(rows) {
  if (!rows.length) return `<p class="small muted" style="margin-top:10px">No creators match that.</p>`;
  return `<div data-uxmore><div class="table-wrap" style="margin-top:10px"><table>
    <tr><th>Creator</th><th>Market</th><th>Status</th><th>Followers</th><th>% local</th><th>Profile</th><th></th></tr>
    ${rows.map((u, ui203) => {
      const c = u.creator || {};
      const pct = typeof c.localAudiencePct === "number" ? c.localAudiencePct + "%" : "—";
      return `<tr${ui203 >= 12 ? ' class="ux-extra" hidden' : ""}>
        <td><strong>${esc(u.name || "")}</strong>${handleLabel(c.handle) ? `<div class="muted small">${esc(handleLabel(c.handle))}</div>` : ""}</td>
        <td data-label="Market">${esc(adminCanonMarket(u.market || ""))}</td>
        <td data-label="Status">${u.status === "approved" ? "Approved" : u.status === "pending" ? "Waiting on review" : esc(u.status || "")}</td>
        <td data-label="Followers">${astFull(astCreatorTotal(u))}</td>
        <td data-label="% local">${pct}</td>
        <td data-label="Profile">${u.status === "approved" && u.profileComplete ? "Complete" : "Not finished"}</td>
        <td><button type="button" class="btn small-btn ghost" onclick="adminViewCreator('${u.id}')">View</button>${u.status === "approved" ? ` <button type="button" class="btn small-btn ghost" onclick="return adminMessagePerson153('${u.id}')">Message</button>` : ""}</td>
      </tr>`;
    }).join("")}
  </table></div>${rows.length > 12 ? uxMoreBtn(rows.length) : ""}</div>`;
}
function adminCreators130Filter(q) {
  const host = document.getElementById("acr-list");
  if (!host) return;
  const needle = String(q || "").trim().toLowerCase();
  const rows = !needle ? adminCreators130Cache : adminCreators130Cache.filter((u) => {
    const c = u.creator || {};
    return String(u.name || "").toLowerCase().includes(needle)
      || String(c.handle || "").toLowerCase().includes(needle)
      || String(u.email || "").toLowerCase().includes(needle)
      || adminCanonMarket(u.market || "").toLowerCase().includes(needle);
  });
  host.innerHTML = adminCreators130RowsHtml(rows);
  return false;
}
async function loadAdminCreators130() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = skelHtml("Loading creators...", 3);
  try {
    const data = await api("GET", "/admin/applications");
    const rows = [...(data.pending || []), ...(data.decided || [])]
      .filter((u) => u.role === "creator" && u.status !== "rejected" && !u.tester)
      .sort((a, b) => astCreatorTotal(b) - astCreatorTotal(a));
    adminCreators130Cache = rows;
    const approved = rows.filter((u) => u.status === "approved").length;
    el.innerHTML = `
      ${wsHead("Creators", { sub: "Every creator on the platform, biggest audience first." })}
      <p class="small muted" style="margin:0 0 10px">${rows.length} signed up · ${approved} approved · ${rows.length - approved} waiting on review. Tester accounts are not listed.</p>
      <div class="field" style="max-width:420px"><label>Search this list</label><input type="search" placeholder="Name, @handle, email or market" oninput="adminCreators130Filter(this.value)"></div>
      <div id="acr-list">${adminCreators130RowsHtml(rows)}</div>
      <div class="panel" style="margin-top:14px"><h3 style="margin:0 0 8px">Your Line lookup</h3>
      <p class="small muted" style="margin:0 0 8px">Who brought whom under one creator, and the points their line earned.</p>
      <div class="row" style="gap:8px;align-items:center"><input id="line-pick" type="text" placeholder="Creator handle" style="max-width:240px"><button type="button" class="btn small-btn" onclick="adminLineLookup()">Look up</button></div>
      <div id="line-out" style="margin-top:8px"></div></div>`;
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// ---------- Admin: Deleted accounts (Build -219c) ----------
// The restore surface for soft-deleted accounts (Jeff's order,
// 2026-11-20: deletion is never a one-way door). Data is
// GET /admin/deleted-accounts — the one list where flagged
// records are supposed to show. Restore is one tap, no confirm
// word: restoring is the safe direction, and the server logs
// an account_restored event for every restore.
async function loadAdminDeleted219c() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = skelHtml("Loading deleted accounts...", 2);
  try {
    const data = await api("GET", "/admin/deleted-accounts");
    const rows = data.accounts || [];
    el.innerHTML = `
      ${wsHead("Deleted accounts", { sub: "Accounts that were deleted, kept so an admin can bring one back." })}
      ${rows.length ? `<div class="table-wrap" style="margin-top:10px"><table>
        <tr><th>Account</th><th>Email</th><th>Role</th><th>Market</th><th>Deleted</th><th></th></tr>
        ${rows.map((a) => `<tr>
          <td><strong>${esc(a.role === "business" && a.businessName ? a.businessName : a.name || "")}</strong>${a.handle ? `<div class="muted small">@${esc(a.handle)}</div>` : ""}</td>
          <td data-label="Email">${esc(a.email || "")}</td>
          <td data-label="Role">${esc(a.role || "")}</td>
          <td data-label="Market">${esc(a.market || "")}</td>
          <td data-label="Deleted">${a.deletedAt ? esc(String(a.deletedAt).slice(0, 10)) : ""}${a.deletedVia ? `<div class="muted small">via ${esc(a.deletedVia)}</div>` : ""}</td>
          <td><button type="button" class="btn small-btn" onclick="return adminRestoreAccount219c('${a.id}')">Restore</button> <span class="small" id="admin-restore-note-${a.id}"></span></td>
        </tr>`).join("")}
      </table></div>` : `<p class="small muted" style="margin-top:10px">No deleted accounts. When an account is deleted, it waits here until an admin restores it.</p>`}`;
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}
async function adminRestoreAccount219c(id) {
  const note = document.getElementById("admin-restore-note-" + id);
  try {
    await api("POST", `/admin/users/${id}/restore-account`, {});
    loadAdminDeleted219c();
  } catch (e) { if (note) note.textContent = e.message; }
  return false;
}

// ---------- Admin Stats + the books (Builds -54..-57, -130) ----------
// History: Build -54 made Stats a "Command Center" shell over
// GET /admin/command/* (-55 Money + Businesses, -56 partner
// deals, -57 Owed/Close). Build -130 (Part 9, Jeff's live Admin
// review) retired the shell: the numbers job moved to the Stats
// charts at the top of loadStats, the ledger views (Money ·
// Partners · Businesses · Owed · Close) kept their endpoints
// and renderers as "The books" under those charts, the forming
// placeholder views were deleted, Creators became its own tab,
// and Admin's Wallet was removed everywhere.
let ccTab = "money";
let ccFilters = { period: "all", market: "", testers: false, partner: "" };
let ccAttentionCache = [];
let ccPartnerId = null;
let ccPartnerOpts = null;
let ccCloseMonth = null;
let ccCloseSel = null;
let ccReconCache = [];

function ccQuery() {
  const q = new URLSearchParams();
  q.set("period", ccFilters.period);
  if (ccFilters.market) q.set("market", ccFilters.market);
  if (ccFilters.testers) q.set("testers", "1");
  if (ccFilters.partner) q.set("partner", ccFilters.partner);
  return q.toString();
}
function ccMoneyFmt(n) {
  return "$" + (Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}
// Build -103: currency-aware money. A GBP figure is printed
// with £ and never flows through the dollar formatter, so a
// blended number cannot be produced by accident.
function ccMoneyFmtC(n, currency) {
  if (currency === "GBP") return "£" + (Number(n) || 0).toLocaleString("en-GB", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  return ccMoneyFmt(n);
}
// Batch fix (Jeff, 2026-11-06): Stats opens on a five-way
// section switcher — Creators | Businesses | Website |
// Partners | Revenue — one focused view at a time, never the
// old one-long-page stack. The books tabs (Money · Partners ·
// Businesses · Owed · Close) live inside the three money-side
// views; the map below keeps the two switchers in sync in both
// directions, and the deep links that preset ccTab preset the
// view the same way.
const AST_BOOK_VIEWS = { money: "revenue", owed: "revenue", close: "revenue", partners: "partners", businesses: "businesses" };
function ccSetTab(tab) { ccTab = tab; astView = AST_BOOK_VIEWS[tab] || astView; if (tab !== "partners") ccPartnerId = null; loadStats(); return false; }
function astSetView(v) {
  astView = v;
  if (v === "businesses") ccTab = "businesses";
  else if (v === "partners") ccTab = "partners";
  else if (v === "revenue" && !["money", "owed", "close"].includes(ccTab)) ccTab = "money";
  loadStats();
  return false;
}
function ccSetPartnerFilter(v) { ccFilters.partner = v; ccPartnerId = null; loadStats(); return false; }
async function ccOpenPartner(id) { ccPartnerId = id; await ccShowTab(); return false; }
async function ccBackPartners() { ccPartnerId = null; await ccShowTab(); return false; }
function ccSetPeriod(v) { ccFilters.period = v; loadStats(); return false; }
function ccSetMarket(v) { ccFilters.market = v; loadStats(); return false; }
function ccSetTesters(on) { ccFilters.testers = !!on; loadStats(); return false; }

// ---------- Admin Stats (Build -130, Part 9) ----------
// The Stats tab is the platform's numbers page: charts at a
// glance, built with the same -119 stat components the creator
// and business dashboards use (stat-band cells, funnel2Html,
// sparkSvg119, the shared table styles). Every number derives
// from record-level payloads (the applications list carries each
// creator's audience + local shares; the books below keep their
// /admin/command/* feeds), so the filters slice everything on
// the page for real. The old Command Center shell is gone: its
// numbers job lives here, its books (Money · Partners ·
// Businesses · Owed · Close) keep their views under "The books",
// the London race and the register connections sit at the foot
// of this page, and Creators is its own Admin tab now. Admin has
// no Wallet: creator/business money pages are theirs alone.
let astFilters = { range: "all", market: "", status: "all" };
let astData = null;
let astView = "overview";

function astFull(n) { return (Number(n) || 0).toLocaleString("en-US"); }
function astCreatorTotal(u) {
  // Build -131 hotfix: the applications payload precomputes
  // the stacked total on the creator record (totalAudience,
  // and audience.total in the audience view). The first cut of
  // this reader looked for a ".stack" field the payload never
  // carries, so every multi-platform creator silently fell back
  // to their primary-platform followerCount and the Stats
  // Followers total undercounted the platform (and disagreed
  // with the Admin home strip, which reads the same records
  // through audienceTotalOf). Read the payload's own fields.
  const c = u.creator || {};
  if (typeof c.totalAudience === "number") return c.totalAudience;
  if (c.audience && typeof c.audience.total === "number") return c.audience.total;
  if (u.audience && typeof u.audience.total === "number") return u.audience.total;
  const st = c.audienceStack || c.stack || {};
  const sum = Object.values(st).reduce((a, v) => a + (Number(v) || 0), 0);
  return sum || Number(c.followerCount || 0) || 0;
}
function astCreatorListings(u) {
  // The markets a creator is listed in, with their % local to
  // each: the home market at their home %, plus every
  // audienceMarkets entry at its own share (the Part 2/3 basis).
  const c = u.creator || {};
  const home = adminCanonMarket(u.market || "");
  const out = [];
  if (home) out.push({ market: home, pct: typeof c.localAudiencePct === "number" ? c.localAudiencePct : null });
  for (const e of Array.isArray(c.audienceMarkets) ? c.audienceMarkets : []) {
    if (!e || !e.market || e.market === home) continue;
    out.push({ market: e.market, pct: typeof e.pct === "number" ? e.pct : null });
  }
  return out;
}
function astFilteredCreators() {
  const all = (astData && astData.creators) || [];
  const f = astFilters;
  return all.filter((u) => {
    if (f.status === "pending" && u.status !== "pending") return false;
    if (f.status === "approved" && u.status !== "approved") return false;
    if (f.status === "complete" && !(u.status === "approved" && u.profileComplete)) return false;
    if (f.market && adminCanonMarket(u.market || "") !== f.market) return false;
    if (f.range !== "all") {
      const t = new Date(u.createdAt || 0).getTime();
      if (!Number.isFinite(t)) return false;
      const now = new Date();
      if (f.range === "30d" && t < now.getTime() - 30 * 864e5) return false;
      if (f.range === "this_month" && (new Date(t).getMonth() !== now.getMonth() || new Date(t).getFullYear() !== now.getFullYear())) return false;
      if (f.range === "last_month") {
        const lm = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        if (new Date(t).getMonth() !== lm.getMonth() || new Date(t).getFullYear() !== lm.getFullYear()) return false;
      }
    }
    return true;
  });
}
function astSetFilter(kind, value) {
  astFilters[kind] = value;
  astRender();
  return false;
}
// The Revenue view's panel (batch fix, 2026-11-06): collected
// is the charge ledger's real net (nothing is invented; while
// payments are off it reads $0 and says so). Pipeline =
// businesses approved at the founding rates they signed up at,
// recorded on their records, not yet billed. Until the Stats
// section switcher landed, this panel rendered inside the
// creator charts stack; it is the Revenue view's headline now
// and renders from the same astData, unchanged.
function astRevenueHtml() {
  if (!astData) return "";
  const money = astData.money || {};
  const collected = (money.charged && money.charged.netTotal) || 0;
  const plans = (state.boot && state.boot.plans) || [];
  const planRate = (id) => { const p = plans.find((x) => x.id === id); return p ? Number(p.priceMonthly) || 0 : 0; };
  const planName = (id) => { const p = plans.find((x) => x.id === id); return p ? (p.name || id) : id; };
  const pipe = {};
  for (const b of astData.businesses) {
    if (b.status !== "approved") continue;
    const id = (b.business && b.business.plan) || "";
    // Build -151: "on a plan" means the plan id resolves to a
    // real plan in the book (the Command Center's definition) —
    // a stale or invented plan id counts nowhere.
    if (!id || !planRate(id)) continue;
    pipe[id] = (pipe[id] || 0) + 1;
  }
  const pipeRows = Object.entries(pipe).map(([id, n]) => ({ id, n, rate: planRate(id), total: n * planRate(id) })).sort((a, b) => b.total - a.total);
  const pipeTotal = pipeRows.reduce((a, r) => a + r.total, 0);
  const waitingBiz = astData.businesses.filter((b) => b.status === "pending").length;
  return `
    <div class="panel">
      <h3 style="margin:0 0 2px">Revenue</h3>
      <p class="muted small" style="margin:0 0 10px">Only what the records say. Nothing here is estimated.</p>
      <div class="stat-band">
        <div class="stat-cell"><div class="stat-num">${ccMoneyFmt(collected)}</div><div class="stat-lbl">Collected so far</div></div>
        <div class="stat-cell"><div class="stat-num">${ccMoneyFmt(pipeTotal)}/mo</div><div class="stat-lbl">Founding pipeline</div></div>
      </div>
      ${collected === 0 ? `<p class="small" style="margin:8px 0 0">Payments are turned off right now, so nothing has been charged or collected yet.</p>` : ""}
      ${pipeRows.length ? `<div class="table-wrap ct199" style="margin-top:10px"><table>
        <tr><th>Plan</th><th>Businesses</th><th>Rate</th><th>Recorded monthly</th></tr>
        ${pipeRows.map((r) => `<tr><td>${esc(planName(r.id))}</td><td data-label="Businesses">${r.n}</td><td data-label="Rate">${ccMoneyFmt(r.rate)}/mo</td><td data-label="Recorded monthly">${ccMoneyFmt(r.total)}/mo</td></tr>`).join("")}
      </table></div>
      <p class="small muted" style="margin:6px 0 0">Recorded, not yet billed: businesses approved at the founding rates they signed up at.${waitingBiz ? ` ${waitingBiz} more ${waitingBiz === 1 ? "business is" : "businesses are"} waiting on review.` : ""}</p>` : `<p class="small muted" style="margin:8px 0 0">No approved businesses yet, so the founding pipeline is empty.</p>`}
    </div>`;
}

function astRender() {
  const host = document.getElementById("ast-charts");
  if (!host || !astData) return;
  const creators = astFilteredCreators();
  const totals = creators.reduce((a, u) => {
    const total = astCreatorTotal(u);
    const pct = u.creator && typeof u.creator.localAudiencePct === "number" ? u.creator.localAudiencePct : null;
    a.followers += total;
    if (pct !== null) { a.pctSum += pct; a.pctN += 1; a.localFollowers += Math.round(total * pct / 100); }
    return a;
  }, { followers: 0, pctSum: 0, pctN: 0, localFollowers: 0 });
  const avg = totals.pctN ? Math.round(totals.pctSum / totals.pctN) : null;
  // Trend: signups per bucket over the filtered range (daily up
  // to ~62 days, weekly beyond), from the same creator records.
  const now = Date.now();
  const spanDays = astFilters.range === "30d" ? 30 : astFilters.range === "all" ? 84 : 31;
  const bucketMs = spanDays > 62 ? 7 * 864e5 : 864e5;
  const buckets = new Array(Math.ceil(spanDays / (bucketMs / 864e5))).fill(0);
  for (const u of creators) {
    const t = new Date(u.createdAt || 0).getTime();
    if (!Number.isFinite(t)) continue;
    const idx = Math.floor((t - (now - spanDays * 864e5)) / bucketMs);
    if (idx >= 0 && idx < buckets.length) buckets[idx] += 1;
  }
  // Build -202: Markets table renders from server rows built on adminMarketRows (no client reimplementation).
  const marketRows = ((astData && astData.marketRows202) || []).map((m) => [m.name, { creators: m.creatorsListed || 0, followers: m.combinedFollowers || 0, localFollowers: m.localFollowers || 0, pctSum: m.avgLocalPct != null && m.avgLocalCount ? m.avgLocalPct * m.avgLocalCount : 0, pctN: m.avgLocalCount || 0 }]).sort((a, b) => b[1].creators - a[1].creators);
  const funnel = funnel2Html([
    { label: "Signed up", n: creators.length, cap: "every creator in this view" },
    { label: "Approved", n: creators.filter((u) => u.status === "approved").length, cap: "through review" },
    { label: "Profile complete", n: creators.filter((u) => u.status === "approved" && u.profileComplete).length, cap: "ready to be booked" },
  ]);
  host.innerHTML = `
    <div class="stat-band">
      <div class="stat-cell"><div class="stat-num">${fmtNum(creators.length)}</div><div class="stat-lbl">Creators signed up</div></div>
      <div class="stat-cell"><div class="stat-num">${fmtNum(totals.followers)}</div><div class="stat-lbl">Followers</div></div>
      <div class="stat-cell"><div class="stat-num">${fmtNum(totals.localFollowers)}</div><div class="stat-lbl">Local followers</div></div>
      <div class="stat-cell"><div class="stat-num">${avg === null ? "—" : avg + "%"}</div><div class="stat-lbl">Avg % local</div></div>
    </div>
    <div class="panel">
      <h3 style="margin:0 0 2px">Signups over time</h3>
      <p class="muted small" style="margin:0 0 8px">New creators in this view, ${spanDays > 62 ? "per week" : "per day"}.</p>
      ${astChart189(buckets)}
      <p class="small" style="margin:6px 0 0"><strong>${fmtNum(buckets.reduce((a, b) => a + b, 0))}</strong> signups in the period shown</p>
    </div>
    <div class="panel">
      <h3 style="margin:0 0 2px">From signup to ready</h3>
      <p class="muted small" style="margin:0 0 8px">How far creators in this view have got.</p>
      ${funnel}
    </div>
    <div class="panel">
      <h3 style="margin:0 0 2px">Markets</h3>
      <p class="muted small" style="margin:0 0 8px">Creators listed in each market, with the share of their audience that lives there.</p>
      ${marketRows.length ? `<div class="table-wrap ct199"><table>
        <tr><th>Market</th><th>Creators</th><th>Followers</th><th>Local followers</th><th>Avg % local</th></tr>
        ${marketRows.map(([name, m]) => `<tr><td>${esc(name)}</td><td data-label="Creators">${astFull(m.creators)}</td><td data-label="Followers">${astFull(m.followers)}</td><td data-label="Local followers">${astFull(m.localFollowers)}</td><td data-label="Avg % local">${m.pctN ? Math.round(m.pctSum / m.pctN) + "%" : "—"}</td></tr>`).join("")}
      </table></div>` : `<p class="small muted">No creators match these filters yet.</p>`}
    </div>`;
  // The Revenue view's panel renders from the same data pass.
  const revHost = document.getElementById("ast-revenue");
  if (revHost) revHost.innerHTML = astRevenueHtml();
}

// ---------- Admin Stats: Overview (Build -244) ----------
