// ================= Biz Dev Dashboard (Build -155) =================
// The field-seller shell. A biz dev seat on the account
// (user.bizdevSeat) makes this the default shell; the account's
// own role surfaces stay reachable from the rep Menu. Everything
// here renders server payloads from /bdev/* — the server enforces
// market + book scoping; this layer only presents. Plain words
// throughout (the fresh-eyes rule): no insider terms on any rep
// screen. Show Mode is a locked, client-facing deck: the rep
// cannot edit a word of it.

const BD_TABS = ["BD Home", "BD Leads", "BD Contacts", "BD Orders", "BD Kit", "BD Money", "BD Menu"];
const BD_STATUSES = ["Not contacted", "Contacted", "Meeting set", "Follow up", "Declined", "Closed"];
// Build -157: true only while Jeff is looking at a rep's Show
// Mode through the admin preview — every mutating Show path
// checks this first (see bdShowClaim / bdPinVerify guards).
let BD_PREVIEW = false;
const bdPractice = {};
const bd = {
  tab: "BD Home", home: null, leads: null, filter: "all", q: "",
  city: "", neighborhood: "", facets: null, practiceItems: [],
  // Build -170 CRM: category/status find, the rolodex, orders.
  category: "", status: "",
  contacts: null, contactCities: [], contactQ: "", contactCity: "", contactAddOpen: false, contactEditId: null,
  orders: null, orderAddOpen: false,
  leadId: null, lead: null, logs: [],
  logDraft: null, show: null, kit: null, money: null,
  addOpen: false, nearNote: "",
  // Build -161: multi-market seats (Jeff's). mkt is the working
  // city; single-market seats never set it and nothing changes.
  // Build -188 (PL-07): the working market starts UNSET on a
  // fresh load — never seeded from a past session's stored
  // pick. The first /bdev call carries no ?mkt=, the server
  // answers with the seat's HOME market, and bdSyncSeat161
  // adopts it. Switching cities is an in-session act via the
  // chips (bdSetMkt); it no longer follows the rep home.
  mkt: "", 
  markets: [], hqSeat: false,
};

function bdShellActive() {
  const u = state.user;
  return !!(u && u.bizdevSeat && u.bizdevSeat.active && state.shell !== "creator" && state.view !== "staff");
}
// Build -227 (Jeff, 2026-11-21): which menu the menu button
// opens follows the shell the person is IN, not just the seat
// they hold. bdShellActive() stays true for an admin in every
// shell (it drives BD data and chrome), and the -219b routing
// keyed the menu on it alone — so Jeff, an admin holding the
// HQ seat, got the Sell drawer on every screen, including
// Admin Home, and the full admin menu never rendered for him.
// Now: an admin gets the rep drawer only in Sell mode (the
// shell he explicitly entered via bdGoShell); everywhere else
// his menu is the admin hamburger. A non-admin seat holder's
// home IS the rep shell, so their routing is unchanged.
function bdMenuDrawerApplies() {
  if (!bdShellActive()) return false;
  const u = state.user;
  if (u && u.role === "admin") return state.shell === "bizdev";
  return true;
}
// Build -188 (PL-05): the desync state — the account still
// carries an active seat stamp, but the server has no seat
// record for it, so every /bdev call answers "No biz dev seat
// on this account." Instead of seven dead tabs each printing
// that raw error, the shell collapses to one plain panel:
// what happened and the exact next step. Any BD loader that
// meets the error hands over to bdSeatGone.
function bdNoSeatPanelHtml() {
  return `<div class="panel" style="max-width:560px">
    <h3 style="margin-top:0">Your Biz Dev seat isn't active</h3>
    <p>Your account still shows a Biz Dev seat, but the seat itself is not on file, so your leads, kit and money can't load. Nothing you did caused this, and nothing is lost: your book comes back the moment the seat is restored.</p>
    <p><strong>Next step:</strong> seats are assigned by Jeff (HQ) from Admin, Biz Dev, Seats. Ask Jeff to re-assign your seat, then reload this page.</p>
    <p style="margin-bottom:0"><button type="button" class="btn" onclick="location.reload()">Reload</button></p>
  </div>`;
}
function bdSeatGone(e, el) {
  if (!e || !/No biz dev seat/.test(String(e.message || ""))) return false;
  state.bdNoSeat = true;
  try { renderNav(); } catch (err) { /* nav re-renders on next go() */ }
  if (el) el.innerHTML = bdNoSeatPanelHtml();
  return true;
}
function bdGoShell() { state.shell = "bizdev"; state.tab = "BD Home"; renderNav(); return go("dashboard", "BD Home"); }
function bdGoCreator() { state.shell = "creator"; state.tab = "Dashboard"; renderNav(); return go("dashboard", "Dashboard"); }

// Build -161: Jeff's Manage ⇄ Sell toggle + the city switcher.
// Sell is the rep shell itself (bdGoShell); Manage is his admin
// Biz Dev room. One tap each way, same login.
function bdGoSell161() { return bdGoShell(); }
function bdGoManage161() { state.shell = "admin"; state.tab = "Biz Dev"; renderNav(); return go("dashboard", "Biz Dev"); }
function bdIsAdminSeller161() { return !!(state.user && state.user.role === "admin" && bd.hqSeat); }
// Every rep API call routes through bdPath: when a working city
// is picked it rides along as ?mkt= and the server validates it
// against the seat's own markets. PIN calls never route through
// here (one PIN per person, every city), and neither does the
// public claim POST (the rep code on it carries attribution).
function bdPath(path) {
  if (!bd.mkt) return path;
  return path + (path.includes("?") ? "&" : "?") + "mkt=" + encodeURIComponent(bd.mkt);
}
function bdSyncSeat161(src) {
  if (!src) return;
  if (Array.isArray(src.markets) && src.markets.length) bd.markets = src.markets;
  if (src.hqSeat != null) bd.hqSeat = !!src.hqSeat;
  // Shared books (2026-11-12): remember my own rep code so the
  // work-claim badge can tell "you're working this one" from
  // "Tony / Jeff is working this one".
  if (src.repCode) bd.repCode = src.repCode;
  if (bd.mkt && bd.markets.length && !bd.markets.some((m) => m.marketId === bd.mkt)) bd.mkt = "";
  if (!bd.mkt && src.marketId) bd.mkt = src.marketId;
}
function bdMktName() {
  const m = (bd.markets || []).find((x) => x.marketId === bd.mkt);
  if (m) return m.marketName;
  return (bd.home && bd.home.rep && bd.home.rep.marketName) || "";
}
function bdSetMkt(marketId) {
  if (marketId === bd.mkt) return false;
  bd.mkt = marketId;
  try { localStorage.setItem("bd161:mkt", marketId); } catch (e) { /* private mode */ }
  bd.home = null; bd.leads = null; bd.leadId = null; bd.city = ""; bd.neighborhood = "";
  return go("dashboard", state.tab);
}
function bdCitySwitcherHtml() {
  if (!bd.markets || bd.markets.length < 2) return "";
  return `<div class="chip-row" style="margin:2px 0 10px">${bd.markets.map((m) => `<button type="button" class="chip ${bd.mkt === m.marketId ? "on" : ""}" onclick="return bdSetMkt('${m.marketId}')">${esc(m.marketName)}</button>`).join("")}</div>`;
}

function bdCacheSet(key, val) { try { localStorage.setItem("bd155:" + key, JSON.stringify({ at: Date.now(), val })); } catch (e) { /* storage full/blocked */ } }
function bdCacheGet(key) { try { const r = JSON.parse(localStorage.getItem("bd155:" + key) || "null"); return r ? r.val : null; } catch (e) { return null; } }
function bdOutbox() { try { return JSON.parse(localStorage.getItem("bd155:outbox") || "[]"); } catch (e) { return []; } }
function bdOutboxSet(list) { try { localStorage.setItem("bd155:outbox", JSON.stringify(list)); } catch (e) { /* ignore */ } }
async function bdFlushOutbox() {
  const box = bdOutbox();
  if (!box.length) return;
  const left = [];
  for (const item of box) {
    try { await api("POST", item.path, item.body); } catch (e) { left.push(item); }
  }
  bdOutboxSet(left);
}
function bdQueuePost(path, body) {
  const box = bdOutbox(); box.push({ path, body, at: Date.now() }); bdOutboxSet(box);
}

function renderBizdevDash() {
  let tab = state.tab || "BD Home";
  if (!BD_TABS.includes(tab) && tab !== "Account") tab = "BD Home";
  state.tab = tab; bd.tab = tab;
  app.innerHTML = `<div class="wrap bd-wrap"><div id="tab-body"><p class="muted">Loading...</p></div></div>`;
  bdFlushOutbox();
  const el = () => document.getElementById("tab-body");
  // Build -188 (PL-05): seat known gone — every BD tab is the
  // one plain panel; Account stays reachable.
  if (state.bdNoSeat && tab !== "Account") { el().innerHTML = bdNoSeatPanelHtml(); return; }
  if (tab === "Account") { el().innerHTML = accountViewHtml126("Biz Dev"); return; }
  if (tab === "BD Leads") return bdLoadLeads(el());
  if (tab === "BD Contacts") return bdLoadContacts(el());
  if (tab === "BD Orders") return bdLoadOrders(el());
  if (tab === "BD Kit") return bdLoadKit(el());
  if (tab === "BD Money") return bdLoadMoney(el());
  if (tab === "BD Menu") return bdRenderMenu(el());
  return bdLoadHome(el());
}

// ---------- shared bits ----------

function bdFlagBanners(l) {
  const out = [];
  if (l.flags.doNotContact) out.push(`<div class="bd-banner bd-banner-stop">Do not contact this business.</div>`);
  else if (l.flags.jeffHandles) out.push(`<div class="bd-banner bd-banner-stop">Jeff is handling this business personally. Don't visit, call, or message.</div>`);
  if (l.phoneVerify) out.push(`<div class="bd-banner bd-banner-warn">Two numbers on file for this business — check which is right before you use it.</div>`);
  if (l.flags.chain) out.push(`<div class="bd-banner bd-banner-warn">Part of a chain — the owner's okay may sit above this shop.</div>`);
  return out.join("");
}
function bdLocked(l) { return !!(l.flags.doNotContact || l.flags.jeffHandles); }
function bdStageBadge(stage) {
  const kind = stage === "Founding spot claimed" ? "ok" : stage === "Said no" || stage === "Not a fit" ? "" : "info";
  return `<span class="badge ${kind}">${esc(stage)}</span>`;
}
function bdStatusBadge(status) {
  if (!status) return "";
  const kind = status === "Closed" ? "ok" : status === "Declined" ? "bd-status-muted" : "";
  return `<span class="badge ${kind} bd-status-badge">${esc(status)}</span>`;
}
// Shared books (2026-11-12): the work-claim badge — BADGE, NOT
// HIDE. A claimed business stays on both men's lists; the badge
// just says whose hands it is in. nameOnly renders the factual
// form (Jeff's Manage view + the read-only preview, where "you"
// would point at the wrong person).
function bdWorkClaimBadge(l, opts) {
  const wc = l && l.workClaim;
  if (!wc || !wc.byRepCode) return "";
  const first = String(wc.byName || wc.byRepCode).trim().split(/\s+/)[0] || wc.byRepCode;
  if (!(opts && opts.nameOnly) && bd.repCode && wc.byRepCode === bd.repCode) {
    return `<span class="badge ok">You're working this one</span>`;
  }
  return `<span class="badge info">${esc(first)} is working this one</span>`;
}
async function bdWorkClaim() {
  if (!bd.leadId) return false;
  try {
    const d = await api("POST", bdPath(`/bdev/leads/${bd.leadId}/work-claim`), {});
    if (d.lead) bd.lead = Object.assign({}, bd.lead, d.lead);
    showToast("Claimed — Tony and Jeff both see you're working this one.");
    const el = document.getElementById("tab-body");
    if (el) bdRenderLead(el);
  } catch (e) { alert(e.message); }
  return false;
}
async function bdWorkRelease() {
  if (!bd.leadId) return false;
  try {
    const d = await api("POST", bdPath(`/bdev/leads/${bd.leadId}/work-release`), {});
    if (d.lead) bd.lead = Object.assign({}, bd.lead, d.lead);
    showToast("Released — this one is open for either of you.");
    const el = document.getElementById("tab-body");
    if (el) bdRenderLead(el);
  } catch (e) { alert(e.message); }
  return false;
}
function bdQueueBadge(label) {
  const kind = label === "Start here" ? "bd-qbadge-start" : label === "Next up" ? "bd-qbadge-next" : "bd-qbadge-later";
  return `<span class="badge ${kind}">${esc(label || "Later")}</span>`;
}
function bdQueueCard(item) {
  const l = item.lead || item;
  if (!l) return "";
  return `<div class="card bd-lead-card">
    ${bdFlagBanners(l)}
    <div class="bd-lead-top"><strong class="bd-lead-name">${esc(l.shortName || l.name)}</strong><span style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">${bdQueueBadge(item.label)}${l.status ? bdStatusBadge(l.status) : ""}${l.stage ? bdStageBadge(l.stage) : ""}${bdWorkClaimBadge(l)}</span></div>
    <div class="muted small">${esc(l.category || "")}${l.neighborhood ? ` · ${esc(l.neighborhood)}` : ""}</div>
    ${item.why ? `<p style="margin:8px 0 0">${esc(item.why)}</p>` : ""}
    ${bdNextLine(l)}
    <div class="bd-card-btns"><button type="button" class="btn" onclick="return bdOpenLead('${l.id}')">Open</button></div>
  </div>`;
}
async function bdShowTrips() {
  const slot = document.getElementById("bd-trips-slot");
  if (!slot) return false;
  slot.innerHTML = `<p class="muted small">Finding good clusters near you...</p>`;
  try {
    const d = await api("GET", bdPath("/bdev/trips"));
    const trips = d.trips || [];
    if (!trips.length) { slot.innerHTML = `<div class="panel"><p class="muted" style="margin:0">No clusters right now — your book is worked through. Add a lead or check back tomorrow.</p></div>`; return false; }
    slot.innerHTML = trips.map((t) => `
    <div class="panel" style="margin-top:10px">
      <strong>${esc(t.zone || "")}${t.city ? ` · ${esc(t.city)}` : ""}</strong>
      <p class="muted small" style="margin:4px 0 8px">${t.count} shop${t.count === 1 ? "" : "s"} · ${t.dueCount || 0} follow-ups due · ${t.warmCount || 0} warm intros</p>
      ${t.first ? `<p style="margin:0 0 8px">First stop: <strong>${esc(t.first.shortName || t.first.name)}</strong></p>` : ""}
      <div style="display:flex;gap:8px;flex-wrap:wrap">${(t.leads || []).map((l) => `<button type="button" class="btn ghost small-btn" onclick="return bdOpenLead('${l.id}')">${esc(l.shortName || l.name)}</button>`).join("")}</div>
    </div>`).join("");
  } catch (e) { slot.innerHTML = `<p class="muted small">${esc(e.message)}</p>`; }
  return false;
}
async function bdSetStatus(status) {
  if (!bd.leadId) return false;
  // Build -161: Declined and Closed end the conversation — a
  // stray thumb closed a lead in QA, so those two ask first and
  // name the business. Every other status stays one tap.
  if ((status === "Declined" || status === "Closed") && bd.lead) {
    const name = bd.lead.shortName || bd.lead.name || "this business";
    if (!window.confirm(`Mark ${name} as ${status}? You can change it later, but this takes them out of your working list.`)) return false;
  }
  try {
    const d = await api("POST", bdPath(`/bdev/leads/${bd.leadId}/status`), { status });
    if (d.lead) bd.lead = Object.assign({}, bd.lead, d.lead);
    showToast("Saved — where things stand is updated.");
    const el = document.getElementById("tab-body");
    if (el) bdRenderLead(el);
  } catch (e) { alert(e.message); }
  return false;
}
function bdCopyText(text, doneMsg) {
  const done = () => showToast(doneMsg || "Copied");
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text || "").then(done).catch(done);
  else done();
  return false;
}
function bdToggleCallMode() {
  const block = document.getElementById("bd-callblock");
  if (block) block.classList.toggle("bd-call-large");
  return false;
}
function bdNextLine(l) {
  if (!l.nextAction) return "";
  const na = l.nextAction;
  const when = na.date ? (l.nextLate ? `<span class="bd-late">${esc(l.nextLate)}</span>` : esc(na.date)) : "when you can";
  return `<div class="bd-next">${esc(na.type || "Visit")} · ${when}${na.what ? ` — ${esc(na.what)}` : ""}</div>`;
}
function bdMapsUrl(l) {
  const q = encodeURIComponent([l.name, l.address || "", l.city || ""].filter(Boolean).join(", "));
  return `https://www.google.com/maps/search/?api=1&query=${q}`;
}
// Build -170: the per-lead contact line — who to ask for, the
// email and the phone, read from the lead record's own contact
// fields (dmName / email / phone1 / phone2). Tappable on mobile.
// A lead with none of them gets the one quiet research line —
// never invented data.
function bdContactLine(l) {
  const bits = [];
  if (l.dmName) bits.push(`Ask for ${esc(l.dmName)}`);
  if (l.email) bits.push(`<a href="mailto:${esc(l.email)}">${esc(l.email)}</a>`);
  const ph = l.phone1 || l.phone2;
  if (ph) bits.push(`<a href="tel:${esc(String(ph).replace(/[^0-9+]/g, ""))}">${esc(ph)}</a>`);
  if (!bits.length) return `<div class="muted small" style="margin-top:4px">Contact info being researched.</div>`;
  return `<div class="small" style="margin-top:4px">${bits.join(" · ")}</div>`;
}
function bdLeadCard(l, opts) {
  const o = opts || {};
  return `<div class="card bd-lead-card" ${o.big ? 'style="padding:18px"' : ""}>
    ${bdFlagBanners(l)}
    <div class="bd-lead-top"><strong class="bd-lead-name">${esc(l.shortName || l.name)}</strong><span style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">${bdStatusBadge(l.status)}${bdStageBadge(l.stage)}${bdWorkClaimBadge(l)}</span></div>
    <div class="muted small">${esc(l.category)}${l.subType ? ` · ${esc(l.subType)}` : ""} · ${esc(l.neighborhood || "")}</div>
    ${bdContactLine(l)}
    ${l.pendingApproval ? `<div class="bd-pending">Waiting for Jeff to check — you can work it now; it counts once he approves it.</div>` : ""}
    ${bdNextLine(l)}
    <div class="bd-card-btns">
      ${o.big ? `<a class="btn" href="${bdMapsUrl(l)}" target="_blank" rel="noopener">Go</a><button type="button" class="btn" onclick="return bdCheckin('${l.id}')">I'm Here</button>` : ""}
      <button type="button" class="btn ${o.big ? "ghost" : ""}" onclick="return bdOpenLead('${l.id}')">Open</button>
    </div>
  </div>`;
}

// ---------- Home ----------

async function bdLoadHome(el) {
  el = el || document.getElementById("tab-body");
  if (!el) return;
  let d = null, offline = false;
  try { d = await api("GET", bdPath("/bdev/home")); bd.home = d; bdSyncSeat161(d.rep); bdCacheSet("home", d); }
  catch (e) { if (bdSeatGone(e, el)) return; d = bdCacheGet("home"); offline = true; if (!d) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; return; } }
  const p = d.progress;
  const pct = Math.min(100, Math.round((p.creators / p.gateLow) * 100));
  const buckets = Object.entries(p.byBucket).map(([name, b]) => `<div class="bd-bucket"><span>${esc(name)}</span><strong>${b.count}</strong><span class="muted small">${esc(b.word)}</span></div>`).join("");
  const stops = d.plan.stops || [];
  const nextUp = stops[0];
  const restStops = stops.slice(1);
  // Build -189 (PL-47): one door, one list. A lead already on
  // today's route does not repeat in the next-best-doors queue.
  const stopIds189 = new Set(stops.map((l) => l && l.id).filter(Boolean));
  const queue189 = (d.queue || []).filter((item) => { const l = item.lead || item; return !(l && stopIds189.has(l.id)); });
  const dayLine = stops.length ? `${d.plan.doneCount} of ${d.plan.totalCount} done today` : "No visits planned today";
  el.innerHTML = `
  <div class="bd-toprow"><strong>${esc(d.rep.marketName)}</strong><span class="muted">${esc(d.rep.firstName)} · ${esc(d.date)}</span></div>
  <p class="small muted" style="margin:2px 0 8px">Viewing: ${esc(d.rep.marketName)} · Your seat: ${esc(d.rep.repCode || "")}${d.rep.hqSeat ? " (HQ)" : ""}</p>
  ${bdCitySwitcherHtml()}
  ${bdIsAdminSeller161() ? `<p class="small" style="margin:0 0 10px">You're selling as HQ-JEFF. <button type="button" class="linklike" onclick="return bdGoManage161()">Back to Manage</button></p>` : ""}
  ${offline ? `<p class="bd-offline">You're seeing a saved copy — no signal right now. Anything you log saves on this phone and sends itself later.</p>` : ""}
  <section class="sigtop130 panel">
    <div class="sigbox130">
      <div class="sigbox-head">${sigOrbMedia130(true)}<div class="sigbox-htext"><strong>Maggie</strong><span>Your morning brief</span></div></div>
      <div class="bd-brief">${d.brief.map((line) => `<p>${esc(line)}</p>`).join("")}</div>
      <form class="sigbox-form" onsubmit="return bdCoachSend(event)">
        <input id="bd-coach-input" type="text" placeholder="Objection? Ask Maggie" autocomplete="off" aria-label="Ask Maggie about an objection">
        <button type="submit" class="btn sigbox-go">Ask</button>
      </form>
      <div class="sigbox-thread" id="bd-coach-thread" hidden></div>
    </div>
  </section>
  ${bdOutbox().length ? `<div class="bd-banner bd-banner-warn">${bdOutbox().length} saved item${bdOutbox().length === 1 ? "" : "s"} on this phone waiting for signal.</div>` : ""}
  <section class="panel">
    <h3 style="margin-top:0">${esc(d.rep.marketName)} founding progress</h3>
    <p class="bd-gate-big">Creators: ${p.creators} of ${p.gateLow} approved needed to open ${esc(d.rep.marketName)}${p.creators < p.gateLow ? ` — ${p.gateLow - p.creators} to go` : " — the launch number is in"}</p>
    <div class="bd-progress"><span style="width:${pct}%"></span></div>
    <div class="bd-buckets">${buckets}</div>
    <p style="margin:10px 0 2px">Businesses on the founding list: <strong>${p.foundingClaimed}</strong></p>
    <p class="muted small" style="margin:0">We open when the founding creator roster is full.</p>
  </section>
  ${(d.unfinished || []).length ? `<section class="panel"><h3 style="margin-top:0">Finish today's logs</h3><p class="muted small" style="margin:0 0 8px">${d.unfinished.length} visit${d.unfinished.length === 1 ? "" : "s"} started but not logged. They stay here until they're done.</p>${d.unfinished.map((u) => `<button type="button" class="btn ghost small-btn" style="margin:0 6px 6px 0" onclick="return bdOpenLead('${u.leadId}')">Finish the log</button>`).join("")}<p class="small" style="margin:8px 0 0">Today so far: ${d.numbers.visitsThisWeek} visits this week · ${d.numbers.claimedThisMonth} founding spots claimed this month.</p></section>` : ""}
  <section>
    <h3 class="bd-h">Today's visits</h3>
    <p class="bd-dayline">${esc(dayLine)}${d.plan.zoneLabel ? ` · ${esc(d.plan.zoneLabel)}` : ""}</p>
    <div class="bd-progress"><span style="width:${stops.length ? Math.round((d.plan.doneCount / Math.max(1, d.plan.totalCount)) * 100) : 0}%"></span></div>
    ${nextUp ? bdLeadCard(nextUp, { big: true }) : `<div class="panel"><p class="muted" style="margin:0">No visits planned. Pick a neighborhood below or see new leads.</p></div>`}
    ${restStops.map((l) => bdLeadCard(l)).join("")}
    ${(d.plan.clusters || []).length ? `<p class="muted small">Neighborhoods with unvisited shops: ${d.plan.clusters.map((c) => `${esc(c.zone)} (${c.count})`).join(" · ")}</p>` : ""}
  </section>
  ${(d.followUps || []).length ? `<section><h3 class="bd-h">Follow-ups due <span class="badge info">${d.followUps.length}</span></h3>${d.followUps.map((l) => bdLeadCard(l)).join("")}</section>` : ""}
  ${(d.plan.onHold || []).length ? `<section><h3 class="bd-h">On hold <span class="badge info">${d.plan.onHold.length}</span></h3><p class="muted small" style="margin:0 0 8px">These leads are on a category hold. They stay off your route and out of your counts until Jeff clears the hold.</p>${d.plan.onHold.map((l) => bdLeadCard(l)).join("")}</section>` : ""}
  ${(d.alarms && d.alarms.length) ? `<section class="panel bd-alarm-panel"><h3 style="margin-top:0">Maggie noticed</h3><p class="muted small" style="margin:0 0 8px">A few doors are still waiting on you. No rush — here's what Maggie spotted.</p>${d.alarms.map((a) => `<div class="bd-logrow"><strong>${esc(a.name)}</strong><br><span>${esc(a.line || "")}</span> <button type="button" class="btn ghost small-btn" style="margin-left:6px" onclick="return bdOpenLead('${a.leadId}')">Open</button></div>`).join("")}</section>` : ""}
  ${queue189.length ? `<section><h3 class="bd-h">Your next best doors</h3>${queue189.map((item) => bdQueueCard(item)).join("")}<button type="button" class="btn ghost" onclick="return bdShowTrips()">I've got some time — where should I go?</button><div id="bd-trips-slot"></div></section>` : `<div id="bd-trips-slot"></div>`}
  ${d.scoreboard ? `<section class="panel"><h3 style="margin-top:0">Your last week, in one look</h3>${(d.scoreboard.lines || []).map((line) => `<p style="margin:6px 0">${esc(line)}</p>`).join("")}<p class="muted small" style="margin:8px 0 0">Week of ${esc(d.scoreboard.weekOf || "")}</p></section>` : ""}
  ${(d.newLeads || []).length ? `<section><h3 class="bd-h">New leads for you</h3>${d.newLeads.map((l) => bdLeadCard(l)).join("")}</section>` : ""}
  <section class="panel">
    <h3 style="margin-top:0">My numbers</h3>
    <div class="bd-numbers">
      <div><strong>${d.numbers.claimedThisMonth}</strong><span>Founding spots claimed (this month)</span></div>
      <div><strong>${d.numbers.visitsThisWeek}</strong><span>Visits this week</span></div>
      <div><strong>$${Number(d.numbers.moneyBuilding || 0).toLocaleString()}</strong><span>Money building up so far</span></div>
    </div>
    <button type="button" class="btn ghost" onclick="return go('dashboard','BD Money')">See My Money</button>
  </section>`;
}

async function bdCoachSend(ev) {
  ev.preventDefault();
  const input = document.getElementById("bd-coach-input");
  const thread = document.getElementById("bd-coach-thread");
  const q = (input.value || "").trim();
  if (!q) return false;
  thread.hidden = false;
  thread.innerHTML = `<div class="bd-coach-q">${esc(q)}</div><p class="muted small">Maggie is checking the Seller Kit...</p>`;
  try {
    const d = await api("POST", bdPath("/bdev/maggie/coach"), { q });
    thread.innerHTML = `<div class="bd-coach-q">${esc(q)}</div><div class="bd-coach-a"><strong>${esc(d.title || "From the Seller Kit")}</strong><p>${esc(d.answer || "")}</p></div>`;
    input.value = "";
  } catch (e) { thread.innerHTML = `<div class="bd-coach-q">${esc(q)}</div><p class="muted small">${esc(e.message)}</p>`; }
  return false;
}

async function bdCheckin(id) {
  try {
    await api("POST", bdPath(`/bdev/leads/${id}/checkin`), {});
    showToast("You're checked in. The log will be waiting when you walk out.");
  } catch (e) {
    bdQueuePost(bdPath(`/bdev/leads/${id}/checkin`), {});
    showToast("Saved on this phone — it will send when you have signal.");
  }
  return false;
}

// ---------- Leads ----------

const BD_FILTERS = [["all", "All"], ["due", "Due today"], ["notvisited", "Not visited yet"], ["thinking", "Thinking it over"], ["claimed", "Founding spot claimed"], ["near", "Near me"], ["checked", "Checked by Jeff"]];
async function bdLoadLeads(el) {
  el = el || document.getElementById("tab-body");
  if (!el) return;
  bd.leadId = null;
  let d = null;
  const cityQ = bd.city ? `&city=${encodeURIComponent(bd.city)}` : "";
  const nbQ = bd.neighborhood ? `&neighborhood=${encodeURIComponent(bd.neighborhood)}` : "";
  const catQ = bd.category ? `&category=${encodeURIComponent(bd.category)}` : "";
  const statusQ = bd.status ? `&status=${encodeURIComponent(bd.status)}` : "";
  try { d = await api("GET", bdPath(`/bdev/leads?filter=${encodeURIComponent(bd.filter === "near" ? "all" : bd.filter)}&q=${encodeURIComponent(bd.q)}${cityQ}${nbQ}${catQ}${statusQ}`)); bdCacheSet("leads", d); bdSyncSeat161(d.seat); }
  catch (e) { if (bdSeatGone(e, el)) return; d = bdCacheGet("leads"); if (!d) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; return; } }
  if (d.facets) bd.facets = d.facets;
  const facets = d.facets || bd.facets || { cities: [], neighborhoods: [] };
  const nbOptions = (facets.neighborhoods || []).filter((n) => !bd.city || n.city === bd.city);
  let leads = d.leads || [];
  el.innerHTML = `
  <h2>My Leads</h2>
  ${bdCitySwitcherHtml()}
  <p class="muted small" style="margin:4px 0 10px">Your ${esc(bdMktName() || "Hampton Roads")} book. Work it top to bottom — the next thing to do is always at the top.</p>
  <div class="bd-searchrow">
    <input id="bd-q" type="search" placeholder="Find a business in my book" value="${esc(bd.q)}" oninput="bdSearchInput(this.value)">
    <button type="button" class="btn" onclick="return bdToggleAdd()">Add a Lead</button>
  </div>
  <div class="bd-searchrow">
    <select id="bd-city" onchange="bdSetCity(this.value)" aria-label="City"><option value="">All cities</option>${(facets.cities || []).map((c) => `<option value="${esc(c)}" ${bd.city === c ? "selected" : ""}>${esc(c)}</option>`).join("")}</select>
    <select id="bd-neighborhood" onchange="bdSetNeighborhood(this.value)" aria-label="Neighborhood"><option value="">All neighborhoods</option>${nbOptions.map((n) => `<option value="${esc(n.name)}" ${bd.neighborhood === n.name ? "selected" : ""}>${esc(n.name)}</option>`).join("")}</select>
  </div>
  <div class="bd-searchrow">
    <select id="bd-category" onchange="bdSetCategory(this.value)" aria-label="Category"><option value="">All categories</option>${(facets.categories || []).map((c) => `<option value="${esc(c)}" ${bd.category === c ? "selected" : ""}>${esc(c)}</option>`).join("")}</select>
    <select id="bd-status" onchange="bdSetStatusFilter(this.value)" aria-label="Status"><option value="">Any status</option>${(facets.statuses || BD_STATUSES).map((st) => `<option value="${esc(st)}" ${bd.status === st ? "selected" : ""}>${esc(st)}</option>`).join("")}</select>
  </div>
  <div class="chip-row">${BD_FILTERS.map(([k, label]) => `<button type="button" class="chip ${bd.filter === k ? "on" : ""}" onclick="return bdSetFilter('${k}')">${esc(label)}</button>`).join("")}</div>
  ${bd.nearNote ? `<p class="muted small">${esc(bd.nearNote)}</p>` : ""}
  <div id="bd-add-slot">${bd.addOpen ? bdAddFormHtml() : ""}</div>
  <div id="bd-lead-list">${leads.length ? leads.map((l) => bdLeadCard(l)).join("") : `<div class="panel"><p class="muted" style="margin:0">Nothing in this view. Pick another filter, or add a lead you walked past.</p></div>`}</div>`;
}
let bdSearchTimer = null;
function bdSetCity(v) { bd.city = v || ""; bd.neighborhood = ""; bdLoadLeads(); return false; }
function bdSetCategory(v) { bd.category = v || ""; bdLoadLeads(); return false; }
function bdSetStatusFilter(v) { bd.status = v || ""; bdLoadLeads(); return false; }
function bdSetNeighborhood(v) { bd.neighborhood = v || ""; bdLoadLeads(); return false; }
function bdSearchInput(v) { bd.q = v; clearTimeout(bdSearchTimer); bdSearchTimer = setTimeout(() => bdLoadLeads(), 350); return false; }
function bdSetFilter(k) {
  bd.filter = k;
  if (k === "near") {
    bd.nearNote = "Near me: your neighborhoods in drive order, starting where you last checked in. (Magpie doesn't track your location in the background — ever.)";
  } else bd.nearNote = "";
  bdLoadLeads();
  return false;
}
function bdToggleAdd() { bd.addOpen = !bd.addOpen; const s = document.getElementById("bd-add-slot"); if (s) s.innerHTML = bd.addOpen ? bdAddFormHtml() : ""; return false; }
function bdAddFormHtml() {
  const cats = ["Restaurants & Dining", "Bars & Nightlife", "Health & Aesthetics", "Beauty & Grooming", "Experiences & Attractions", "Retail & Boutiques"];
  return `<div class="panel">
    <h3 style="margin-top:0">Add a lead</h3>
    <p class="muted small">You can work it right away. It counts once Jeff checks it — usually within a business day.</p>
    <div class="field"><label>Business name</label><input id="bd-add-name" placeholder="The shop's name"></div>
    <div class="field"><label>Kind of business</label><select id="bd-add-cat">${cats.map((c) => `<option>${esc(c)}</option>`).join("")}</select></div>
    <div class="field"><label>City</label><input id="bd-add-city" placeholder="e.g. Virginia Beach"></div>
    <div class="field"><label>Neighborhood</label><input id="bd-add-nb" placeholder="e.g. Ghent Norfolk"></div>
    <div class="field"><label>Address (if you have it)</label><input id="bd-add-addr" placeholder="Street address"></div>
    <div class="field"><label>Who to ask for (if you know)</label><input id="bd-add-cname" placeholder="The owner or manager's name"></div>
    <div class="field"><label>Email (if you have it)</label><input id="bd-add-email" placeholder="hello@theirshop.com"></div>
    <div class="field"><label>Phone (if you have it)</label><input id="bd-add-phone" placeholder="(757) 555-0100"></div>
    <div class="field"><label>Instagram (if you have it)</label><input id="bd-add-ig" placeholder="@theirshop"></div>
    <div class="field"><label>Notes</label><input id="bd-add-notes" placeholder="Anything Jeff should know"></div>
    <button type="button" class="btn" onclick="return bdAddSubmit()">Add to my book</button>
    <span id="bd-add-msg" class="small muted" style="margin-left:8px"></span>
  </div>`;
}
async function bdAddSubmit() {
  const msg = document.getElementById("bd-add-msg");
  const val = (id) => { const n = document.getElementById(id); return n ? n.value.trim() : ""; };
  const body = {
    name: val("bd-add-name"),
    category: document.getElementById("bd-add-cat").value,
    city: val("bd-add-city"),
    neighborhood: val("bd-add-nb"),
    address: val("bd-add-addr"),
    contactName: val("bd-add-cname"),
    email: val("bd-add-email"),
    phone: val("bd-add-phone"),
    instagram: val("bd-add-ig"),
    notes: val("bd-add-notes"),
  };
  try {
    const d = await api("POST", bdPath("/bdev/leads"), body);
    if (d.duplicate) { msg.textContent = d.message; return false; }
    bd.addOpen = false;
    showToast("Added. It's in your book — Jeff checks it before it counts.");
    bdLoadLeads();
  } catch (e) { msg.textContent = e.message; }
  return false;
}


// ---------- Contacts (the rolodex) + Orders — Build -170 CRM ----------

function bdContactCard(c, opts) {
  const o = opts || {};
  const bits = [];
  if (c.email) bits.push(`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`);
  if (c.phone) bits.push(`<a href="tel:${esc(String(c.phone).replace(/[^0-9+]/g, ""))}">${esc(c.phone)}</a>`);
  return `<div class="card bd-lead-card">
    <div class="bd-lead-top"><strong class="bd-lead-name">${esc(c.name || c.business || "No name")}</strong><span class="badge">${c.kind === "second" ? "Second contact" : c.kind === "business" ? "Business" : c.source === "lead" ? "From a lead" : "Added"}</span></div>
    <div class="muted small">${esc(c.business || "")}${c.role ? ` · ${esc(c.role)}` : ""}${c.city ? ` · ${esc(c.city)}` : ""}${c.neighborhood ? ` · ${esc(c.neighborhood)}` : ""}${o.ownerTag && c.ownerName ? ` · ${esc(c.ownerName)}'s book` : ""}</div>
    ${bits.length ? `<div class="small" style="margin-top:4px">${bits.join(" · ")}</div>` : `<div class="muted small" style="margin-top:4px">Contact info being researched.</div>`}
    ${c.notes ? `<p class="small" style="margin:6px 0 0">${esc(c.notes)}</p>` : ""}
    ${!o.ro ? `<div class="bd-card-btns">
      ${c.source === "lead" && c.leadId ? `<button type="button" class="btn ghost" onclick="return bdOpenLead('${c.leadId}')">Open the lead</button>` : ""}
      ${c.source === "added" ? `<button type="button" class="btn ghost" onclick="return bdContactEdit('${c.id}')">Edit</button>` : ""}
    </div>` : ""}
  </div>`;
}
function bdContactFormHtml(c) {
  const v = c || {};
  return `<div class="panel">
    <h3 style="margin-top:0">${c ? "Edit contact" : "Add a contact"}</h3>
    <div class="field"><label>Name</label><input id="bd-ct-name" value="${esc(v.name || "")}" placeholder="Who you talk to"></div>
    <div class="field"><label>Business</label><input id="bd-ct-business" value="${esc(v.business || "")}" placeholder="Their shop's name"></div>
    <div class="field"><label>Role</label><input id="bd-ct-role" value="${esc(v.role || "")}" placeholder="Owner, manager, chef..."></div>
    <div class="field"><label>Email</label><input id="bd-ct-email" value="${esc(v.email || "")}" placeholder="hello@theirshop.com"></div>
    <div class="field"><label>Phone</label><input id="bd-ct-phone" value="${esc(v.phone || "")}" placeholder="(757) 555-0100"></div>
    <div class="field"><label>City</label><input id="bd-ct-fcity" value="${esc(v.city || "")}" placeholder="e.g. Virginia Beach"></div>
    <div class="field"><label>Notes</label><input id="bd-ct-notes" value="${esc(v.notes || "")}" placeholder="Anything worth remembering"></div>
    <button type="button" class="btn" onclick="return bdContactSubmit('${c ? c.id : ""}')">${c ? "Save" : "Add to my rolodex"}</button>
    <button type="button" class="btn ghost" onclick="return bdContactCancel()">Cancel</button>
    <span id="bd-ct-msg" class="small muted" style="margin-left:8px"></span>
  </div>`;
}
async function bdLoadContacts(el) {
  el = el || document.getElementById("tab-body");
  if (!el) return;
  try {
    const qs = new URLSearchParams();
    if (bd.contactQ) qs.set("q", bd.contactQ);
    if (bd.contactCity) qs.set("city", bd.contactCity);
    const d = await api("GET", bdPath(`/bdev/contacts?${qs.toString()}`));
    bd.contacts = d.contacts || []; bd.contactCities = d.cities || []; bd.contactSummary = d.summary || null;
  } catch (e) { if (bdSeatGone(e, el)) return; el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; return; }
  bdRenderContacts(el);
}
function bdRenderContacts(el) {
  const list = bd.contacts || [];
  const editing = bd.contactEditId ? list.find((c) => c.id === bd.contactEditId && c.source === "added") : null;
  el.innerHTML = `
  <h2>Contacts</h2>
  <p class="muted small" style="margin:4px 0 10px">Your rolodex — everyone you talk to, in one place. Contacts from your leads show up on their own; add anyone else by hand.</p>
  ${bd.contactSummary ? `<p class="small" style="margin:0 0 10px"><strong>${bd.contactSummary.businesses} businesses</strong> · ${bd.contactSummary.people + bd.contactSummary.secondContacts} people (${bd.contactSummary.people} main contacts + ${bd.contactSummary.secondContacts} second contacts) · ${bd.contactSummary.businessContacts} business contacts${bd.contactSummary.added ? ` · ${bd.contactSummary.added} added by hand` : ""}</p>` : ""}
  <div class="bd-searchrow">
    <input id="bd-ct-q" type="search" placeholder="Find a person or business" value="${esc(bd.contactQ)}" oninput="bdContactSearch(this.value)">
    <button type="button" class="btn" onclick="return bdContactToggleAdd()">Add a contact</button>
  </div>
  <div class="bd-searchrow">
    <select id="bd-ct-city" onchange="bdContactSetCity(this.value)" aria-label="City"><option value="">All cities</option>${(bd.contactCities || []).map((c) => `<option value="${esc(c)}" ${bd.contactCity === c ? "selected" : ""}>${esc(c)}</option>`).join("")}</select>
  </div>
  <div id="bd-ct-form">${editing ? bdContactFormHtml(editing) : (bd.contactAddOpen ? bdContactFormHtml(null) : "")}</div>
  <div id="bd-ct-list">${list.length ? list.map((c) => bdContactCard(c)).join("") : `<div class="panel"><p class="muted" style="margin:0">No contacts match. Add the people you meet and they'll live here.</p></div>`}</div>`;
}
let bdContactTimer = null;
function bdContactSearch(v) { bd.contactQ = v; clearTimeout(bdContactTimer); bdContactTimer = setTimeout(() => bdLoadContacts(), 350); return false; }
function bdContactSetCity(v) { bd.contactCity = v || ""; bdLoadContacts(); return false; }
function bdContactToggleAdd() { bd.contactAddOpen = !bd.contactAddOpen; bd.contactEditId = null; bdRenderContacts(document.getElementById("tab-body")); return false; }
function bdContactEdit(id) { bd.contactEditId = id; bd.contactAddOpen = false; bdRenderContacts(document.getElementById("tab-body")); return false; }
function bdContactCancel() { bd.contactAddOpen = false; bd.contactEditId = null; bdRenderContacts(document.getElementById("tab-body")); return false; }
async function bdContactSubmit(id) {
  const msg = document.getElementById("bd-ct-msg");
  const val = (x) => { const n = document.getElementById(x); return n ? n.value.trim() : ""; };
  const body = { name: val("bd-ct-name"), business: val("bd-ct-business"), role: val("bd-ct-role"), email: val("bd-ct-email"), phone: val("bd-ct-phone"), city: val("bd-ct-fcity"), notes: val("bd-ct-notes") };
  try {
    if (id) await api("POST", bdPath(`/bdev/contacts/${id}`), body);
    else await api("POST", bdPath("/bdev/contacts"), body);
    bd.contactAddOpen = false; bd.contactEditId = null;
    showToast(id ? "Contact saved." : "Added to your rolodex.");
    bdLoadContacts();
  } catch (e) { if (msg) msg.textContent = e.message; }
  return false;
}

function bdOrderPlanLabel(plan) {
  return plan ? `Founding plan — $${plan}/mo` : "Plan not set yet";
}
function bdOrderCard(o, opts) {
  const ow = opts && opts.ownerTag && o.ownerName ? ` · ${esc(o.ownerName)}'s book` : "";
  return `<div class="card bd-lead-card">
    <div class="bd-lead-top"><strong class="bd-lead-name">${esc(o.businessName || "")}</strong><span class="badge ok">${esc(bdOrderPlanLabel(o.plan))}</span></div>
    <div class="muted small">${esc(o.date || "")}${ow}</div>
    ${o.notes ? `<p class="small" style="margin:6px 0 0">${esc(o.notes)}</p>` : ""}
  </div>`;
}
async function bdLoadOrders(el) {
  el = el || document.getElementById("tab-body");
  if (!el) return;
  try { const d = await api("GET", bdPath("/bdev/orders")); bd.orders = d.orders || []; }
  catch (e) { if (bdSeatGone(e, el)) return; el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; return; }
  bdRenderOrders(el);
}
function bdRenderOrders(el) {
  const list = bd.orders || [];
  el.innerHTML = `
  <h2>Orders</h2>
  <p class="muted small" style="margin:4px 0 10px">Orders you've taken, in your own book. This is your record — the money Jeff's system counts lives under My Money.</p>
  <div class="bd-searchrow"><button type="button" class="btn" onclick="return bdOrderToggleAdd()">Record an order</button></div>
  <div id="bd-order-form">${bd.orderAddOpen ? bdOrderFormHtml() : ""}</div>
  <div id="bd-order-list">${list.length ? list.map((o) => bdOrderCard(o)).join("") : `<div class="panel"><p class="muted" style="margin:0">No orders recorded yet. When a business says yes, write it down here.</p></div>`}</div>`;
}
function bdOrderFormHtml() {
  const today = new Date().toISOString().slice(0, 10);
  return `<div class="panel">
    <h3 style="margin-top:0">Record an order</h3>
    <div class="field"><label>Business name</label><input id="bd-ord-biz" placeholder="The shop's name"></div>
    <div class="field"><label>Plan</label><select id="bd-ord-plan"><option value="">Not sure yet</option><option value="199">Founding — $199/mo</option><option value="349">Founding — $349/mo</option><option value="699">Founding — $699/mo</option></select></div>
    <div class="field"><label>Date</label><input id="bd-ord-date" type="date" value="${today}"></div>
    <div class="field"><label>Notes</label><input id="bd-ord-notes" placeholder="Anything worth remembering"></div>
    <button type="button" class="btn" onclick="return bdOrderSubmit()">Save the order</button>
    <button type="button" class="btn ghost" onclick="return bdOrderToggleAdd()">Cancel</button>
    <span id="bd-ord-msg" class="small muted" style="margin-left:8px"></span>
  </div>`;
}
function bdOrderToggleAdd() { bd.orderAddOpen = !bd.orderAddOpen; bdRenderOrders(document.getElementById("tab-body")); return false; }
async function bdOrderSubmit() {
  const msg = document.getElementById("bd-ord-msg");
  const val = (x) => { const n = document.getElementById(x); return n ? n.value.trim() : ""; };
  const body = { businessName: val("bd-ord-biz"), plan: val("bd-ord-plan"), date: val("bd-ord-date"), notes: val("bd-ord-notes") };
  try {
    await api("POST", bdPath("/bdev/orders"), body);
    bd.orderAddOpen = false;
    showToast("Order recorded.");
    bdLoadOrders();
  } catch (e) { if (msg) msg.textContent = e.message; }
  return false;
}

// ---------- Lead detail + logging ----------

async function bdOpenLead(id) {
  bd.leadId = id;
  const el = document.getElementById("tab-body");
  if (!el) return false;
  el.innerHTML = `<p class="muted">Loading...</p>`;
  try {
    const d = await api("GET", bdPath(`/bdev/leads/${id}`));
    bd.lead = d.lead; bd.logs = d.logs || [];
    bdRenderLead(el);
  } catch (e) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; }
  return false;
}

function bdMailtoHref(email, mail) {
  if (!email || !mail) return "";
  return `mailto:${email}?subject=${encodeURIComponent(mail.subject || "")}&body=${encodeURIComponent(mail.body || "")}`;
}
function bdCopyDmOpener() {
  const t = bd.lead && bd.lead.playbook ? bd.lead.playbook.dmOpener : "";
  return bdCopyText(t || "", "Copied");
}
function bdPlaybookHtml(l) {
  const p = l.playbook;
  if (!p) return "";
  const phone = p.phone || {};
  const emailNote = !l.email ? `<p class="muted small">No email on file — this one's a visit or a call.</p>` : "";
  const emailCard = (title, mail) => mail ? `<div class="card bd-kit-card"><strong>${esc(title)}</strong><p style="margin:8px 0 4px"><strong>${esc(mail.subject || "")}</strong></p><pre class="bd-email-body">${esc(mail.body || "")}</pre>${l.email ? `<a class="btn ghost small-btn" href="${esc(bdMailtoHref(l.email, mail))}">Send with your mail app</a>` : ""}</div>` : "";
  return `<div class="panel bd-playbook">
    <h3 style="margin-top:0">Your playbook for this visit</h3>
    ${p.beforeYouGo ? `<h4 class="bd-h" style="margin-top:10px">Before you go</h4><p style="white-space:pre-wrap;line-height:1.55;margin:6px 0">${esc(p.beforeYouGo)}</p>` : ""}
    ${p.opener ? `<h4 class="bd-h" style="margin-top:14px">When you walk in, say</h4><p class="bd-opener">${esc(p.opener)}</p>${p.preVisitLine ? `<p class="muted"><strong>If you called first:</strong> ${esc(p.preVisitLine)}</p>` : ""}` : (p.preVisitLine ? `<p class="muted"><strong>If you called first:</strong> ${esc(p.preVisitLine)}</p>` : "")}
    <h4 class="bd-h" style="margin-top:14px">If you call first</h4>
    <div id="bd-callblock" class="bd-callblock">
      <div class="card bd-kit-card"><strong>You get the owner</strong><p class="bd-callscript">${esc(phone.owner || "")}</p></div>
      <div class="card bd-kit-card"><strong>You get staff</strong><p class="bd-callscript">${esc(phone.staff || "")}</p></div>
      <div class="card bd-kit-card"><strong>It goes to voicemail</strong><p class="bd-callscript">${esc(phone.voicemail || "")}</p></div>
    </div>
    <button type="button" class="btn ghost small-btn" onclick="return bdToggleCallMode()">Call mode — make the words bigger</button>
    ${emailNote}
    ${emailCard("Intro email", p.introEmail)}
    ${emailCard("Follow-up email", p.followupEmail)}
    ${p.dmOpener ? `<div class="card bd-kit-card"><strong>Instagram opener</strong><p style="white-space:pre-wrap;line-height:1.55">${esc(p.dmOpener)}</p><button type="button" class="btn ghost small-btn" onclick="return bdCopyDmOpener()">Copy</button></div>` : ""}
    ${(p.runsheet && p.runsheet.length) ? `<h4 class="bd-h" style="margin-top:14px">At the counter — the run-sheet</h4><ol class="bd-runsheet">${p.runsheet.map((s) => `<li><strong>${esc(s.screen || "")}</strong>${s.show ? ` — ${esc(s.show)}` : ""}${s.say ? `<br><em>“${esc(s.say)}”</em>` : ""}</li>`).join("")}</ol>` : ""}
  </div>`;
}
function bdRenderLead(el) {
  const l = bd.lead;
  if (!l) return;
  const locked = bdLocked(l);
  // Shared books (2026-11-12): the work-claim control — claim an
  // unclaimed business, release your own, or see whose it is.
  const wc = l.workClaim || null;
  const wcMine = !!(wc && bd.repCode && wc.byRepCode === bd.repCode);
  const wcFirst = wc ? (String(wc.byName || wc.byRepCode).trim().split(/\s+/)[0] || wc.byRepCode) : "";
  const wcButton = !wc
    ? `<button type="button" class="btn ghost" onclick="return bdWorkClaim()">Claim this business</button>`
    : wcMine
      ? `<button type="button" class="btn ghost" onclick="return bdWorkRelease()">Release my claim</button>`
      : `<button type="button" class="btn ghost" disabled>${esc(wcFirst)} is working this one</button>`;
  const routes = [];
  if (l.phone1) routes.push(`<a class="btn ghost small-btn" href="tel:${esc(l.phone1.replace(/[^0-9+]/g, ""))}">Call ${esc(l.phone1)}</a>`);
  if (l.phone2) routes.push(`<a class="btn ghost small-btn" href="tel:${esc(l.phone2.replace(/[^0-9+]/g, ""))}">Call ${esc(l.phone2)}</a>`);
  if (l.instagram) routes.push(`<a class="btn ghost small-btn" href="https://instagram.com/${esc(l.instagram)}" target="_blank" rel="noopener">Instagram @${esc(l.instagram)}</a>`);
  if (l.email) routes.push(`<a class="btn ghost small-btn" href="mailto:${esc(l.email)}">Email</a>`);
  if (!routes.length) routes.push(`<span class="muted small">No contact route on file — visit in person.</span>`);
  el.innerHTML = `
  <button type="button" class="linklike" onclick="return go('dashboard','BD Leads')">← My Leads</button>
  <div class="card" style="margin-top:8px">
    ${bdFlagBanners(l)}
    <div class="bd-lead-top"><strong class="bd-lead-name">${esc(l.name)}</strong><span style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">${bdStatusBadge(l.status)}${bdStageBadge(l.stage)}${bdWorkClaimBadge(l)}</span></div>
    <p class="muted" style="margin:4px 0">${esc(l.category)}${l.subType ? ` · ${esc(l.subType)}` : ""} · ${esc(l.neighborhood || "")}${l.address ? `<br>${esc(l.address)}` : ""}</p>
    ${l.pendingApproval ? `<div class="bd-pending">Waiting for Jeff to check — you can work it now; it counts once he approves it.</div>` : ""}
    ${l.championName ? `<p class="small">Introduced by Champion — ${esc(l.championName)}</p>` : ""}
    <p style="margin:8px 0"><strong>Who runs it:</strong> ${l.dmName ? `${esc(l.dmName)}${l.dmRoleLabel ? ` — ${esc(l.dmRoleLabel)}` : ""}` : "Owner — name not on file, ask on your first visit"}${l.secondContact ? `<br><span class="muted small">Also: ${esc(l.secondContact.name)} — ${esc(l.secondContact.roleLabel || "")}</span>` : ""}${l.usuallyHere ? `<br><span class="muted small">Usually here: ${esc(l.usuallyHere)}</span>` : ""}</p>
    ${bdContactLine(l)}
    <div id="bd-oneliner" class="bd-oneliner"><span class="muted small">Maggie's one-liner is loading...</span></div>
    ${bdPlaybookHtml(l)}
    <div class="bd-routes">${routes.join("")}</div>
    ${l.flags.noEmail && !l.email ? `<p class="muted small">No email on file — visit or phone only.</p>` : ""}
    <p style="margin:10px 0 4px"><strong>Founding spot:</strong> ${l.founding.status === "Confirmed" ? "Claimed — confirmed ✓" : l.founding.status === "Claimed" ? "Claimed — waiting for HQ to confirm" : "Not claimed yet"}${l.founding.planInterest ? ` · They're thinking about the $${l.founding.planInterest} plan` : ""}</p>
    <div style="margin:10px 0"><p style="margin:0 0 6px"><strong>Where things stand</strong></p><div class="chip-row">${BD_STATUSES.map((s) => `<button type="button" class="chip ${l.status === s ? "on" : ""}" onclick="return bdSetStatus('${esc(s)}')">${esc(s)}</button>`).join("")}</div></div>
    ${bdNextLine(l)}
    <div class="bd-actions">
      <a class="btn" href="${bdMapsUrl(l)}" target="_blank" rel="noopener">Go</a>
      <button type="button" class="btn" ${locked ? "disabled" : ""} onclick="return bdCheckin('${l.id}')">I'm Here</button>
      <button type="button" class="btn" ${locked ? "disabled" : ""} onclick="return bdStartLog()">Log this visit</button>
      <button type="button" class="btn ghost" ${locked ? "disabled" : ""} onclick="return bdShowEnter('${l.id}')">Show</button>
      <button type="button" class="btn ghost" ${locked ? "disabled" : ""} onclick="return bdPriceEnter('${l.id}')">Asked about price — show plans</button>
      <button type="button" class="btn ghost" onclick="return bdSendClaim('${l.id}')">Send them their claim link</button>
      ${wcButton}
      <button type="button" class="btn ghost" onclick="return bdEscalateOpen()">Ask Jeff</button>
    </div>
    <div id="bd-lead-slot"></div>
  </div>
  <div class="panel">
    <h3 style="margin-top:0">What's happened here</h3>
    ${(l.statusHistory && l.statusHistory.length) ? [...l.statusHistory].reverse().map((h) => `<div class="bd-logrow"><span class="muted small">${esc(String(h.at || "").slice(0, 10))}</span> Status set to ${esc(h.status || "")}${h.by && !/^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(h.by) ? ` <span class="muted small">· ${esc(h.by)}</span>` : ""}</div>`).join("") : ""}
    ${(bd.logs || []).length ? [...bd.logs].reverse().map((v) => `<div class="bd-logrow"><span class="muted small">${esc(String(v.visitAt || v.createdAt || "").slice(0, 10))}</span> ${v.type === "price_shown" ? "Price was shown" : v.type === "show_session" ? `Show Mode was used (${v.pages || 0} screens)` : `<strong>${esc(v.outcome || "")}</strong>${v.spokeName ? ` — talked to ${esc(v.spokeName)}` : ""}${v.objections && v.objections.length ? `<br><span class="muted small">Pushed back on: ${esc(v.objections.join(", "))}</span>` : ""}`}</div>`).join("") : ((l.statusHistory && l.statusHistory.length) ? "" : `<p class="muted" style="margin:0">Nothing yet. The first visit starts the story.</p>`)}
  </div>`;
  api("GET", bdPath(`/bdev/leads/${l.id}/oneliner`)).then((d) => {
    const s = document.getElementById("bd-oneliner");
    if (s && d.text) s.innerHTML = `<strong>Maggie:</strong> ${esc(d.text)}`;
  }).catch(() => { const s = document.getElementById("bd-oneliner"); if (s) s.innerHTML = ""; });
}

async function bdSendClaim(id) {
  try {
    const d = await api("POST", bdPath(`/bdev/leads/${id}/send-claim`), {});
    const slot = document.getElementById("bd-lead-slot");
    if (slot) slot.innerHTML = `<div class="bd-pending" style="margin-top:10px">${esc(d.message)}<br><strong>${esc(d.claimUrl)}</strong></div>`;
  } catch (e) { alert(e.message); }
  return false;
}
function bdEscalateOpen() {
  const slot = document.getElementById("bd-lead-slot");
  if (!slot) return false;
  const reasons = ["Wants a discount or free months", "Partner, sponsorship, or media talk", "Chain or multi-location deal", "Wants to invest", "Complaint about Magpie", "Press", "Other"];
  slot.innerHTML = `<div class="panel" style="margin-top:10px">
    <h3 style="margin-top:0">Ask Jeff</h3>
    <p class="muted small">Say this out loud while you send it: <em>“That's above what I can say yes to — and I won't guess at it. That's Jeff's call, he's the founder. I'll put it to him today and come back to you with his actual answer, not my version of it.”</em></p>
    <div class="field"><label>What's it about?</label><select id="bd-esc-reason">${reasons.map((r) => `<option>${esc(r)}</option>`).join("")}</select></div>
    <div class="field"><label>Anything Jeff should know (optional)</label><textarea id="bd-esc-note" rows="2"></textarea></div>
    <button type="button" class="btn" onclick="return bdEscalateSend()">Send it to Jeff</button>
  </div>`;
  return false;
}
async function bdEscalateSend() {
  try {
    await api("POST", bdPath(`/bdev/leads/${bd.leadId}/escalate`), { reason: document.getElementById("bd-esc-reason").value, note: document.getElementById("bd-esc-note").value });
    showToast("Sent to Jeff. Use the holding line out loud — he'll take it from there.");
    bdOpenLead(bd.leadId);
  } catch (e) { alert(e.message); }
  return false;
}

// ---------- Visit log flow ----------

const BD_OUTCOMES = ["Claimed a founding spot", "Very interested — set a follow-up", "Talked — needs to think", "Talked to staff — need the owner", "Owner not in", "Said no", "Shop closed / not a fit", "Owner said never contact again"];
const BD_OBJECTIONS = ["Price", "No time", "Tried influencers before", "Doesn't get local %", "Asked when it launches", "Wants to pick creators", "Worried about no-shows", "Wants to know who else is on it", "Other"];
const BD_WANT = ["Food", "Fitness", "Beauty", "Lifestyle", "Going Out", "Other"];
const BD_COMPETITORS = ["Instagram direct", "An agency", "Another platform", "Radio", "None"];

function bdStartLog() {
  const l = bd.lead;
  bd.logDraft = {
    clientUid: `bd${Date.now()}${Math.random().toString(36).slice(2, 8)}`,
    outcome: "", spokeWith: l.dmName ? "Owner" : "", spokeName: l.dmName || "",
    interest: "", objections: [], catsWanted: [], supplyGap: "", competitor: "",
    followUp: "", followUpDate: "", saidWords: "", walkInIntel: "", referral: "",
    visitType: "In person", notFitReason: "", photoData: null, photoType: null,
  };
  const slot = document.getElementById("bd-lead-slot");
  if (!slot) return false;
  const d = bd.logDraft;
  const chip = (group, val, label, on) => `<button type="button" class="chip bd-chip ${on ? "on" : ""}" onclick="return bdLogPick('${group}','${esc(val)}')">${esc(label || val)}</button>`;
  slot.innerHTML = `<div class="panel bd-logflow" style="margin-top:10px">
    <h3 style="margin-top:0">Log this visit</h3>
    <p class="bd-logstep">1 · What happened?</p>
    <div class="chip-row">${BD_OUTCOMES.map((o) => chip("outcome", o, o === "Claimed a founding spot" ? "⭐ " + o : o)).join("")}</div>
    <p class="bd-logstep">2 · Who did you talk to?</p>
    <div class="chip-row">${["Owner", "Manager", "Staff", "No one"].map((s) => chip("spokeWith", s, s === "Owner" && l.dmName ? `Owner — ${l.dmName.split(" ")[0]}` : s)).join("")}</div>
    <input id="bd-log-spokename" placeholder="Their name (if different)" value="${esc(d.spokeName && !l.dmName ? d.spokeName : "")}" style="margin-top:6px">
    <div id="bd-log-interest" hidden>
      <p class="bd-logstep">3 · How interested?</p>
      <div class="chip-row">${["Hot", "Warm", "Cold"].map((s) => chip("interest", s)).join("")}</div>
    </div>
    <div id="bd-log-obj" hidden>
      <p class="bd-logstep">What did they push back on? (tap any)</p>
      <div class="chip-row">${BD_OBJECTIONS.map((o) => chip("objections", o)).join("")}</div>
    </div>
    <p class="bd-logstep">What kinds of creators do they want? (tap any)</p>
    <div class="chip-row">${BD_WANT.map((o) => chip("catsWanted", o)).join("")}</div>
    <div class="field"><label>Asked for a creator type we don't have?</label><input id="bd-log-gap" placeholder="Say what they asked for"></div>
    <p class="bd-logstep">Follow-up</p>
    <div class="chip-row">${[["auto", "Let Magpie pick"], ["tomorrow", "Tomorrow"], ["3days", "In 3 days"], ["week", "Next week"], ["pick", "Pick a date"], ["none", "No follow-up"]].map(([k, label]) => chip("followUp", k, label, k === "auto")).join("")}</div>
    <input type="date" id="bd-log-fudate" hidden>
    <div class="field"><label>What they said — in their words</label><textarea id="bd-log-said" rows="2" placeholder="Anything worth remembering, in their words"></textarea></div>
    <div class="field"><label>Anything else you noticed</label><textarea id="bd-log-intel" rows="2" placeholder="A renovation, a second location, a competitor's poster in the window..."></textarea></div>
    <div class="field"><label>Did they name another business we should visit?</label><input id="bd-log-referral" placeholder="Business name — Jeff gets it as a possible new lead"></div>
    <p class="bd-logstep">Who have they used before?</p>
    <div class="chip-row">${BD_COMPETITORS.map((o) => chip("competitor", o)).join("")}</div>
    <div class="field"><label>Storefront photo (optional — helps you spot the shop next time)</label><input type="file" id="bd-log-photo" accept="image/*" onchange="bdLogPhoto(this)"></div>
    <button type="button" class="btn bd-done" onclick="return bdLogSubmit()">Done</button>
    <span id="bd-log-msg" class="small muted" style="margin-left:8px"></span>
  </div>`;
  slot.scrollIntoView({ behavior: "smooth", block: "start" });
  return false;
}
function bdLogPick(group, val) {
  const d = bd.logDraft;
  if (!d) return false;
  if (group === "objections" || group === "catsWanted") {
    const arr = d[group];
    const i = arr.indexOf(val);
    if (i > -1) arr.splice(i, 1); else arr.push(val);
  } else d[group] = val;
  if (group === "outcome") {
    const interestDiv = document.getElementById("bd-log-interest");
    const objDiv = document.getElementById("bd-log-obj");
    const implies = ["Claimed a founding spot", "Said no", "Owner not in", "Shop closed / not a fit", "Owner said never contact again"].includes(val);
    if (interestDiv) interestDiv.hidden = implies;
    if (objDiv) objDiv.hidden = !["Talked — needs to think", "Talked to staff — need the owner", "Said no", "Very interested — set a follow-up"].includes(val);
  }
  if (group === "followUp") {
    const dateInput = document.getElementById("bd-log-fudate");
    if (dateInput) dateInput.hidden = val !== "pick";
  }
  // repaint chip states inside the log flow only
  const slot = document.getElementById("bd-lead-slot");
  if (slot) slot.querySelectorAll(".bd-chip").forEach((c) => {
    const oc = c.getAttribute("onclick") || "";
    const m = oc.match(/bdLogPick\('([^']+)','((?:[^'\\]|\\.)*)'\)/);
    if (!m) return;
    const g = m[1], v = m[2].replace(/\\'/g, "'");
    const on = (g === "objections" || g === "catsWanted") ? d[g].includes(v) : d[g] === v;
    c.classList.toggle("on", !!on);
  });
  return false;
}
function bdLogPhoto(input) {
  const file = input.files && input.files[0];
  if (!file) return;
  const img = new Image();
  img.onload = () => {
    const max = 1100;
    const scale = Math.min(1, max / Math.max(img.width, img.height));
    const cv = document.createElement("canvas");
    cv.width = Math.round(img.width * scale); cv.height = Math.round(img.height * scale);
    cv.getContext("2d").drawImage(img, 0, 0, cv.width, cv.height);
    const url = cv.toDataURL("image/jpeg", 0.72);
    bd.logDraft.photoData = url.split(",")[1];
    bd.logDraft.photoType = "image/jpeg";
    URL.revokeObjectURL(img.src);
  };
  img.src = URL.createObjectURL(file);
}
async function bdLogSubmit() {
  const d = bd.logDraft;
  const msg = document.getElementById("bd-log-msg");
  if (!d.outcome) { msg.textContent = "Pick what happened first."; return false; }
  if (!d.spokeWith) { msg.textContent = "Say who you talked to."; return false; }
  const body = {
    clientUid: d.clientUid, outcome: d.outcome, spokeWith: d.spokeWith,
    spokeName: (document.getElementById("bd-log-spokename").value || d.spokeName || "").trim() || null,
    interest: d.interest || null, objections: d.objections, catsWanted: d.catsWanted,
    supplyGap: document.getElementById("bd-log-gap").value || null,
    competitor: d.competitor || null, saidWords: document.getElementById("bd-log-said").value || null,
    walkInIntel: document.getElementById("bd-log-intel").value || null,
    referral: document.getElementById("bd-log-referral").value || null,
    visitType: d.visitType, photoData: d.photoData, photoType: d.photoType,
  };
  if (d.followUp === "none") body.followUp = "none";
  else if (d.followUp === "tomorrow") body.followUpDate = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
  else if (d.followUp === "3days") body.followUpDate = new Date(Date.now() + 3 * 86400000).toISOString().slice(0, 10);
  else if (d.followUp === "week") body.followUpDate = new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10);
  else if (d.followUp === "pick") body.followUpDate = document.getElementById("bd-log-fudate").value || null;
  msg.textContent = "Saving...";
  try {
    const r = await api("POST", bdPath(`/bdev/leads/${bd.leadId}/log`), body);
    showToast(r.message || "Logged.");
    bd.logDraft = null;
    bdOpenLead(bd.leadId);
  } catch (e) {
    bdQueuePost(bdPath(`/bdev/leads/${bd.leadId}/log`), body);
    showToast("Saved on this phone — it will send when you have signal.");
    bd.logDraft = null;
    go("dashboard", "BD Home");
  }
  return false;
}

// ---------- Show Mode ----------

async function bdEnsurePin() {
  const home = bd.home || bdCacheGet("home");
  if (home && home.rep && home.rep.pinSet) return true;
  const pin = window.prompt("Set your 4-number Show Mode PIN first — it's the only way out of Show Mode, so a client holding your phone can't wander into your book.");
  if (!pin) return false;
  try { await api("POST", "/bdev/pin", { pin }); if (bd.home) bd.home.rep.pinSet = true; return true; }
  catch (e) { alert(e.message); return false; }
}
async function bdShowEnter(leadId) {
  if (!await bdEnsurePin()) return false;
  try {
    const d = await api("GET", bdPath(`/bdev/leads/${leadId}/show`));
    bd.show = { data: d, screen: 1, maxSeen: 1, startedAt: Date.now(), pricing: false };
    bdShowRender();
  } catch (e) { alert(e.message); }
  return false;
}
async function bdPriceEnter(leadId) {
  if (!await bdEnsurePin()) return false;
  try {
    await api("POST", bdPath(`/bdev/leads/${leadId}/price-shown`), {});
    const d = await api("GET", bdPath(`/bdev/leads/${leadId}/show`));
    bd.show = { data: d, screen: 7, maxSeen: 7, startedAt: Date.now(), pricing: true };
    bdShowRender();
  } catch (e) { alert(e.message); }
  return false;
}
function bdShowScreens() {
  const d = bd.show.data;
  // Build -161 fix: the deck speaks the LEAD's market (the show
  // payload carries it) — a Nashville business must never be
  // told a Hampton Roads story over a Nashville bench.
  const mktName = d.marketName || "Hampton Roads";
  const bench = d.bench || [];
  const cards = bench.map((c) => `
    <div class="bd-show-card">
      ${c.photoUrl ? `<img class="bd-show-photo" src="${esc(c.photoUrl)}" alt="" onerror="this.remove()">` : `<div class="bd-show-photo bd-show-mono">${esc(String(c.firstName || "?").charAt(0).toUpperCase())}</div>`}
      <div class="bd-show-cmain">
        <div class="bd-show-cname">${esc(c.firstName || c.name)} ${handleLabel(c.handle) ? `<span class="muted">${esc(handleLabel(c.handle))}</span>` : ""}</div>
        <div class="muted small">${esc(c.categoryLine)}${c.alsoLine ? ` · Also in ${esc(mktName)}` : ""}</div>
        ${c.reachLine ? `<div class="bd-show-reach">${esc(c.reachLine)}</div>` : ""}
        ${c.areaLine ? `<div class="bd-show-reach">${esc(c.areaLine)}</div>` : ""}
      </div>
    </div>`).join("");
  const af = d.areaFraming;
  return [
    { title: `Your next regulars are already following people right here in ${mktName}.`, body: `<p>Magpie is a local list of creators — neighbors with local followings. Local shops use them to get local people in the door. You're being invited in early, before we open here.</p>` },
    { title: `These are founding creators in ${mktName}.`, body: bench.length ? `${cards}${af ? `<p class="bd-show-reach">Based in ${esc(af.label)}: ${af.count} of these creators — together they reach about ${fmtNum(af.combinedNeighbors)} ${af.anyExtrapolated ? "potential local followers" : "local followers"}.</p>` : ""}<p class="muted">The founding list is growing every week. Shops that claim a spot now get first pick when we open.</p>` : `<p>The founding list is growing every week — the first creators in this category are being added now. Shops that claim a spot now get first pick when we open.</p>` },
    { title: "You pick. You approve. Nothing posts without you.", body: `<ol class="bd-show-steps"><li>Invite a creator to come in. Treat them to a visit — a meal, a service, an experience — and they post 1 post + 1 story.</li><li>Or book them at their own listed price for bigger work. They set their rate. (Creators keep 97% of their rate — the 3% is card processing.)</li><li>Every visit is counted at your register with their own code — you'll see exactly who came in because of them.</li></ol><p><strong>You choose every creator. You approve every visit. You see the count.</strong></p>` },
    { title: "We don't guess. We count.", body: `<p>Magpie's match system ranks creators by how many of their followers actually live here — not by who's most famous. When you want an idea, Maggie, our in-app helper, suggests a campaign and names the creators she'd pick for your shop, and why. After a visit, you don't get “good vibes” — you get a count: how many of their people came in and used the code.</p>` },
    { title: `${mktName} founding spots are open now.`, body: `<p>We're building the founding creator list for ${mktName} right now. Shops that claim a founding spot are first in line when we open — first pick of creators, founding pricing locked, and we'll set your page up with you. There's nothing to pay today — paying starts when we open here, and we open when the founding creator roster is full. You're being invited in early.</p>` },
    { title: "Claim your founding spot.", body: BD_PREVIEW ? `
      <form id="bd-show-claim" onsubmit="return bdShowClaim(event)">
        <fieldset disabled>
        <div class="field"><label>Your name</label><input id="bsc-name" autocomplete="name" disabled></div>
        <div class="field"><label>Business name</label><input id="bsc-biz" value="${esc(d.lead.name)}" autocomplete="organization" disabled></div>
        <div class="field"><label>Best phone or Instagram to reach you</label><input id="bsc-contact" disabled></div>
        <label class="bd-show-check"><input type="checkbox" id="bsc-yes" disabled> <span>Yes — put us on the ${mktName} founding list.</span></label>
        <button type="submit" class="btn bd-show-next" disabled>Claim your founding spot</button>
        </fieldset>
        <p class="muted small">Claims are off while Jeff is looking.</p>
        <p class="muted small">Or scan the code on the card ${esc(d.repFirstName || "your rep")} leaves you and do it on your own phone. No payment today.</p>
        <p id="bsc-msg" class="small"></p>
      </form>` : `
      <form id="bd-show-claim" onsubmit="return bdShowClaim(event)">
        <div class="field"><label>Your name</label><input id="bsc-name" autocomplete="name"></div>
        <div class="field"><label>Business name</label><input id="bsc-biz" value="${esc(d.lead.name)}" autocomplete="organization"></div>
        <div class="field"><label>Best phone or Instagram to reach you</label><input id="bsc-contact"></div>
        <label class="bd-show-check"><input type="checkbox" id="bsc-yes"> <span>Yes — put us on the ${mktName} founding list.</span></label>
        <button type="submit" class="btn bd-show-next">Claim your founding spot</button>
        <p class="muted small">Or scan the code on the card ${esc(d.repFirstName || "your rep")} leaves you and do it on your own phone. No payment today.</p>
        <p id="bsc-msg" class="small"></p>
      </form>` },
    { title: "Founding plans.", pricing: true, body: `<div class="bd-plans"><div class="bd-plan"><strong>$199</strong><span>a month</span></div><div class="bd-plan"><strong>$349</strong><span>a month</span></div><div class="bd-plan"><strong>$699</strong><span>a month</span></div></div><p>3-month minimum · $100 off your first month.</p><p class="muted">You'd pick your plan when we open — nothing to pay today.</p>` },
  ];
}
function bdShowRender() {
  const s = bd.show;
  if (!s) return;
  const screens = bdShowScreens();
  const total = s.pricing ? 1 : 6;
  const idx = s.pricing ? 7 : s.screen;
  const sc = screens[idx - 1];
  let host = document.getElementById("bd-show-overlay");
  if (!host) { host = document.createElement("div"); host.id = "bd-show-overlay"; document.body.appendChild(host); }
  host.innerHTML = `
  <div class="bd-show-wrap">
    <div class="bd-show-top">
      <span class="bd-show-mark" id="bd-show-mark" title="Magpie"><img src="/assets/logo.png" alt="Magpie"></span>
      <span class="muted small">${s.pricing ? "Founding plans" : `${idx} of ${total}`}</span>
    </div>
    <div class="bd-show-progress"><span style="width:${(idx / 6) * 100}%"></span></div>
    <div class="bd-show-body">
      <h1 class="bd-show-title">${esc(sc.title)}</h1>
      <div class="bd-show-text">${sc.body}</div>
    </div>
    ${idx === 6 || s.pricing ? "" : `<button type="button" class="btn bd-show-next" onclick="return bdShowNext()">Next</button>`}
    ${!s.pricing && idx > 1 && idx < 6 ? `<button type="button" class="linklike bd-show-back" onclick="return bdShowBack()">Back</button>` : ""}
    ${BD_PREVIEW ? `<button type="button" class="btn ghost bd-show-next" onclick="return abdPvShowExit()">Done looking</button><p class="muted small bd-show-hint">Preview only — nothing here saves, sends, or counts.</p>` : `<p class="muted small bd-show-hint">Hold the Magpie mark to hand the phone back.</p>`}
  </div>`;
  const mark = document.getElementById("bd-show-mark");
  let timer = null;
  if (!BD_PREVIEW && mark) {
    mark.addEventListener("pointerdown", () => { timer = setTimeout(bdShowPinPad, 2000); });
    ["pointerup", "pointerleave", "pointercancel"].forEach((ev) => mark.addEventListener(ev, () => clearTimeout(timer)));
  }
  let tx = null;
  host.ontouchstart = (e) => { tx = e.touches[0].clientX; };
  host.ontouchend = (e) => {
    if (tx == null || s.pricing) return;
    const dx = e.changedTouches[0].clientX - tx;
    if (dx < -60) bdShowNext(); else if (dx > 60) bdShowBack();
    tx = null;
  };
}
function bdShowNext() { if (bd.show && bd.show.screen < 6) { bd.show.screen += 1; bd.show.maxSeen = Math.max(bd.show.maxSeen, bd.show.screen); bdShowRender(); } return false; }
function bdShowBack() { if (bd.show && bd.show.screen > 1) { bd.show.screen -= 1; bdShowRender(); } return false; }
async function bdShowClaim(ev) {
  if (BD_PREVIEW) return false;
  ev.preventDefault();
  const msg = document.getElementById("bsc-msg");
  const body = {
    rep: (bd.home && bd.home.rep && bd.home.rep.repCode) || "",
    lead: bd.show.data.lead.id,
    businessName: document.getElementById("bsc-biz").value,
    name: document.getElementById("bsc-name").value,
    contact: document.getElementById("bsc-contact").value,
    yes: document.getElementById("bsc-yes").checked,
  };
  try {
    const d = await api("POST", "/bdev/claim", body);
    msg.textContent = d.message || "You're on the list.";
    msg.style.color = "#1F6B3B";
  } catch (e) { msg.textContent = e.message; }
  return false;
}
function bdShowPinPad() {
  if (BD_PREVIEW) return;
  const host = document.getElementById("bd-show-overlay");
  if (!host || !bd.show) return;
  host.innerHTML = `<div class="bd-show-wrap bd-pin-wrap">
    <p class="bd-pin-title">Enter your PIN</p>
    <div class="bd-pin-dots"><span id="bd-pin-dot"></span></div>
    <div class="bd-pin-pad">${[1, 2, 3, 4, 5, 6, 7, 8, 9, "", 0, "←"].map((n) => n === "" ? `<span></span>` : `<button type="button" class="bd-pin-key" onclick="return bdPinKey('${n}')">${n}</button>`).join("")}</div>
    <p id="bd-pin-msg" class="small muted"></p>
    <button type="button" class="linklike" onclick="bdShowRender()">Back to the show</button>
  </div>`;
  bd.show.pinEntry = "";
}
function bdPinKey(k) {
  const s = bd.show;
  if (!s) return false;
  if (k === "←") s.pinEntry = (s.pinEntry || "").slice(0, -1);
  else if ((s.pinEntry || "").length < 4) s.pinEntry = (s.pinEntry || "") + k;
  const dot = document.getElementById("bd-pin-dot");
  if (dot) dot.textContent = "•".repeat((s.pinEntry || "").length);
  if ((s.pinEntry || "").length === 4) bdPinVerify();
  return false;
}
async function bdPinVerify() {
  if (BD_PREVIEW) return false;
  const s = bd.show;
  try {
    const d = await api("POST", "/bdev/pin/verify", { pin: s.pinEntry });
    if (d.ok) {
      const pages = s.pricing ? 1 : s.maxSeen;
      const seconds = Math.round((Date.now() - s.startedAt) / 1000);
      const leadId = s.data.lead.id;
      api("POST", bdPath(`/bdev/leads/${leadId}/show-session`), { pages, seconds }).catch(() => {});
      const host = document.getElementById("bd-show-overlay");
      if (host) host.remove();
      bd.show = null;
      showToast("Show Mode closed.");
    } else {
      const msg = document.getElementById("bd-pin-msg");
      if (msg) msg.textContent = "That PIN didn't match. Try again.";
      s.pinEntry = "";
      const dot = document.getElementById("bd-pin-dot");
      if (dot) dot.textContent = "";
    }
  } catch (e) {
    const msg = document.getElementById("bd-pin-msg");
    if (msg) msg.textContent = e.message;
  }
}

