async function bdLoadKit(el) {
  el = el || document.getElementById("tab-body");
  if (!el) return;
  let d = null;
  try { d = await api("GET", bdPath("/bdev/kit")); bd.kit = d.kit; bdSyncSeat161(d.seat); bdCacheSet("kit", d); }
  catch (e) { if (bdSeatGone(e, el)) return; d = bdCacheGet("kit"); if (!d) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; return; } }
  const k = d.kit;
  bd.practiceItems = d.practice || k.practice || bd.practiceItems || [];
  const card = (title, text) => `<div class="card bd-kit-card"><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;
  el.innerHTML = `
  <h2>Seller Kit</h2>
  ${bdCitySwitcherHtml()}
  <p class="muted small" style="margin:4px 0 10px">Every word here is approved to say out loud, word for word. ${bd.hqSeat ? "This is your kit, in your voice, for the city picked above." : "If it isn't in the Kit, it goes to Jeff."}</p>
  <div class="field"><input id="bd-kit-q" type="search" placeholder="Search the kit — try “launch” or “expensive”" oninput="bdKitSearch(this.value)"></div>
  <div id="bd-kit-results"></div>
  <h3 class="bd-h">Openers</h3>
  ${k.openers.map((o) => card(o.title, o.text)).join("")}
  ${k.twoMinute ? `<div class="card bd-kit-card"><strong>${esc(k.twoMinute.title)}</strong>${(k.twoMinute.paras || []).map((p) => `<p>${esc(p)}</p>`).join("")}</div>` : ""}
  <h3 class="bd-h">The founding list</h3>
  ${card(k.openers[1].title, k.openers[1].text)}
  <h3 class="bd-h">Price answers <span class="muted small">(only when they ask)</span></h3>
  ${k.priceAnswers.map((o) => card(o.title, o.text)).join("")}
  <div class="card bd-kit-card"><strong>Founding terms — exactly what you may quote</strong><ul class="bd-terms">${k.foundingTerms.map((t) => `<li>${esc(t)}</li>`).join("")}</ul>
  <p style="margin:10px 0 0"><a class="btn ghost small-btn" href="${esc(k.deck.url)}" target="_blank" rel="noopener">Open the seller deck (${esc(k.deck.version)})</a></p></div>
  ${(k.printKit && k.printKit.length) ? `<h3 class="bd-h">Your print kit</h3>${k.printKit.map((p) => `<div class="card bd-kit-card"><strong>${esc(p.label)}</strong><p>${esc(p.note || "")}</p><p style="margin:10px 0 0"><a class="btn ghost small-btn" href="${esc(p.url)}" download>Download the PDF</a></p></div>`).join("")}` : ""}
  <h3 class="bd-h">Objections</h3>
  ${k.objections.map((o) => card(o.q, o.a)).join("")}
  <div id="bd-practice"></div>
  <h3 class="bd-h">Closing</h3>
  ${k.closing.map((o) => card(o.title, o.text)).join("")}
  ${(k.faq && k.faq.length) ? `<h3 class="bd-h">Questions businesses ask</h3>${k.faq.map((f) => card(f.q, f.a)).join("")}` : ""}
  <div class="card bd-kit-danger">
    <strong>Rules — never say these</strong>
    <ul class="bd-terms">${k.doNotSay.map((t) => `<li>${esc(t)}</li>`).join("")}</ul>
  </div>
  ${bd.hqSeat ? `<div class="card bd-kit-card">
    <strong>Your calls</strong>
    <p>These are yours to decide — nobody else makes them: discounts or free months, partner or media talk, chains, anyone wanting to invest, complaints, press.</p>
    <p><em>“${esc(k.holdingLine)}”</em></p>
  </div>` : `<div class="card bd-kit-card">
    <strong>Help from Jeff</strong>
    <p>Some things are always Jeff's call: discounts or free months, partner or media talk, chains, anyone wanting to invest, complaints, press.</p>
    <p><em>“${esc(k.holdingLine)}”</em></p>
    <p class="muted small">Send it from the lead's page with <strong>Ask Jeff</strong> — one tap, before you leave the shop.</p>
  </div>`}`;
  bdRenderPractice();
}
function bdRenderPractice() {
  const host = document.getElementById("bd-practice");
  if (!host) return;
  const items = bd.practiceItems || [];
  if (!items.length) { host.innerHTML = ""; return; }
  host.innerHTML = `<h3 class="bd-h">Practice with Maggie</h3>
  <p class="muted small" style="margin:4px 0 10px">Maggie plays the owner. Pick what you'd say — she'll tell you straight.</p>
  ${items.map((item) => {
    const n = item.n;
    const picked = bdPractice[n];
    const base = [{ kind: "answer", text: item.answer }, { kind: "trap", text: item.trap }, { kind: "weak", text: item.weak }];
    const shift = ((Number(n) || 0) % 3 + 3) % 3;
    const options = base.slice(shift).concat(base.slice(0, shift));
    const result = picked ? `<div class="bd-practice-result"><strong>${picked === "answer" ? "That's the one." : "Not that one."}</strong>${item.why ? `<p style="margin:6px 0">${esc(item.why)}</p>` : ""}<div class="bd-practice-answer"><span class="muted small">Say it like this:</span><p style="margin:4px 0 0;white-space:pre-wrap;line-height:1.55">${esc(item.answer || "")}</p></div></div>` : `<div style="display:flex;flex-direction:column;gap:8px;margin-top:10px">${options.map((o) => `<button type="button" class="btn ghost" style="text-align:left;justify-content:flex-start" onclick="return bdPracticePick(${Number(n) || 0},'${o.kind}')">${esc(o.text || "")}</button>`).join("")}</div>`;
    return `<div class="card bd-kit-card"><p class="muted small" style="margin:0">The owner says:</p><p style="font-size:17px;line-height:1.5;margin:6px 0 0"><em>“${esc(item.label || "")}”</em></p>${result}</div>`;
  }).join("")}`;
}
function bdPracticePick(n, kind) {
  bdPractice[n] = kind;
  bdRenderPractice();
  return false;
}
function bdKitSearch(q) {
  const host = document.getElementById("bd-kit-results");
  if (!host || !bd.kit) return;
  q = (q || "").trim().toLowerCase();
  if (q.length < 2) { host.innerHTML = ""; return; }
  const k = bd.kit;
  const pool = [...k.openers, ...k.priceAnswers, ...k.closing, ...k.objections.map((o) => ({ title: o.q, text: o.a }))];
  const hits = pool.filter((i) => (i.title + " " + i.text).toLowerCase().includes(q));
  host.innerHTML = hits.length ? hits.map((i) => `<div class="card bd-kit-card"><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p></div>`).join("") : `<p class="muted small">Nothing in the Kit matches that. If it isn't in the Kit, it goes to Jeff.</p>`;
}

