// ---------- Admin: Biz Dev room (Build -155) ----------

const abd = { data: null, leads: [], contacts: [], orders: [], contactQ: "", preview: null, previewTab: "Home", previewLead: null, leadFilter: { city: "", neighborhood: "", status: "", rep: "", q: "", category: "" }, manageOpen: {}, prewarmOpen: {} };
async function loadAdminBizdev155() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = skelHtml("Loading the seller system...", 3);
  try {
    // Build -170: the overview and the lead list are independent
    // reads — fetch them together instead of one after the other.
    const [overviewRes, leadsRes, contactsRes, ordersRes] = await Promise.all([
      api("GET", "/admin/bdev/overview"),
      api("GET", "/admin/bdev/leads"),
      api("GET", "/admin/bdev/contacts").catch(() => ({ contacts: [] })),
      api("GET", "/admin/bdev/orders").catch(() => ({ orders: [] })),
    ]);
    abd.data = overviewRes;
    abd.leads = leadsRes.leads || [];
    abd.contacts = contactsRes.contacts || [];
    abd.orders = ordersRes.orders || [];
    abdRender(el);
  } catch (e) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; }
}
function abdCountsChips(counts) {
  return BD_STATUSES.map((s) => `<span class="badge ${s === "Closed" ? "ok" : ""}" style="margin:0 4px 4px 0">${esc(s)}: ${Number((counts || {})[s] || 0)}</span>`).join("");
}
// Build -161: what is waiting on Jeff, counted once, used by the
// strip at the top of this room, the Admin-home entry and the
// menu badges — one definition so the three never disagree.
// Referrals are FYI only and deliberately not counted.
function abdConfirmableClaims(d) {
  // A claim can only be CONFIRMED once it is matched to a lead;
  // the unmatched ones are their own waiting kind (the match
  // panel below), never double-counted in both.
  return ((d && d.unconfirmedClaims) || []).filter((c) => c.leadId);
}
function abdWaitingCounts(d) {
  const c = {
    claims: abdConfirmableClaims(d).length,
    leads: ((d && d.pendingLeads) || []).length,
    unmatched: ((d && d.disputes) || []).length,
    escalations: ((d && d.escalations) || []).length,
  };
  c.total = c.claims + c.leads + c.unmatched + c.escalations;
  return c;
}
function abdWaitingStripHtml(d) {
  const c = abdWaitingCounts(d);
  if (!c.total) return `<div class="panel abd-wait abd-wait-clear"><strong>Nothing waiting on you.</strong> <span class="muted">No claims to confirm, no leads to approve, no escalations open.</span></div>`;
  const part = (n, label, anchor) => n ? `<button type="button" class="btn ghost small-btn" onclick="return abdJump('${anchor}')">${n} ${label}</button>` : "";
  return `<div class="panel abd-wait"><strong>Waiting on you: ${c.total}</strong> <span style="margin-left:6px">${part(c.claims, c.claims === 1 ? "claim to confirm" : "claims to confirm", "abd-panel-claims")}${part(c.leads, c.leads === 1 ? "lead to approve" : "leads to approve", "abd-panel-leads")}${part(c.unmatched, c.unmatched === 1 ? "claim to match" : "claims to match", "abd-panel-unmatched")}${part(c.escalations, c.escalations === 1 ? "escalation" : "escalations", "abd-panel-escalations")}</span></div>`;
}
function abdJump(id) {
  const t = document.getElementById(id);
  if (t) t.scrollIntoView({ behavior: "smooth", block: "start" });
  return false;
}
// Build -161: the confirm step. Confirming a claim is the tap
// that makes it count, so it always names the business first —
// and the button only exists (enabled) when a real claim is
// waiting on that lead.
function abdConfirmClaim(leadId) {
  const l = (abd.leads || []).find((x) => x.id === leadId);
  const name = l ? l.name : "this business";
  if (!window.confirm(`Confirm ${name} as a founding claim? This is the tap that makes it count.`)) return false;
  return abdLeadAction(leadId, "confirm-claim");
}
function abdPendingClaimFor(leadId) {
  return ((abd.data && abd.data.unconfirmedClaims) || []).some((c) => c.leadId === leadId);
}
function abdToggleManage(id) {
  abd.manageOpen[id] = !abd.manageOpen[id];
  const host = document.getElementById("abd-lead-list");
  if (host) host.innerHTML = abdLeadRowsHtml();
  return false;
}
function abdTogglePrewarm(i) {
  abd.prewarmOpen[i] = !abd.prewarmOpen[i];
  const body = document.getElementById(`abd-prewarm-body-${i}`);
  const btn = document.getElementById(`abd-prewarm-btn-${i}`);
  if (body) body.style.display = abd.prewarmOpen[i] ? "" : "none";
  if (btn) btn.textContent = abd.prewarmOpen[i] ? "Hide" : "Read";
  return false;
}
function abdRollupHtml(d) {
  // The overview ships statusRollup as a map keyed by marketId
  // (values carry marketId/byStatus/byCity/byNeighborhood);
  // accept a plain array of the same rows too.
  const raw = d.statusRollup;
  const roll = Array.isArray(raw) ? raw : raw && typeof raw === "object" ? Object.values(raw) : [];
  if (!roll.length) return "";
  const marketName = (id) => { const m = (d.markets || []).find((x) => x.marketId === id); return m ? (m.marketName || m.marketId) : id; };
  return roll.map((r) => `<div class="panel abd-rollup">
    <strong>Where things stand — ${esc(marketName(r.marketId) || r.marketId || "")}</strong>
    <p class="muted small" style="margin:4px 0 0">How every lead in this market is doing, by status. Counts unique businesses, the same basis as the All leads list.</p>
    <div style="margin:8px 0">${abdCountsChips(r.byStatus)}</div>
    ${(r.byCity || []).length ? `<table class="abd-rollup-table"><thead><tr><th>City</th>${BD_STATUSES.map((s) => `<th>${esc(s)}</th>`).join("")}</tr></thead><tbody>${r.byCity.map((c) => `<tr><td data-label="City">${esc(c.city || "")}</td>${BD_STATUSES.map((s) => `<td data-label="${esc(s)}">${Number((c.counts || {})[s] || 0)}</td>`).join("")}</tr>`).join("")}</tbody></table>` : ""}
    ${(r.byNeighborhood || []).length ? `<div style="margin-top:10px">${r.byNeighborhood.map((n) => { const total = BD_STATUSES.reduce((a, s) => a + Number((n.counts || {})[s] || 0), 0); return `<div class="bd-logrow" style="font-size:13.5px"><strong>${esc(n.neighborhood || "")}</strong> <span class="muted">· ${esc(n.city || "")} · ${total} total</span><div style="margin-top:4px">${abdCountsChips(n.counts)}</div></div>`; }).join("")}</div>` : ""}
  </div>`).join("");
}
function abdPrewarmText(item) {
  if (!item) return "";
  const dr = item.draft;
  if (!dr) return "";
  if (typeof dr === "string") return dr;
  return [dr.subject ? `Subject: ${dr.subject}` : "", dr.body || dr.text || ""].filter(Boolean).join("\n\n");
}
function abdCopyPrewarm(i) {
  const item = (abd.data && abd.data.prewarm || [])[i];
  return bdCopyText(abdPrewarmText(item), "Copied — paste it into your own email when you're ready.");
}
async function abdSetStatus(leadId) {
  const sel = document.getElementById(`abd-status-${leadId}`);
  if (!sel) return false;
  try { await api("POST", `/admin/bdev/leads/${leadId}/status`, { status: sel.value }); showToast("Status saved."); abdRefresh(); }
  catch (e) { alert(e.message); }
  return false;
}
function abdFilteredLeads() {
  const f = abd.leadFilter || { city: "", neighborhood: "", status: "", rep: "", q: "", category: "" };
  const q = String(f.q || "").toLowerCase();
  return (abd.leads || []).filter((l) => (!f.city || l.city === f.city) && (!f.neighborhood || l.neighborhood === f.neighborhood) && (!f.status || l.status === f.status) && (!f.rep || l.assignedRepId === f.rep) && (!f.category || l.category === f.category) && (!q || [l.name, l.dmName, l.category, l.city, l.neighborhood].join(" ").toLowerCase().includes(q)));
}
function abdSetLeadQuery(v) {
  abd.leadFilter.q = v || "";
  const host = document.getElementById("abd-lead-list");
  if (host) host.innerHTML = abdLeadRowsHtml();
  return false;
}
function abdSetContactQuery(v) {
  abd.contactQ = v || "";
  const host = document.getElementById("abd-contact-list");
  if (host) host.innerHTML = abdContactsHtml();
  return false;
}
// Build -189 (PL-36): a designed empty state: icon, one line,
// and the action that fills the panel.
function abdEmpty189(icon, title, line, actionHtml) {
  return `<div class="abd-empty189"><span class="ae-ic">${bnIcon(icon)}</span><div><div class="ae-t">${esc(title)}</div><div class="ae-s">${esc(line)}</div>${actionHtml || ""}</div></div>`;
}
function abdClearLeadFilters189() {
  abd.leadFilter = { q: "", category: "", city: "", neighborhood: "", status: "", rep: "" };
  abdRender();
  return false;
}
function abdContactsHtml() {
  const q = String(abd.contactQ || "").toLowerCase();
  const list = (abd.contacts || []).filter((c) => !q || [c.name, c.business, c.city, c.role, c.ownerName].join(" ").toLowerCase().includes(q));
  if (!list.length) return abdEmpty189("users", "No contacts match", "Contacts appear here as leads and sellers add the people on each record.", "");
  return list.map((c) => bdContactCard(c, { ro: true, ownerTag: true })).join("");
}
function abdOrdersHtml() {
  const list = abd.orders || [];
  if (!list.length) return abdEmpty189("receipt", "No orders recorded yet", "When a seller records an order in their book, it shows here.", "");
  return list.map((o) => bdOrderCard(o, { ownerTag: true })).join("");
}
// Build -161: compact rows. The status control stays inline in
// the row (it's the daily job); everything heavier — the guarded
// Confirm claim, the flags, reassign — lives behind one Manage
// expander. Reassign renders only when a second seat exists.
function abdLeadRowsHtml() {
  const d = abd.data;
  if (!d) return "";
  const repName = (id) => { const r = (d.reps || []).find((x) => x.userId === id); return r ? `${r.name} (${r.repCode})` : id; };
  const rows = abdFilteredLeads();
  if (!rows.length) return abdEmpty189("search", "No leads match those filters", "Loosen a filter, or clear them all to see the whole book.", `<button type="button" class="btn ghost small-btn" onclick="return abdClearLeadFilters189()">Clear filters</button>`);
  const multiRep = (d.reps || []).length > 1;
  return rows.map((l) => {
    const open = !!abd.manageOpen[l.id];
    const claimWaiting = abdPendingClaimFor(l.id);
    return `
      <div class="bd-logrow abd-leadrow">
        <div class="abd-leadline"><strong>${esc(l.name)}</strong> ${bdStatusBadge(l.status)}<button type="button" class="btn ghost small-btn" style="margin-left:8px" onclick="return abdToggleManage('${l.id}')">${open ? "Close" : "Manage"}</button></div>
        <div class="muted small" style="margin-top:2px">${esc(l.category)} · ${esc(l.neighborhood || "")}${l.city ? ` · ${esc(l.city)}` : ""} · ${esc(l.stage)} · ${esc(repName(l.assignedRepId))}${l.source === "Added by rep" ? " · added by the rep" : ""}${l.pendingApproval ? " · ⏳ waiting your check" : ""}${l.founding && l.founding.status === "Claimed" ? " · claimed, unconfirmed" : ""}${l.founding && l.founding.status === "Confirmed" ? " · claimed ✓" : ""}${l.hasPlaybook ? " · has playbook" : ""}${l.workClaim ? ` · ${esc(String(l.workClaim.byName || l.workClaim.byRepCode).trim().split(/\s+/)[0] || l.workClaim.byRepCode)} is working it` : ""}</div>
        ${bdContactLine(l)}
        <span style="display:block;margin-top:6px">
          <select id="abd-status-${l.id}" aria-label="Status for ${esc(l.name)}">${BD_STATUSES.map((s) => `<option value="${esc(s)}" ${l.status === s ? "selected" : ""}>${esc(s)}</option>`).join("")}</select>
          <button type="button" class="btn ghost small-btn" onclick="return abdSetStatus('${l.id}')">Set status</button>
        </span>
        ${open ? `<div class="abd-manage">
          ${claimWaiting
            ? `<button type="button" class="btn small-btn" onclick="return abdConfirmClaim('${l.id}')">Confirm claim</button>`
            : `<button type="button" class="btn ghost small-btn" disabled>Confirm claim</button> <span class="muted small">No claim is waiting on this lead — nothing to confirm.</span>`}
          <button type="button" class="btn ghost small-btn" onclick="return abdFlag('${l.id}','doNotContact',${!(l.flags && l.flags.doNotContact)})">${l.flags && l.flags.doNotContact ? "Clear do-not-contact" : "Set do-not-contact"}</button>
          <button type="button" class="btn ghost small-btn" onclick="return abdFlag('${l.id}','jeffHandles',${!(l.flags && l.flags.jeffHandles)})">${l.flags && l.flags.jeffHandles ? "Clear “Jeff handles”" : "Jeff handles this one"}</button>
          ${multiRep ? `<select id="abd-reassign-${l.id}" aria-label="Reassign ${esc(l.name)}">${(d.reps || []).map((r) => `<option value="${r.userId}" ${r.userId === l.assignedRepId ? "selected" : ""}>${esc(r.repCode)}</option>`).join("")}</select>
          <button type="button" class="btn ghost small-btn" onclick="return abdReassign('${l.id}')">Reassign</button>` : ""}
        </div>` : ""}
      </div>`;
  }).join("");
}
function abdSetLeadFilter(key, val) {
  abd.leadFilter[key] = val || "";
  const host = document.getElementById("abd-lead-list");
  if (host) host.innerHTML = abdLeadRowsHtml();
  else { const el = document.getElementById("tab-body"); if (el) abdRender(el); }
  return false;
}
// ---------- Admin preview (Build -157): Jeff looks through a rep's eyes, read-only ----------
async function abdPreviewOpen(repId) {
  try {
    const d = await api("GET", `/admin/bdev/preview?repId=${encodeURIComponent(repId)}`);
    abd.preview = d; abd.previewTab = "Home"; abd.previewLead = null;
    abdPreviewRender();
  } catch (e) { alert(e.message); }
  return false;
}
function abdPreviewClose() {
  if (BD_PREVIEW) { const sh = document.getElementById("bd-show-overlay"); if (sh) sh.remove(); BD_PREVIEW = false; bd.show = null; }
  const el = document.getElementById("abd-preview");
  if (el) el.remove();
  abd.previewLead = null;
  return false;
}
function abdPreviewRender() {
  const pv = abd.preview;
  if (!pv) return;
  let host = document.getElementById("abd-preview");
  if (!host) { host = document.createElement("div"); host.id = "abd-preview"; document.body.appendChild(host); }
  const seat = pv.seat || {};
  const tabs = ["Home", "My Leads", "Contacts", "Orders", "Seller Kit", "My Money"];
  host.innerHTML = `
  <div class="abd-pv-banner"><span>You're seeing <strong>${esc(seat.repName || "the rep")}'s</strong> view — looking only. Nothing you tap here saves, sends, or counts.</span><button type="button" class="btn small-btn" onclick="return abdPreviewClose()">Back to your view</button></div>
  <div class="abd-pv-frame">
    <div class="abd-pv-tabs">${tabs.map((t) => `<button type="button" class="chip ${abd.previewTab === t ? "on" : ""}" onclick="return abdPvSetTab('${t}')">${esc(t)}</button>`).join("")}</div>
    <div id="abd-pv-body"></div>
  </div>`;
  abdPvRenderBody();
}
function abdPvSetTab(t) { abd.previewTab = t; abd.previewLead = null; abdPreviewRender(); return false; }
function abdPvLeadsList() {
  const pv = abd.preview;
  if (!pv) return [];
  if (Array.isArray(pv.leads)) return pv.leads;
  return (pv.leads && pv.leads.leads) || [];
}
