// ---------- admin: the National room ----------
// PL-17 (Build -191): the national publishing hold + the
// pre-publish review queue. The gate panel says the EFFECTIVE
// state in plain words: a live market releases it even when the
// stored hold still says on.
function adminNatGateHtml191(g) {
  const line = g.effectiveOn
    ? "On. A national campaign a brand publishes waits in the queue below for review before any creator can see it."
    : g.releasedByLaunch
      ? "Released by launch. A market is live, so national campaigns go out as soon as a brand publishes them. The stored hold is still on, but it no longer holds anything."
      : "Off. National campaigns go out as soon as a brand publishes them.";
  const btn = g.storedOn
    ? `<button type="button" class="btn small-btn" onclick="return adminNatGateToggle191(false)">Release the hold</button>`
    : `<button type="button" class="btn small-btn ghost" onclick="return adminNatGateToggle191(true)">Turn the hold back on</button>`;
  return `<div class="panel nat-gate191" style="margin-top:10px">
    <div class="flex-between"><strong>National publishing hold</strong><span class="badge ${g.effectiveOn ? "info" : "ok"}">${g.effectiveOn ? "Holding" : "Released"}</span></div>
    <p class="small" style="margin:6px 0 10px">${esc(line)}</p>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">${btn}<span class="small muted">Turning the hold back on never pulls back a campaign that is already open.</span></div>
  </div>`;
}
function natSubmittedLabel191(c) {
  const raw = c.submittedAt || c.createdAt || "";
  const d = raw ? new Date(raw) : null;
  if (!d || Number.isNaN(d.getTime())) return "Submitted time not recorded";
  return `Submitted ${d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })} at ${d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`;
}
function adminNatQueueHtml191(queue) {
  return `<div class="panel nat-queue191" style="margin-top:10px">
    <div class="flex-between"><strong>Waiting for release</strong><span class="badge ${queue.length ? "info" : "ok"}">${queue.length ? natNoun(queue.length, "campaign") : "Clear"}</span></div>
    <p class="small muted" style="margin:6px 0 0">National campaigns a brand has published while the hold is on. Release one and it opens to approved creators with finished profiles. Send one back and it returns to the brand as a draft.</p>
    ${queue.length ? queue.map((c) => `<div class="nat-queue-row191">
      <div class="flex-between"><strong>${esc(c.brandName || "A national brand")}</strong><span class="badge info">Awaiting release</span></div>
      <p style="margin:6px 0 2px"><strong>${esc(c.title || "Untitled campaign")}</strong></p>
      <p class="small" style="margin:0 0 2px"><strong>What creators get:</strong> ${esc(c.whatYouGet || "")}</p>
      <p class="small muted" style="margin:0 0 10px">${esc(natSubmittedLabel191(c))}</p>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button type="button" class="btn small-btn" onclick="return adminNatRelease191('${c.id}')">Release</button>
        <button type="button" class="btn small-btn ghost" onclick="return adminNatSendBack191('${c.id}')">Send back</button>
      </div>
    </div>`).join("") : `<div class="nat-queue-empty191"><strong>Nothing is waiting.</strong><p class="small muted" style="margin:4px 0 0">When a national brand publishes while the hold is on, its campaign lands here first.</p></div>`}
  </div>`;
}
async function adminNatGateToggle191(on) {
  try { await api("POST", "/admin/national/publish-gate", { hold: !!on }); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function adminNatRelease191(id) {
  try { await api("POST", `/admin/national/campaigns/${id}/release`, {}); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function adminNatSendBack191(id) {
  const reason = prompt("What should the brand know or fix? This note shows on the brand's campaign list.");
  if (reason === null) return false;
  try { await api("POST", `/admin/national/campaigns/${id}/send-back`, { reason }); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function loadAdminNational178() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  el.innerHTML = `<p class="muted">Loading national accounts...</p>`;
  try {
    const d = await api("GET", "/admin/national");
    state.adminNational178 = d;
    const r = d.rollup || {};
    el.innerHTML = `
    <h3 style="margin-top:4px">National accounts</h3>
    <p class="small muted">Brands that reach creators in every market. These numbers live here only — national accounts never count toward any market's launch numbers.</p>
    <div class="panel"><strong>Roll-up:</strong> ${natNoun(r.accounts, "account")} (${r.verifiedAccounts || 0} verified) · ${natNoun(r.campaigns, "campaign")} (${Object.entries(r.campaignsByStatus || {}).map(([k, v]) => `${esc(k)} ${v}`).join(", ") || "none"}) · ${natNoun(r.hands, "hand")} · ${natNoun(r.picks, "pick")}</div>
    ${adminNatGateHtml191(d.gate || {})}
    ${adminNatQueueHtml191(d.releaseQueue || [])}
    ${(r.staleNoPicks || []).length ? `<div class="panel" style="margin-top:10px"><strong>Needs a close-out:</strong> ${r.staleNoPicks.map((s) => `${esc(s.title)} — deadline passed 14+ days ago, ${natNoun(s.handsWaiting, "hand")} still waiting. <button type="button" class="btn small-btn ghost" onclick="return adminNatCloseCampaign('${s.campaignId}')">Close it</button>`).join("<br>")}</div>` : ""}
    <div class="panel" style="margin-top:14px">
      <h4 style="margin-top:0">Create a national account</h4>
      <form onsubmit="return adminNatCreate(event)">
        <label class="nfld178"><span>Account email</span><input id="an-email" type="email" required></label>
        <label class="nfld178"><span>Business (legal) name</span><input id="an-bizname" required></label>
        <label class="nfld178"><span>Brand name (what creators see)</span><input id="an-brandname"></label>
        <label class="nfld178"><span>Website</span><input id="an-website" placeholder="https://brand.com" required></label>
        <label class="nfld178"><span>What they sell</span><textarea id="an-about" rows="2"></textarea></label>
        <label class="nfld178"><span>Logo address (optional)</span><input id="an-logo" placeholder="https://brand.com/logo.png"></label>
        <label class="nfld178"><span>Currency</span><select id="an-currency"><option>USD</option><option>GBP</option><option>CAD</option><option>NZD</option><option>EUR</option></select></label>
        <div class="nfld178"><span>Focus markets</span>${natMarketPickerHtml({ uid: "admin", inputClass: "an-focus", markets: d.markets || [], checked: [] })}</div>
        <button type="submit" class="btn">Create national account</button>
        <span class="small muted"> Lands as pending, on the founding list. Approve + activate it like any business, then verify the brand below. No email is sent automatically.</span>
      </form>
    </div>
    <h4 style="margin:18px 0 6px">Accounts</h4>
    ${(d.accounts || []).map((a) => `<div class="panel" style="margin-top:8px">
      <div class="flex-between"><strong>${esc(a.brandName)}</strong><span class="badge ${a.verified ? "ok" : "info"}">${a.verified ? "Verified brand" : "Not verified"}</span></div>
      <p class="small" style="margin:6px 0">${esc(a.email)} · ${a.website ? `<a href="${esc(a.website)}" target="_blank" rel="noopener">${esc(a.websiteHost || a.website)}</a>` : "no website"} · status ${esc(a.status)} · ${a.accessState === "active" ? "activated" : "founding list"} · market: National (sentinel) · no plan<br>Focus: ${esc((a.focusMarkets || []).join(", ") || "all markets")}</p>
      ${a.verified ? `<button type="button" class="btn small-btn ghost" onclick="return adminNatUnverify('${a.id}')">Remove verification</button>` : `<span style="display:inline-flex;gap:10px;flex-wrap:wrap;align-items:center"><label><input type="checkbox" id="anv-site-${a.id}"> Website resolves and belongs to the brand</label><label><input type="checkbox" id="anv-name-${a.id}"> Brand name matches the site</label><label><input type="checkbox" id="anv-store-${a.id}"> A real product or store exists there</label><button type="button" class="btn small-btn" onclick="return adminNatVerify('${a.id}')">Verify brand</button></span>`}
    </div>`).join("") || `<p class="muted">No national accounts yet.</p>`}
    <h4 style="margin:18px 0 6px">Convert a market business</h4>
    <p class="small muted">Only for a business with no offers yet. Conversion sets the sentinel market, clears the plan to none (the old plan is kept in the audit log), and removes any partner stamp.</p>
    <form onsubmit="return adminNatConvert(event)">
      <label class="nfld178"><span>Business account id (from Admin search)</span><input id="an-convert-id" required></label>
      <label class="nfld178"><span>Website (optional if already on file)</span><input id="an-convert-web"></label>
      <button type="submit" class="btn ghost">Convert to national</button>
    </form>
    <h4 style="margin:18px 0 6px">Campaigns</h4>
    ${(d.campaigns || []).map((c) => `<div class="panel" style="margin-top:8px">
      <div class="flex-between"><strong>${esc(c.title || "Untitled")}</strong><span class="badge info">${esc(c.status === "awaiting_release" ? "Awaiting release" : c.status)}</span></div>
      <p class="small" style="margin:6px 0">${esc(c.brandName || "")}${c.verified ? " · verified" : " · NOT verified"} · ${natNoun(c.handCount, "hand")} · ${c.pickedCount || 0}/${c.picksCount || 0} picked</p>
      ${c.status !== "closed" && c.status !== "completed" && c.status !== "cancelled" ? `<button type="button" class="btn small-btn ghost" onclick="return adminNatCloseCampaign('${c.id}')">Close campaign</button>` : ""}
      <span style="display:inline-flex;gap:6px;flex-wrap:wrap;align-items:center;margin-left:8px"><input id="anr-creator-${c.id}" placeholder="Creator id" style="max-width:150px"><input id="anr-orders-${c.id}" type="number" min="0" placeholder="Orders" style="max-width:90px"><input id="anr-rev-${c.id}" type="number" min="0" step="0.01" placeholder="Revenue" style="max-width:100px"><button type="button" class="btn small-btn ghost" onclick="return adminNatResults('${c.id}')">Enter store-reported results</button></span>
    </div>`).join("") || `<p class="muted">No national campaigns yet.</p>`}`;
    natMkSync("admin");
  } catch (e) { el.innerHTML = `<div class="error-box">${esc(e.message)}</div>`; }
}
async function adminNatCreate(ev) {
  ev.preventDefault();
  try {
    const d = await api("POST", "/admin/national/accounts", {
      email: document.getElementById("an-email").value,
      businessName: document.getElementById("an-bizname").value,
      brandName: document.getElementById("an-brandname").value,
      website: document.getElementById("an-website").value,
      about: document.getElementById("an-about").value,
      logoUrl: document.getElementById("an-logo").value,
      currency: document.getElementById("an-currency").value,
      focusMarkets: [...document.querySelectorAll(".an-focus:checked")].map((x) => x.value),
    });
    if (d.sameWebsiteWarning && d.sameWebsiteWarning.length) alert("Heads up: another national account already uses this website: " + d.sameWebsiteWarning.map((x) => x.brandName).join(", ") + ". The account was still created.");
    loadAdminNational178();
  } catch (e) { alert(e.message); }
  return false;
}
async function adminNatVerify(id) {
  const checklist = {
    websiteResolves: document.getElementById(`anv-site-${id}`).checked,
    nameMatches: document.getElementById(`anv-name-${id}`).checked,
    storeExists: document.getElementById(`anv-store-${id}`).checked,
  };
  try { await api("POST", `/admin/national/accounts/${id}/verify`, { checklist }); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function adminNatUnverify(id) {
  if (!confirm("Remove this brand's verification? Live campaigns stay live but flagged here; new publishes stop until it is verified again.")) return false;
  try { await api("POST", `/admin/national/accounts/${id}/verify`, { verified: false }); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function adminNatConvert(ev) {
  ev.preventDefault();
  const id = document.getElementById("an-convert-id").value.trim();
  if (!confirm("Convert this business to a national account? Its market becomes the National sentinel and its plan is cleared. This states what changes on the record.")) return false;
  try {
    await api("POST", `/admin/national/accounts/${id}/convert`, { website: document.getElementById("an-convert-web").value || undefined });
    loadAdminNational178();
  } catch (e) { alert(e.message); }
  return false;
}
async function adminNatCloseCampaign(id) {
  const note = prompt("Why is this campaign closing? The note goes to the business.") || "";
  try { await api("POST", `/admin/national/campaigns/${id}/close`, { note }); loadAdminNational178(); }
  catch (e) { alert(e.message); }
  return false;
}
async function adminNatResults(id) {
  const creatorId = document.getElementById(`anr-creator-${id}`).value.trim();
  if (!creatorId) { alert("Add the creator id first."); return false; }
  try {
    await api("POST", `/admin/national/campaigns/${id}/results`, {
      creatorId,
      ordersAttributed: document.getElementById(`anr-orders-${id}`).value === "" ? undefined : Number(document.getElementById(`anr-orders-${id}`).value),
      revenueAttributed: document.getElementById(`anr-rev-${id}`).value === "" ? undefined : Number(document.getElementById(`anr-rev-${id}`).value),
      resultNote: "Entered from the brand's store report.",
    });
    alert("Results saved. They show on the business's reports as reported by the brand's store.");
  } catch (e) { alert(e.message); }
  return false;
}
